-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261118000009_storage.sql
-- =============================================================================
-- 0009 STORAGE BUCKETS & POLICIES
--   product-images   PUBLIC   catalog images (admin upload)
--   site-assets      PUBLIC   logo, banners (admin upload)
--   payment-receipts PRIVATE  customer receipts (server upload; admin signed URLs)
--   printing-files   PRIVATE  customer documents (server upload; admin signed URLs)
-- Customer uploads never go directly from the browser to Storage: the Next.js
-- server validates type/size/magic bytes, then uploads with the service role.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('product-images',   'product-images',   true,  5242880,  array['image/jpeg', 'image/png', 'image/webp']),
  ('site-assets',      'site-assets',      true,  5242880,  array['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml']),
  ('payment-receipts', 'payment-receipts', false, 10485760, array['image/jpeg', 'image/png', 'application/pdf']),
  ('printing-files',   'printing-files',   false, 26214400, array[
     'application/pdf',
     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
     'application/msword', 'image/jpeg', 'image/png'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- Public buckets serve reads through the public CDN URL; listing/writes need policies.
create policy "product images: admin write" on storage.objects for insert to authenticated
  with check (bucket_id = 'product-images' and (select private.has_permission('products.manage')));
create policy "product images: admin update" on storage.objects for update to authenticated
  using (bucket_id = 'product-images' and (select private.has_permission('products.manage')));
create policy "product images: admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'product-images' and (select private.has_permission('products.manage')));

create policy "site assets: admin write" on storage.objects for insert to authenticated
  with check (bucket_id = 'site-assets' and ((select private.has_permission('settings.manage'))
                                            or (select private.has_permission('promotions.manage'))));
create policy "site assets: admin delete" on storage.objects for delete to authenticated
  using (bucket_id = 'site-assets' and ((select private.has_permission('settings.manage'))
                                       or (select private.has_permission('promotions.manage'))));

-- Private: read (=> signed URL creation) only for permitted staff. No anon access at all.
create policy "receipts: payment reviewers read" on storage.objects for select to authenticated
  using (bucket_id = 'payment-receipts' and (select private.has_permission('payments.view')));

create policy "printing files: printing staff read" on storage.objects for select to authenticated
  using (bucket_id = 'printing-files' and (select private.has_permission('printing.view')));
create policy "printing files: printing managers delete" on storage.objects for delete to authenticated
  using (bucket_id = 'printing-files' and (select private.has_permission('printing.manage')));

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261118000010_storefront.sql
-- =============================================================================
-- 0010 STOREFRONT SUPPORT
-- Replace the effective_price() computed field (it needs the whole row, which
-- conflicts with anon's column-level grants) with a stored generated column
-- that can be selected, sorted and indexed by the public catalog.
-- =============================================================================

drop function if exists public.effective_price(public.products);

alter table public.products
  add column effective_price_etb numeric(12,2)
  generated always as (coalesce(sale_price_etb, price_etb)) stored;

create index products_effective_price_idx on public.products(effective_price_etb)
  where status = 'active';
create index products_created_idx on public.products(created_at desc)
  where status = 'active';

grant select (effective_price_etb) on public.products to anon;

-- Fix: PostgreSQL regexes allow at most 255 repetitions, so the original
-- '{3,300}' check raised "invalid repetition count" on every insert.
alter table public.product_images drop constraint product_images_storage_path_check;
alter table public.product_images add constraint product_images_storage_path_check
  check (char_length(storage_path) between 3 and 300 and storage_path ~ '^[A-Za-z0-9/_.-]+$' and storage_path !~ '\.\.');

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261118000011_business_name.sql
-- Business name: "Abiye" (Amharic: አብዬ, confirmed by the owner).
-- Only replaces the original placeholder, so it never overwrites a name an
-- administrator has already set in /admin/settings.
update public.website_settings
   set value = jsonb_set(value, '{name}', jsonb_build_object('en', 'Abiye', 'am', 'አብዬ'))
 where key = 'business'
   and value #>> '{name,en}' = '[BUSINESS NAME]';

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261119000012_admin_dashboard.sql
-- =============================================================================
-- 0012 ADMIN DASHBOARD STATS
-- One permission-aware aggregate call for the dashboard. Every figure is
-- scoped to what the caller may see:
--   * revenue only with analytics.view (Super Admin by default)
--   * staff (orders.view_assigned without view_all) count only assigned orders
--   * stock / printing / payment figures only with the matching permission
-- Days are calendar days in Africa/Addis_Ababa.
-- =============================================================================
create or replace function public.admin_dashboard_stats(p_days integer default 14)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_all       boolean := private.has_permission('orders.view_all');
  v_assigned  boolean := private.has_permission('orders.view_assigned');
  v_revenue   boolean := private.has_permission('analytics.view');
  v_days      integer := greatest(1, least(coalesce(p_days, 14), 90));
  v_today     date := (now() at time zone 'Africa/Addis_Ababa')::date;
  v_result    jsonb;
begin
  perform private.require_permission('dashboard.view');

  with visible as (
    select o.* from public.orders o
    where v_all or (v_assigned and o.assigned_to = v_uid)
  )
  select jsonb_build_object(
    'orders_total', (select count(*) from visible),
    'orders_today', (select count(*) from visible where (created_at at time zone 'Africa/Addis_Ababa')::date = v_today),
    'awaiting_processing', (select count(*) from visible where status in ('confirmed', 'processing')),
    'awaiting_payment', (select count(*) from visible where status in ('awaiting_payment', 'payment_rejected')),
    'pending_payments', case when private.has_permission('payments.view')
        then (select count(*) from public.payment_submissions where status = 'pending') end,
    'products_active', case when private.has_permission('products.view')
        then (select count(*) from public.products where status = 'active') end,
    'low_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory
              and stock_quantity > 0 and stock_quantity <= low_stock_threshold) end,
    'out_of_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity = 0) end,
    'printing_open', case when private.has_permission('printing.view')
        then (select count(*) from public.printing_jobs where status not in ('completed', 'cancelled')) end,
    'revenue_verified_total', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified') end,
    'revenue_verified_period', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified'
              and (payment_verified_at at time zone 'Africa/Addis_Ababa')::date > v_today - v_days) end,
    'daily', (
      select jsonb_agg(jsonb_build_object(
               'day', d.day,
               'orders', (select count(*) from visible v where (v.created_at at time zone 'Africa/Addis_Ababa')::date = d.day),
               'revenue', case when v_revenue then (
                   select coalesce(sum(o.total_etb), 0) from public.orders o
                    where o.payment_status = 'verified'
                      and (o.payment_verified_at at time zone 'Africa/Addis_Ababa')::date = d.day) end)
             order by d.day)
      from (select generate_series(v_today - (v_days - 1), v_today, interval '1 day')::date as day) d
    )
  ) into v_result;
  return v_result;
end;
$$;
revoke execute on function public.admin_dashboard_stats(integer) from public, anon;
grant execute on function public.admin_dashboard_stats(integer) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261119000013_staff_management.sql
-- =============================================================================
-- 0013 STAFF MANAGEMENT
-- The auth account is created server-side with the secret key (Supabase Auth
-- admin API); the PROFILE (which grants admin access) is created through this
-- function under the inviting admin's own session, so the permission check and
-- the audit log record who granted access.
-- =============================================================================
create or replace function public.admin_create_staff_profile(p_user_id uuid, p_full_name text, p_role_key text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role smallint;
begin
  perform private.require_permission('staff.manage');
  select id into v_role from public.admin_roles where key = p_role_key;
  if not found then perform private.app_error('invalid_role'); end if;
  if not exists (select 1 from auth.users where id = p_user_id) then perform private.app_error('user_not_found'); end if;
  if exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('invalid_request', 'profile exists'); end if;
  if char_length(btrim(coalesce(p_full_name, ''))) not between 1 and 120 then perform private.app_error('invalid_name'); end if;
  insert into public.profiles (id, full_name, role_id, created_by)
  values (p_user_id, btrim(p_full_name), v_role, (select auth.uid()));
end;
$$;
revoke execute on function public.admin_create_staff_profile(uuid, text, text) from public, anon;
grant execute on function public.admin_create_staff_profile(uuid, text, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261119000014_printing_retention.sql
-- =============================================================================
-- 0014 PRINTING: file retention + admin file deletion
-- Customer documents are deleted after printing_jobs.files_delete_after
-- (set from the "retention_days" setting), but NEVER while the job is being
-- paid for or produced (payment_verification / printing / ready).
-- Storage objects are removed by server code; these functions keep the DB in sync.
-- =============================================================================

alter table public.printing_jobs
  add constraint printing_jobs_paper_size_check check (paper_size ~ '^[A-Za-z0-9]{1,10}$');

-- Cron worker (service_role): which stored files are due for deletion?
create or replace function public.printing_files_due_for_deletion(p_limit integer default 200)
returns table (file_id uuid, job_id uuid, storage_path text)
language sql
stable
security definer
set search_path = ''
as $$
  select f.id, f.job_id, f.storage_path
  from public.printing_files f
  join public.printing_jobs j on j.id = f.job_id
  where f.deleted_at is null
    and j.files_delete_after < now()
    and j.status not in ('payment_verification', 'printing', 'ready')
  order by j.files_delete_after
  limit greatest(1, least(coalesce(p_limit, 200), 1000))
$$;

-- Cron worker (service_role): record files whose storage objects were removed.
create or replace function public.mark_printing_files_deleted(p_file_ids uuid[])
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  update public.printing_files set deleted_at = now()
   where id = any(p_file_ids) and deleted_at is null;
  get diagnostics v_count = row_count;
  update public.printing_jobs j set files_deleted_at = now()
   where j.files_deleted_at is null
     and j.id in (select job_id from public.printing_files where id = any(p_file_ids))
     and not exists (select 1 from public.printing_files f where f.job_id = j.id and f.deleted_at is null);
  return v_count;
end;
$$;

-- Admin (printing.manage): mark a job's files deleted after removing them from Storage.
create or replace function public.admin_mark_printing_files_deleted(p_job_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_status public.print_job_status;
  v_ids uuid[];
begin
  perform private.require_permission('printing.manage');
  select status into v_status from public.printing_jobs where id = p_job_id;
  if not found then perform private.app_error('not_found'); end if;
  if v_status in ('payment_verification', 'printing', 'ready') then
    perform private.app_error('invalid_transition', 'files are needed for this job');
  end if;
  select array_agg(id) into v_ids from public.printing_files where job_id = p_job_id and deleted_at is null;
  perform private.audit('printing_files_deleted', 'printing_job', p_job_id::text, null,
                        jsonb_build_object('files', coalesce(array_length(v_ids, 1), 0)));
  return public.mark_printing_files_deleted(coalesce(v_ids, '{}'));
end;
$$;

revoke execute on function public.printing_files_due_for_deletion(integer) from public, anon, authenticated;
revoke execute on function public.mark_printing_files_deleted(uuid[]) from public, anon, authenticated;
revoke execute on function public.admin_mark_printing_files_deleted(uuid) from public, anon;
grant execute on function public.printing_files_due_for_deletion(integer) to service_role;
grant execute on function public.mark_printing_files_deleted(uuid[]) to service_role;
grant execute on function public.admin_mark_printing_files_deleted(uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261119000015_notifications_admin.sql
-- =============================================================================
-- 0015 NOTIFICATION ADMIN
-- notifications_outbox stays service_role-only at the table level; admins with
-- settings.manage get a read-only view of recent rows, can re-queue failed or
-- dead messages, and can queue a test message.
-- =============================================================================

create or replace function public.admin_notifications(p_limit integer default 50)
returns table (
  id bigint, event_type text, status public.notification_status, attempts integer, max_attempts integer,
  last_error text, created_at timestamptz, sent_at timestamptz, next_attempt_at timestamptz, reference text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return query
    select o.id, o.event_type, o.status, o.attempts, o.max_attempts, o.last_error, o.created_at, o.sent_at, o.next_attempt_at,
           coalesce(o.payload ->> 'order_number', o.payload ->> 'job_number', o.payload ->> 'label')
    from public.notifications_outbox o
    order by o.id desc
    limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;

create or replace function public.admin_retry_notification(p_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  update public.notifications_outbox
     set status = 'pending', attempts = 0, next_attempt_at = now(), locked_until = null, last_error = null
   where id = p_id and status in ('failed', 'dead');
  if not found then perform private.app_error('invalid_transition', 'only failed messages can be retried'); end if;
  perform private.audit('notification_retry', 'notification', p_id::text);
end;
$$;

create or replace function public.admin_queue_test_notification()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  perform private.enqueue_notification('test_message', 'test:' || gen_random_uuid(),
    jsonb_build_object('label', 'Test message', 'requested_by_role', private.current_role_key(), 'requested_at', now()));
end;
$$;

revoke execute on function public.admin_notifications(integer) from public, anon;
revoke execute on function public.admin_retry_notification(bigint) from public, anon;
revoke execute on function public.admin_queue_test_notification() from public, anon;
grant execute on function public.admin_notifications(integer) to authenticated;
grant execute on function public.admin_retry_notification(bigint) to authenticated;
grant execute on function public.admin_queue_test_notification() to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000016_customer_accounts.sql
-- =============================================================================
-- 0016 CUSTOMER ACCOUNTS (email + password, confirmed) — required to order
--   * customer_accounts: one row per signed-up user (auto-created on sign-up)
--   * orders.user_id / printing_jobs.user_id: who placed it
--   * New orders/printing jobs REQUIRE a confirmed account (DB-enforced):
--     only the *_for_user wrappers may create them, and a BEFORE INSERT
--     trigger refuses rows without a user.
--   * Customers can read their own orders (RLS); nothing else changes for
--     staff. Signing up never grants admin access (that needs public.profiles).
--   * Editable legal texts (terms / privacy) in website_settings.
-- =============================================================================

create table public.customer_accounts (
  id                uuid primary key references auth.users(id) on delete cascade,
  full_name         text check (char_length(full_name) <= 120),
  phone             text check (phone ~ '^\+251[79][0-9]{8}$'),
  accepted_terms_at timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create trigger customer_accounts_updated_at before update on public.customer_accounts
  for each row execute function private.set_updated_at();

alter table public.customer_accounts enable row level security;
revoke all on public.customer_accounts from anon, authenticated;
grant select on public.customer_accounts to authenticated;
grant update (full_name, phone) on public.customer_accounts to authenticated;
create policy customer_accounts_own_read on public.customer_accounts for select to authenticated
  using (id = (select auth.uid()));
create policy customer_accounts_own_update on public.customer_accounts for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy customer_accounts_staff_read on public.customer_accounts for select to authenticated
  using ((select private.has_permission('customers.view')));

-- Auto-create the account row on sign-up (name/terms from sign-up metadata).
create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.customer_accounts (id, full_name, accepted_terms_at)
  values (
    new.id,
    left(nullif(btrim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), ''), 120),
    case when (new.raw_user_meta_data ->> 'accepted_terms') = 'true' then now() end)
  on conflict (id) do nothing;
  return new;
end;
$$;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function private.handle_new_user();

-- Backfill accounts for existing users (e.g. staff) so every user has one row.
insert into public.customer_accounts (id) select id from auth.users on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Who placed it
-- ---------------------------------------------------------------------------
alter table public.orders add column user_id uuid references auth.users(id) on delete restrict;
create index orders_user_idx on public.orders(user_id, created_at desc) where user_id is not null;
alter table public.printing_jobs add column user_id uuid references auth.users(id) on delete restrict;
create index printing_jobs_user_idx on public.printing_jobs(user_id, created_at desc) where user_id is not null;

-- New rows must carry a user. The wrappers below pass it through a
-- transaction-local setting so the existing (tested) functions stay unchanged.
create or replace function private.require_ordering_user()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.user_id := coalesce(new.user_id, nullif(current_setting('app.ordering_user_id', true), '')::uuid);
  if new.user_id is null then
    raise exception using errcode = 'P0001', message = 'login_required';
  end if;
  return new;
end;
$$;
create trigger orders_require_user before insert on public.orders
  for each row execute function private.require_ordering_user();
create trigger printing_jobs_require_user before insert on public.printing_jobs
  for each row execute function private.require_ordering_user();

create or replace function private.assert_confirmed_user(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user_id is null or not exists (
    select 1 from auth.users where id = p_user_id and email_confirmed_at is not null
  ) then
    perform private.app_error('login_required');
  end if;
end;
$$;

create or replace function public.create_order_for_user(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner uuid;
  v_result jsonb;
begin
  perform private.assert_confirmed_user(p_user_id);
  -- An idempotent replay must come from the same account.
  select user_id into v_owner from public.orders where idempotency_key = (p_input ->> 'idempotency_key')::uuid;
  if found and v_owner is distinct from p_user_id then
    perform private.app_error('idempotency_conflict');
  end if;
  perform set_config('app.ordering_user_id', p_user_id::text, true);
  v_result := public.create_order(p_input);
  -- Clear immediately so nothing later in the same transaction inherits this user.
  perform set_config('app.ordering_user_id', '', true);
  return v_result;
end;
$$;

create or replace function public.create_printing_job_for_user(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_result jsonb;
begin
  perform private.assert_confirmed_user(p_user_id);
  perform set_config('app.ordering_user_id', p_user_id::text, true);
  v_result := public.create_printing_job(p_input);
  perform set_config('app.ordering_user_id', '', true);
  return v_result;
end;
$$;

-- Only the wrappers may create orders/printing jobs from now on.
revoke execute on function public.create_order(jsonb) from service_role;
revoke execute on function public.create_printing_job(jsonb) from service_role;
revoke execute on function public.create_order_for_user(uuid, jsonb) from public, anon, authenticated;
revoke execute on function public.create_printing_job_for_user(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.create_order_for_user(uuid, jsonb) to service_role;
grant execute on function public.create_printing_job_for_user(uuid, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- Customers read their own orders (in addition to the staff policies)
-- ---------------------------------------------------------------------------
create or replace function private.owns_order(p_order_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.orders o where o.id = p_order_id and o.user_id = (select auth.uid()))
$$;
grant execute on function private.owns_order(uuid) to authenticated;

create policy orders_customer_read on public.orders for select to authenticated
  using (user_id = (select auth.uid()));
create policy order_items_customer_read on public.order_items for select to authenticated
  using (private.owns_order(order_id));
create policy order_status_history_customer_read on public.order_status_history for select to authenticated
  using (private.owns_order(order_id));
create policy printing_jobs_customer_read on public.printing_jobs for select to authenticated
  using (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Editable legal texts (seeded from the reviewed draft; "approved" hides the draft banner)
-- ---------------------------------------------------------------------------
insert into public.website_settings (key, value, is_public)
values ('legal', '{"privacy":{"en":"## What we collect\n\nWhen you order, we collect your name, phone number, delivery city and address, delivery instructions, the products you order, your bank transaction reference and the payment receipt you upload. For printing services we also store the documents you upload.\n\n## Why we use it\n\nWe use this information only to process, verify, deliver and support your orders, and to contact you about them. We do not sell your information or use it for third-party advertising.\n\n## Payment receipts and documents\n\nReceipts and printing documents are stored privately. Only authorized {name} staff can open them. Printing documents are deleted automatically after the retention period shown on the printing page.\n\n## Who can see your data\n\nOnly staff who need it for your order. Our hosting providers (Vercel and Supabase) store data on our behalf under their security terms. Order notifications are sent to a private staff Telegram chat.\n\n## Your choices\n\nYou may ask us to correct or delete your information by contacting us, unless we must keep it to meet legal or accounting obligations.\n\n## Contact\n\nFor privacy questions, contact {name} using the details on our Contact page.","am":"## የምንሰበስበው መረጃ\n\nሲያዝዙ ስምዎን፣ ስልክ ቁጥርዎን፣ የማድረሻ ከተማና አድራሻዎን፣ የማድረሻ መመሪያዎን፣ ያዘዟቸውን ምርቶች፣ የባንክ ግብይት ማጣቀሻ ቁጥርዎን እና የሚጭኑትን የክፍያ ደረሰኝ እንሰበስባለን። ለህትመት አገልግሎት የሚጭኗቸውን ሰነዶችም እናስቀምጣለን።\n\n## ለምን እንጠቀምበታለን\n\nይህን መረጃ የምንጠቀመው ትዕዛዝዎን ለማስኬድ፣ ለማረጋገጥ፣ ለማድረስ እና ለመደገፍ እንዲሁም ስለ ትዕዛዝዎ ለማግኘትዎ ብቻ ነው። መረጃዎን አንሸጥም ወይም ለሶስተኛ ወገን ማስታወቂያ አንጠቀምበትም።\n\n## የክፍያ ደረሰኞች እና ሰነዶች\n\nደረሰኞች እና የህትመት ሰነዶች በግል ይቀመጣሉ። ሊከፍቷቸው የሚችሉት የተፈቀደላቸው የ{name} ሰራተኞች ብቻ ናቸው። የህትመት ሰነዶች በህትመት ገጹ ላይ ከተገለጸው የማቆያ ጊዜ በኋላ በራስ-ሰር ይሰረዛሉ።\n\n## መረጃዎን ማን ሊያይ ይችላል\n\nለትዕዛዝዎ የሚያስፈልጋቸው ሰራተኞች ብቻ። የማስተናገጃ አቅራቢዎቻችን (Vercel እና Supabase) በደህንነት ውሎቻቸው መሰረት መረጃን በእኛ ስም ያከማቻሉ። የትዕዛዝ ማሳወቂያዎች ወደ የግል የሰራተኞች ቴሌግራም ቡድን ይላካሉ።\n\n## የእርስዎ ምርጫዎች\n\nበህግ ወይም በሂሳብ ግዴታ ምክንያት ማቆየት ካላስፈለገን በስተቀር መረጃዎን እንድናስተካክል ወይም እንድንሰርዝ እኛን በማግኘት መጠየቅ ይችላሉ።\n\n## ያግኙን\n\nለግላዊነት ጥያቄዎች በ«ያግኙን» ገጻችን ላይ ባሉት አድራሻዎች {name}ን ያግኙ።"},"terms":{"en":"## Orders\n\nPlacing an order reserves the items for the payment window shown at checkout. If payment is not submitted in time, the order expires and the items are released.\n\n## Prices\n\nAll prices are in Ethiopian Birr (ETB). The price confirmed at checkout is the price you pay, even if our prices change later.\n\n## Payment\n\nWe accept bank transfer to the account shown at checkout. Your order is confirmed only after our team verifies the transfer in our bank account. A receipt image alone is not proof of payment. We may reject payments that cannot be verified; you can then resubmit.\n\n## Delivery and pickup\n\nDelivery fees depend on your city and are shown before you order. Delivery times are estimates. Pickup orders can be collected at our shop once marked ready.\n\n## Printing services\n\nPrinting prices are calculated from page count, copies, paper size, color and sides. Where we cannot count pages automatically, we send a quote before you pay. You are responsible for having the right to print the documents you upload.\n\n## Cancellations and returns\n\nContact us as soon as possible to cancel. Items must be returned unused and in original packaging, unless faulty. Hygiene-sensitive cosmetics cannot be returned once opened. Refunds for verified payments are made by bank transfer.\n\n## Contact\n\nQuestions about these terms: contact {name} using the details on our Contact page.","am":"## ትዕዛዞች\n\nትዕዛዝ ማስገባት ዕቃዎቹን በክፍያ ጊዜ ውስጥ ለእርስዎ ይይዛል። ክፍያ በጊዜው ካልገባ ትዕዛዙ ጊዜው ያልፍበታል እና ዕቃዎቹ ይለቀቃሉ።\n\n## ዋጋዎች\n\nሁሉም ዋጋዎች በኢትዮጵያ ብር ናቸው። በክፍያ ጊዜ የተረጋገጠው ዋጋ ዋጋችን ቢቀየርም የሚከፍሉት ዋጋ ነው።\n\n## ክፍያ\n\nበክፍያ ጊዜ ወደሚታየው ሂሳብ የሚደረግ የባንክ ዝውውር እንቀበላለን። ትዕዛዝዎ የሚረጋገጠው ቡድናችን ዝውውሩን በባንክ ሂሳባችን ካረጋገጠ በኋላ ብቻ ነው። የደረሰኝ ምስል ብቻውን የክፍያ ማረጋገጫ አይደለም። ሊረጋገጡ የማይችሉ ክፍያዎችን ውድቅ ልናደርግ እንችላለን፤ ከዚያ እንደገና ማስገባት ይችላሉ።\n\n## ማድረስ እና መውሰድ\n\nየማድረሻ ክፍያ በከተማዎ ላይ የተመሰረተ ሲሆን ከማዘዝዎ በፊት ይታያል። የማድረሻ ጊዜዎች ግምቶች ናቸው። የመውሰጃ ትዕዛዞች ዝግጁ ከተባሉ በኋላ ከሱቃችን ሊወሰዱ ይችላሉ።\n\n## የህትመት አገልግሎቶች\n\nየህትመት ዋጋ በገጽ ብዛት፣ በቅጂ፣ በወረቀት መጠን፣ በቀለም እና በገጽ ይሰላል። ገጾችን በራስ-ሰር መቁጠር በማንችልበት ጊዜ ከክፍያ በፊት የዋጋ ግምት እንልካለን። የሚጭኗቸውን ሰነዶች የማሳተም መብት እንዳለዎት ማረጋገጥ የእርስዎ ኃላፊነት ነው።\n\n## ስረዛ እና መመለስ\n\nለመሰረዝ በተቻለ ፍጥነት ያግኙን። ዕቃዎች ጉድለት ከሌለባቸው በስተቀር ያልተጠቀሙባቸው እና በመጀመሪያ ማሸጊያቸው መመለስ አለባቸው። ለንጽህና ስሜታዊ የሆኑ የውበት ምርቶች ከተከፈቱ በኋላ መመለስ አይችሉም። ለተረጋገጡ ክፍያዎች ተመላሽ በባንክ ዝውውር ይደረጋል።\n\n## ያግኙን\n\nስለ እነዚህ ውሎች ጥያቄዎች ካሉዎት በ«ያግኙን» ገጻችን ላይ ባሉት አድራሻዎች {name}ን ያግኙ።"},"approved":false}'::jsonb, true)
on conflict (key) do nothing;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000017_admin_customer_accounts.sql
-- =============================================================================
-- 0017 ADMIN: registered customer accounts
-- Emails live in auth.users (not exposed to the API). Staff holding
-- customers.view get them through these permission-checked functions only.
-- =============================================================================

create or replace function public.admin_customer_accounts(p_search text default null, p_limit integer default 100, p_user_id uuid default null)
returns table (
  id uuid, email text, full_name text, phone text, created_at timestamptz,
  email_confirmed_at timestamptz, last_sign_in_at timestamptz, is_staff boolean,
  order_count bigint, last_order_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('customers.view');
  return query
    select u.id, u.email::text, c.full_name, c.phone, u.created_at, u.email_confirmed_at, u.last_sign_in_at,
           exists (select 1 from public.profiles p where p.id = u.id) as is_staff,
           (select count(*) from public.orders o where o.user_id = u.id) as order_count,
           (select max(o.created_at) from public.orders o where o.user_id = u.id) as last_order_at
    from auth.users u
    left join public.customer_accounts c on c.id = u.id
    where (p_user_id is null or u.id = p_user_id)
      and (v_q is null
       or u.email ilike '%' || v_q || '%'
       or c.full_name ilike '%' || v_q || '%'
       or c.phone ilike '%' || v_q || '%')
    order by u.created_at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

revoke execute on function public.admin_customer_accounts(text, integer, uuid) from public, anon;
grant execute on function public.admin_customer_accounts(text, integer, uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000018_customer_account_management.sql
-- =============================================================================
-- 0018 CUSTOMER ACCOUNT MANAGEMENT
--   * customers.manage permission (Super Admin by default): reset password,
--     invite, deactivate / reactivate and delete customer accounts.
--     Staff accounts are never managed here (they live under Staff).
--   * Deactivation: recorded on customer_accounts and enforced in the database
--     (no new orders / printing jobs, no reading own data). The app also bans
--     the user in Supabase Auth so they cannot sign in.
--   * Customer activity timeline (admin actions, own profile changes, sign-in
--     events, orders, payments, printing jobs) and a global activity log.
--   * Saved baskets of signed-in customers + "stalled checkouts" (> N hours).
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('customers.manage', 'Reset passwords, invite, deactivate and delete customer accounts')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select id, 'customers.manage' from public.admin_roles where key = 'super_admin'
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Deactivation
-- ---------------------------------------------------------------------------
alter table public.customer_accounts
  add column deactivated_at      timestamptz,
  add column deactivated_by      uuid references auth.users(id) on delete set null,
  add column deactivation_reason text check (char_length(deactivation_reason) <= 500);

-- Is this user allowed to use their customer account? (not deactivated, not banned)
create or replace function private.is_active_user(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_user_id is not null
    and not exists (select 1 from public.customer_accounts c where c.id = p_user_id and c.deactivated_at is not null)
    and not exists (select 1 from auth.users u where u.id = p_user_id and u.banned_until is not null and u.banned_until > now())
$$;
create or replace function private.is_active_customer()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_active_user((select auth.uid()))
$$;
grant execute on function private.is_active_customer() to authenticated;

create or replace function private.assert_confirmed_user(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user_id is null or not exists (
    select 1 from auth.users where id = p_user_id and email_confirmed_at is not null
  ) then
    perform private.app_error('login_required');
  end if;
  if not private.is_active_user(p_user_id) then
    perform private.app_error('account_deactivated');
  end if;
end;
$$;

-- Deactivated customers lose access to their own data (staff policies unchanged).
create or replace function private.owns_order(p_order_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.orders o where o.id = p_order_id and o.user_id = (select auth.uid()))
     and private.is_active_customer()
$$;

drop policy orders_customer_read on public.orders;
create policy orders_customer_read on public.orders for select to authenticated
  using (user_id = (select auth.uid()) and (select private.is_active_customer()));
drop policy printing_jobs_customer_read on public.printing_jobs;
create policy printing_jobs_customer_read on public.printing_jobs for select to authenticated
  using (user_id = (select auth.uid()) and (select private.is_active_customer()));
drop policy customer_accounts_own_update on public.customer_accounts;
create policy customer_accounts_own_update on public.customer_accounts for update to authenticated
  using (id = (select auth.uid()) and (select private.is_active_customer()))
  with check (id = (select auth.uid()));

-- Customers' own name/phone changes go to the audit log (shown on their timeline).
create or replace function private.audit_customer_account_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (old.full_name, old.phone) is distinct from (new.full_name, new.phone) then
    perform private.audit('profile_updated', 'customer_account', new.id::text,
      jsonb_build_object('full_name', old.full_name, 'phone', old.phone),
      jsonb_build_object('full_name', new.full_name, 'phone', new.phone));
  end if;
  return new;
end;
$$;
create trigger audit_customer_accounts after update of full_name, phone on public.customer_accounts
  for each row execute function private.audit_customer_account_change();

-- Target must be an existing, non-staff account.
create or replace function private.assert_manageable_customer(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_user_id is null or not exists (select 1 from auth.users where id = p_user_id) then
    perform private.app_error('user_not_found');
  end if;
  if exists (select 1 from public.profiles where id = p_user_id) then
    perform private.app_error('cannot_manage_staff');
  end if;
end;
$$;

create or replace function public.admin_set_customer_active(p_user_id uuid, p_active boolean, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_before public.customer_accounts;
begin
  perform private.require_permission('customers.manage');
  perform private.assert_manageable_customer(p_user_id);
  if p_active is null then perform private.app_error('invalid_request'); end if;
  if not p_active and (v_reason is null or char_length(v_reason) > 500) then
    perform private.app_error('invalid_reason');
  end if;

  insert into public.customer_accounts (id) values (p_user_id) on conflict do nothing;
  select * into v_before from public.customer_accounts where id = p_user_id for update;
  if p_active = (v_before.deactivated_at is null) then
    return; -- already in that state
  end if;

  update public.customer_accounts
     set deactivated_at      = case when p_active then null else now() end,
         deactivated_by      = case when p_active then null else (select auth.uid()) end,
         deactivation_reason = case when p_active then null else v_reason end
   where id = p_user_id;

  perform private.audit(
    case when p_active then 'customer_reactivated' else 'customer_deactivated' end,
    'customer_account', p_user_id::text,
    jsonb_build_object('deactivated_at', v_before.deactivated_at, 'reason', v_before.deactivation_reason),
    null,
    jsonb_build_object('reason', v_reason));
end;
$$;

-- Records account actions performed through Supabase Auth by the app
-- (password reset email, invite, deletion) in the audit log.
create or replace function public.admin_log_customer_action(p_user_id uuid, p_action text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('customers.manage');
  if p_action not in ('password_reset_sent', 'invite_sent', 'customer_deleted') then
    perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 4000 then
    perform private.app_error('invalid_request');
  end if;
  if p_action = 'customer_deleted' then
    -- Logged after the auth user is gone.
    if p_user_id is null or exists (select 1 from auth.users where id = p_user_id) then
      perform private.app_error('invalid_request');
    end if;
  else
    perform private.assert_manageable_customer(p_user_id);
  end if;
  perform private.audit(p_action, 'customer_account', p_user_id::text,
    case when p_action = 'customer_deleted' then p_metadata end, null,
    case when p_action = 'customer_deleted' then '{}'::jsonb else p_metadata end);
end;
$$;

-- Checks a delete is allowed and returns a snapshot to keep in the audit log.
-- Accounts with orders or printing jobs are kept (history) — deactivate instead.
create or replace function public.admin_prepare_customer_delete(p_user_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v jsonb;
begin
  perform private.require_permission('customers.manage');
  perform private.assert_manageable_customer(p_user_id);
  if exists (select 1 from public.orders where user_id = p_user_id)
     or exists (select 1 from public.printing_jobs where user_id = p_user_id) then
    perform private.app_error('has_orders');
  end if;
  select jsonb_build_object('email', u.email, 'full_name', c.full_name, 'phone', c.phone,
                            'created_at', u.created_at, 'email_confirmed_at', u.email_confirmed_at)
    into v
    from auth.users u left join public.customer_accounts c on c.id = u.id
   where u.id = p_user_id;
  return v;
end;
$$;

-- Account list: now also returns the deactivation state.
drop function public.admin_customer_accounts(text, integer, uuid);
create function public.admin_customer_accounts(p_search text default null, p_limit integer default 100, p_user_id uuid default null)
returns table (
  id uuid, email text, full_name text, phone text, created_at timestamptz,
  email_confirmed_at timestamptz, last_sign_in_at timestamptz, is_staff boolean,
  order_count bigint, last_order_at timestamptz,
  deactivated_at timestamptz, deactivation_reason text, deactivated_by_name text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('customers.view');
  return query
    select u.id, u.email::text, c.full_name, c.phone, u.created_at, u.email_confirmed_at, u.last_sign_in_at,
           exists (select 1 from public.profiles p where p.id = u.id) as is_staff,
           (select count(*) from public.orders o where o.user_id = u.id) as order_count,
           (select max(o.created_at) from public.orders o where o.user_id = u.id) as last_order_at,
           c.deactivated_at, c.deactivation_reason,
           (select p.full_name from public.profiles p where p.id = c.deactivated_by)
    from auth.users u
    left join public.customer_accounts c on c.id = u.id
    where (p_user_id is null or u.id = p_user_id)
      and (v_q is null
       or u.email ilike '%' || v_q || '%'
       or c.full_name ilike '%' || v_q || '%'
       or c.phone ilike '%' || v_q || '%')
    order by u.created_at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

-- ---------------------------------------------------------------------------
-- Activity
-- ---------------------------------------------------------------------------
create or replace function private.actor_name(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.full_name from public.profiles p where p.id = p_user_id),
    (select c.full_name from public.customer_accounts c where c.id = p_user_id),
    (select u.email::text from auth.users u where u.id = p_user_id))
$$;

-- One customer's history, newest first.
--   kind: admin | account | auth | order | payment | printing
create or replace function public.admin_customer_activity(p_user_id uuid, p_limit integer default 200)
returns table (at timestamptz, kind text, action text, actor_name text, reference text, details jsonb)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_id text := p_user_id::text;
begin
  perform private.require_permission('customers.view');
  return query
  select * from (
    -- Admin actions and the customer's own profile changes
    select a.created_at, case when a.actor_id = p_user_id then 'account' else 'admin' end, a.action,
           private.actor_name(a.actor_id), null::text,
           jsonb_strip_nulls(jsonb_build_object('before', a.before_data, 'after', a.after_data,
             'metadata', nullif(a.metadata, '{}'::jsonb), 'actor_role', a.actor_role))
      from public.audit_logs a
     where a.entity_type = 'customer_account' and a.entity_id = v_id
    union all
    -- Supabase Auth events (sign-up, sign-in, password changes ...)
    select e.created_at, 'auth', e.payload ->> 'action',
           case when e.payload ->> 'actor_id' = v_id then null else nullif(e.payload ->> 'actor_username', '') end,
           null, jsonb_strip_nulls(jsonb_build_object('ip', nullif(e.ip_address, '')))
      from auth.audit_log_entries e
     where (e.payload ->> 'actor_id' = v_id or e.payload -> 'traits' ->> 'user_id' = v_id)
       and coalesce(e.payload ->> 'action', '') not in ('token_refreshed', 'token_revoked')
    union all
    select o.created_at, 'order', 'order_placed', null, o.order_number,
           jsonb_build_object('order_id', o.id, 'total_etb', o.total_etb, 'status', o.status)
      from public.orders o where o.user_id = p_user_id
    union all
    select h.created_at, 'order', 'order_status', private.actor_name(h.changed_by), o.order_number,
           jsonb_strip_nulls(jsonb_build_object('order_id', o.id, 'from', h.from_status, 'to', h.to_status, 'note', h.note))
      from public.order_status_history h join public.orders o on o.id = h.order_id
     where o.user_id = p_user_id and h.from_status is not null
    union all
    select s.submitted_at, 'payment', 'payment_submitted', null, o.order_number,
           jsonb_build_object('order_id', o.id, 'amount_etb', s.amount_expected_etb)
      from public.payment_submissions s join public.orders o on o.id = s.order_id
     where o.user_id = p_user_id
    union all
    select s.reviewed_at, 'payment', 'payment_' || s.status::text, private.actor_name(s.reviewed_by), o.order_number,
           jsonb_strip_nulls(jsonb_build_object('order_id', o.id, 'note', s.review_note))
      from public.payment_submissions s join public.orders o on o.id = s.order_id
     where o.user_id = p_user_id and s.reviewed_at is not null
    union all
    select j.created_at, 'printing', 'printing_submitted', null, j.job_number,
           jsonb_strip_nulls(jsonb_build_object('job_id', j.id, 'status', j.status, 'total_etb', j.total_etb))
      from public.printing_jobs j where j.user_id = p_user_id
  ) t (at, kind, action, actor_name, reference, details)
  order by t.at desc
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
end;
$$;

-- Every critical change across the system (audit log) with actor names.
create or replace function public.admin_activity_log(
  p_entity_type text default null, p_search text default null,
  p_limit integer default 100, p_before_id bigint default null)
returns table (
  id bigint, created_at timestamptz, actor_id uuid, actor_name text, actor_role text,
  action text, entity_type text, entity_id text, entity_label text,
  before_data jsonb, after_data jsonb, metadata jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('audit.view');
  return query
    select a.id, a.created_at, a.actor_id, private.actor_name(a.actor_id), a.actor_role,
           a.action, a.entity_type, a.entity_id,
           case a.entity_type
             when 'order' then (select o.order_number from public.orders o where o.id::text = a.entity_id)
             when 'printing_job' then (select j.job_number from public.printing_jobs j where j.id::text = a.entity_id)
             when 'customer_account' then coalesce(
               (select u.email::text from auth.users u where u.id::text = a.entity_id), a.before_data ->> 'email')
             when 'profiles' then private.actor_name(case when a.entity_id ~ '^[0-9a-f-]{36}$' then a.entity_id::uuid end)
             when 'products' then coalesce(a.after_data ->> 'name_en', a.before_data ->> 'name_en')
             else null
           end,
           a.before_data, a.after_data, a.metadata
      from public.audit_logs a
     where (p_entity_type is null or a.entity_type = p_entity_type)
       and (p_before_id is null or a.id < p_before_id)
       and (v_q is null or a.action ilike '%' || v_q || '%' or a.entity_id ilike '%' || v_q || '%'
            or private.actor_name(a.actor_id) ilike '%' || v_q || '%')
     order by a.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

-- ---------------------------------------------------------------------------
-- Saved baskets (signed-in customers) and stalled checkouts
-- ---------------------------------------------------------------------------
create or replace function private.valid_cart_items(p jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select jsonb_typeof(p) = 'array' and jsonb_array_length(p) <= 50
     and not exists (
       select 1 from jsonb_array_elements(p) e
        where jsonb_typeof(e) <> 'object'
           or coalesce(e ->> 'product_id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           or jsonb_typeof(e -> 'quantity') <> 'number'
           or (e ->> 'quantity') !~ '^[0-9]{1,3}$'
           or (e ->> 'quantity')::int not between 1 and 999)
$$;

grant execute on function private.valid_cart_items(jsonb) to authenticated, service_role;

create table public.customer_carts (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  items      jsonb not null default '[]'::jsonb check (private.valid_cart_items(items)),
  item_count integer not null default 0,
  updated_at timestamptz not null default now()
);
create index customer_carts_stalled_idx on public.customer_carts(updated_at) where item_count > 0;

create or replace function private.customer_carts_touch()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.item_count := coalesce((select sum((e ->> 'quantity')::int) from jsonb_array_elements(new.items) e), 0);
  new.updated_at := now();
  return new;
end;
$$;
create trigger customer_carts_touch before insert or update on public.customer_carts
  for each row execute function private.customer_carts_touch();

alter table public.customer_carts enable row level security;
revoke all on public.customer_carts from anon, authenticated;
grant select, delete on public.customer_carts to authenticated;
-- update(user_id) is needed by upsert; the policies pin user_id to the caller.
grant insert (user_id, items), update (user_id, items) on public.customer_carts to authenticated;
create policy customer_carts_own_read on public.customer_carts for select to authenticated
  using (user_id = (select auth.uid()));
create policy customer_carts_own_insert on public.customer_carts for insert to authenticated
  with check (user_id = (select auth.uid()) and (select private.is_active_customer()));
create policy customer_carts_own_update on public.customer_carts for update to authenticated
  using (user_id = (select auth.uid()) and (select private.is_active_customer()))
  with check (user_id = (select auth.uid()));
create policy customer_carts_own_delete on public.customer_carts for delete to authenticated
  using (user_id = (select auth.uid()));

-- A successful order empties the saved basket.
create or replace function public.create_order_for_user(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner uuid;
  v_result jsonb;
begin
  perform private.assert_confirmed_user(p_user_id);
  -- An idempotent replay must come from the same account.
  select user_id into v_owner from public.orders where idempotency_key = (p_input ->> 'idempotency_key')::uuid;
  if found and v_owner is distinct from p_user_id then
    perform private.app_error('idempotency_conflict');
  end if;
  perform set_config('app.ordering_user_id', p_user_id::text, true);
  v_result := public.create_order(p_input);
  -- Clear immediately so nothing later in the same transaction inherits this user.
  perform set_config('app.ordering_user_id', '', true);
  delete from public.customer_carts where user_id = p_user_id;
  return v_result;
end;
$$;

-- Customers who started but did not finish (older than p_hours):
--   unpaid_order    order placed, no payment submitted (or payment rejected)
--   unpaid_printing printing job priced, not paid
--   basket          items saved in the basket, no order placed
create or replace function public.admin_stalled_checkouts(p_hours integer default 2)
returns table (
  kind text, since timestamptz, user_id uuid, email text, full_name text, phone text,
  reference text, entity_id uuid, amount_etb numeric, item_count integer, status text, items jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_cutoff timestamptz := now() - make_interval(hours => greatest(1, least(coalesce(p_hours, 2), 720)));
begin
  perform private.require_permission('customers.view');
  return query
  select * from (
    select 'unpaid_order'::text, o.updated_at, o.user_id, u.email::text, coalesce(c.full_name, o.customer_name),
           coalesce(c.phone, o.customer_phone), o.order_number, o.id, o.total_etb,
           (select coalesce(sum(i.quantity), 0)::int from public.order_items i where i.order_id = o.id),
           o.status::text, null::jsonb
      from public.orders o
      left join auth.users u on u.id = o.user_id
      left join public.customer_accounts c on c.id = o.user_id
     where o.status in ('awaiting_payment', 'payment_rejected') and o.updated_at < v_cutoff
    union all
    select 'unpaid_printing', j.updated_at, j.user_id, u.email::text, coalesce(c.full_name, j.customer_name),
           coalesce(c.phone, j.customer_phone), j.job_number, j.id, j.total_etb, j.copies,
           j.status::text, null::jsonb
      from public.printing_jobs j
      left join auth.users u on u.id = j.user_id
      left join public.customer_accounts c on c.id = j.user_id
     where j.status = 'awaiting_payment' and j.order_id is null and j.updated_at < v_cutoff
    union all
    select 'basket', k.updated_at, k.user_id, u.email::text, c.full_name, c.phone, null, null,
           (select sum(coalesce(p.sale_price_etb, p.price_etb) * (e ->> 'quantity')::int)
              from jsonb_array_elements(k.items) e join public.products p on p.id = (e ->> 'product_id')::uuid),
           k.item_count, null,
           (select jsonb_agg(jsonb_build_object('name', coalesce(p.name_en, '?'), 'quantity', (e ->> 'quantity')::int))
              from jsonb_array_elements(k.items) e left join public.products p on p.id = (e ->> 'product_id')::uuid)
      from public.customer_carts k
      join auth.users u on u.id = k.user_id
      left join public.customer_accounts c on c.id = k.user_id
     where k.item_count > 0 and k.updated_at < v_cutoff and k.updated_at > now() - interval '30 days'
       and private.is_active_user(k.user_id)
  ) t
  order by 2 desc
  limit 500;
end;
$$;

