    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000030_pickup_cleanup_and_receipt_archive.sql
-- =============================================================================
-- 0030 (1) Printing documents are deleted once the job is picked up (Completed).
--      (2) Payment receipts are archived by email when verified or rejected.
-- =============================================================================

-- (1) Completed = picked up: the files are due for deletion immediately. The app removes them
-- right away; if that fails, the daily storage maintenance job removes them.
create or replace function private.printing_files_due_on_pickup()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' then
    new.files_delete_after := now();
  end if;
  return new;
end;
$$;
drop trigger if exists printing_jobs_files_due_on_pickup on public.printing_jobs;
create trigger printing_jobs_files_due_on_pickup before update of status on public.printing_jobs
  for each row execute function private.printing_files_due_on_pickup();

-- Due "now" means now (inclusive).
create or replace function public.printing_files_due_for_deletion(p_limit integer default 200)
returns table (file_id uuid, job_id uuid, storage_path text)
language sql
stable
security definer
set search_path = ''
as $$
  select f.id, f.job_id, f.storage_path
  from public.printing_files f
  join public.printing_jobs j on j.id = f.job_id
  where f.deleted_at is null
    and j.files_delete_after <= now()
    and j.status not in ('payment_verification', 'printing', 'ready')
  order by j.files_delete_after
  limit greatest(1, least(coalesce(p_limit, 200), 1000))
$$;

-- Jobs completed earlier: their files are due now too.
update public.printing_jobs set files_delete_after = now()
 where status = 'completed' and files_deleted_at is null and (files_delete_after is null or files_delete_after > now());

-- (2) Receipt archive ---------------------------------------------------------
alter table public.notifications_outbox drop constraint notifications_outbox_channel_check;
alter table public.notifications_outbox add constraint notifications_outbox_channel_check check (channel in ('telegram', 'email', 'push', 'archive'));
-- Archive emails go to the business's archive address, not to a customer.
alter table public.notifications_outbox drop constraint notifications_outbox_email_recipient;
alter table public.notifications_outbox add constraint notifications_outbox_email_recipient
  check (channel in ('telegram', 'archive') or recipient_user_id is not null);

-- Archive address: private setting (never public), changed only through admin_set_receipt_archive.
create or replace function public.admin_set_receipt_archive(p_email text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text := nullif(lower(btrim(coalesce(p_email, ''))), '');
  v_old text := private.setting('receipt_archive') ->> 'email';
begin
  perform private.require_permission('settings.manage');
  if v_email is not null and (length(v_email) > 254 or v_email !~ '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$') then
    perform private.app_error('invalid_request', 'email');
  end if;
  insert into public.website_settings (key, value, is_public, updated_by)
  values ('receipt_archive', jsonb_build_object('email', v_email), false, auth.uid())
  on conflict (key) do update set value = excluded.value, is_public = false, updated_by = excluded.updated_by;
  perform private.audit('receipt_archive_set', 'website_settings', 'receipt_archive',
                        jsonb_build_object('email', v_old), jsonb_build_object('email', v_email));
end;
$$;

create or replace function private.archive_payment_receipt(p_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, attachment_bucket, attachment_path, max_attempts)
  select 'archive', 'receipt_archive', 'archive:payment:' || s.id || ':' || s.status,
         jsonb_build_object(
           'kind', 'order_payment', 'result', s.status, 'number', o.order_number, 'amount_etb', s.amount_expected_etb,
           'order_total_etb', o.total_etb, 'reference', s.transaction_reference, 'customer_name', o.customer_name,
           'customer_phone', o.customer_phone, 'customer_email', u.email::text,
           'bank_name', o.bank_snapshot ->> 'bank_name', 'account_number', o.bank_snapshot ->> 'account_number',
           'submitted_at', s.submitted_at, 'decided_at', s.reviewed_at, 'decided_by', private.actor_name(s.reviewed_by),
           'reason', s.review_note, 'receipt_name', s.receipt_original_name, 'receipt_mime', s.receipt_mime, 'receipt_sha256', s.receipt_sha256),
         'payment-receipts', s.receipt_path, 20
    from public.payment_submissions s
    join public.orders o on o.id = s.order_id
    left join auth.users u on u.id = o.user_id
   where s.id = p_id and s.status::text in ('verified', 'rejected')
     and private.setting('receipt_archive') ->> 'email' is not null
  on conflict (dedupe_key) do nothing;
$$;

create or replace function private.archive_topup_receipt(p_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, attachment_bucket, attachment_path, max_attempts)
  select 'archive', 'receipt_archive', 'archive:topup:' || t.id || ':' || t.status,
         jsonb_build_object(
           'kind', 'wallet_topup', 'result', t.status, 'number', t.topup_number, 'amount_etb', t.amount_etb,
           'reference', t.transaction_reference, 'customer_name', a.full_name, 'customer_phone', a.phone, 'customer_email', u.email::text,
           'bank_name', t.bank_snapshot ->> 'bank_name', 'account_number', t.bank_snapshot ->> 'account_number',
           'submitted_at', t.created_at, 'decided_at', t.reviewed_at, 'decided_by', private.actor_name(t.reviewed_by),
           'reason', t.review_note, 'receipt_mime', t.receipt_mime, 'receipt_sha256', t.receipt_sha256),
         'payment-receipts', t.receipt_path, 20
    from public.wallet_topups t
    left join public.customer_accounts a on a.id = t.user_id
    left join auth.users u on u.id = t.user_id
   where t.id = p_id and t.status in ('verified', 'rejected')
     and private.setting('receipt_archive') ->> 'email' is not null
  on conflict (dedupe_key) do nothing;
$$;

-- Queued in the same transaction as the decision.
create or replace function private.archive_on_payment_decision()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status::text in ('verified', 'rejected') and old.status::text is distinct from new.status::text then
    if tg_table_name = 'payment_submissions' then perform private.archive_payment_receipt(new.id);
    else perform private.archive_topup_receipt(new.id);
    end if;
  end if;
  return null;
end;
$$;
drop trigger if exists payment_submissions_archive on public.payment_submissions;
create trigger payment_submissions_archive after update of status on public.payment_submissions
  for each row execute function private.archive_on_payment_decision();
drop trigger if exists wallet_topups_archive on public.wallet_topups;
create trigger wallet_topups_archive after update of status on public.wallet_topups
  for each row execute function private.archive_on_payment_decision();

-- Send receipts decided before the archive was set up (or in a period). Duplicates are skipped.
create or replace function public.admin_archive_past_receipts(p_from timestamptz, p_to timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_before integer;
  v_after integer;
begin
  perform private.require_permission('settings.manage');
  if p_from is null or p_to is null or p_to <= p_from then perform private.app_error('invalid_request'); end if;
  if private.setting('receipt_archive') ->> 'email' is null then perform private.app_error('invalid_request', 'archive_not_set'); end if;
  select count(*) into v_before from public.notifications_outbox where channel = 'archive';
  perform private.archive_payment_receipt(s.id) from public.payment_submissions s
   where s.status::text in ('verified', 'rejected') and s.reviewed_at >= p_from and s.reviewed_at < p_to;
  perform private.archive_topup_receipt(t.id) from public.wallet_topups t
   where t.status in ('verified', 'rejected') and t.reviewed_at >= p_from and t.reviewed_at < p_to;
  select count(*) into v_after from public.notifications_outbox where channel = 'archive';
  perform private.audit('receipt_archive_backfill', 'website_settings', 'receipt_archive', null, null,
                        jsonb_build_object('from', p_from, 'to', p_to, 'queued', v_after - v_before));
  return v_after - v_before;
end;
$$;

-- Admin overview of the archive (settings.manage).
create or replace function public.admin_receipt_archive_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return jsonb_build_object(
    'email', private.setting('receipt_archive') ->> 'email',
    'sent', (select count(*) from public.notifications_outbox where channel = 'archive' and status = 'sent'),
    'waiting', (select count(*) from public.notifications_outbox where channel = 'archive' and status in ('pending', 'processing', 'failed')),
    'dead', (select count(*) from public.notifications_outbox where channel = 'archive' and status = 'dead'),
    'last_sent_at', (select max(sent_at) from public.notifications_outbox where channel = 'archive'),
    'last_error', (select last_error from public.notifications_outbox where channel = 'archive' and last_error is not null order by id desc limit 1));
end;
$$;

-- Worker (service_role): the current archive address.
create or replace function public.receipt_archive_email()
returns text
language sql
stable
security definer
set search_path = ''
as $$ select private.setting('receipt_archive') ->> 'email' $$;

-- Notifications list: show the order / top-up number of archive emails too.
create or replace function public.admin_notifications(p_limit integer default 50)
returns table (
  id bigint, event_type text, status public.notification_status, attempts integer, max_attempts integer,
  last_error text, created_at timestamptz, sent_at timestamptz, next_attempt_at timestamptz, reference text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return query
    select o.id, o.event_type, o.status, o.attempts, o.max_attempts, o.last_error, o.created_at, o.sent_at, o.next_attempt_at,
           coalesce(o.payload ->> 'order_number', o.payload ->> 'job_number', o.payload ->> 'number', o.payload ->> 'label')
    from public.notifications_outbox o
    order by o.id desc
    limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;

revoke all on function public.admin_set_receipt_archive(text) from public, anon;
revoke all on function public.admin_archive_past_receipts(timestamptz, timestamptz) from public, anon;
revoke all on function public.admin_receipt_archive_status() from public, anon;
revoke all on function public.receipt_archive_email() from public, anon, authenticated;
revoke all on function private.archive_payment_receipt(uuid) from public;
revoke all on function private.archive_topup_receipt(uuid) from public;
grant execute on function public.admin_set_receipt_archive(text) to authenticated;
grant execute on function public.admin_archive_past_receipts(timestamptz, timestamptz) to authenticated;
grant execute on function public.admin_receipt_archive_status() to authenticated;
grant execute on function public.receipt_archive_email() to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000031_stock_alerts.sql
-- =============================================================================
-- 0031 STOCK ALERTS
--  * Staff: a Telegram + email alert when an active product reaches its low-stock level
--    and when it sells out (once per crossing, queued with the stock change).
--  * Customers: "Notify me when available" on out-of-stock products; email + phone
--    notification when it is back in stock (once per request).
-- =============================================================================

create table public.stock_alerts (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid not null references public.products(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  created_at  timestamptz not null default now(),
  notified_at timestamptz
);
create unique index stock_alerts_open_uq on public.stock_alerts(product_id, user_id) where notified_at is null;
create index stock_alerts_user_idx on public.stock_alerts(user_id, created_at desc);

alter table public.stock_alerts enable row level security;
revoke all on public.stock_alerts from anon, authenticated;
grant select on public.stock_alerts to authenticated;
-- Customers see their own requests; staff who manage stock see all (counts per product).
create policy stock_alerts_own_read on public.stock_alerts for select to authenticated
  using (user_id = (select auth.uid()) or (select private.has_permission('inventory.manage')));
-- Changes only through the functions below.

-- Customer: ask to be told when an out-of-stock product is available again.
create or replace function public.request_stock_alert(p_product_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_p public.products;
begin
  perform private.assert_confirmed_user(v_uid); -- signed in, confirmed, active, not staff
  select * into v_p from public.products where id = p_product_id and status = 'active';
  if not found then perform private.app_error('not_found'); end if;
  if not v_p.track_inventory or v_p.stock_quantity > 0 then perform private.app_error('invalid_request', 'in_stock'); end if;
  if (select count(*) from public.stock_alerts where user_id = v_uid and notified_at is null) >= 50 then
    perform private.app_error('rate_limited');
  end if;
  insert into public.stock_alerts (product_id, user_id) values (p_product_id, v_uid)
  on conflict (product_id, user_id) where notified_at is null do nothing;
end;
$$;

create or replace function public.cancel_stock_alert(p_product_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.stock_alerts where product_id = p_product_id and user_id = (select auth.uid()) and notified_at is null;
$$;

-- Staff who should get stock emails: active staff whose role can manage inventory.
create or replace function private.stock_alert_recipients()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.id from public.profiles p
    join public.role_permissions rp on rp.role_id = p.role_id and rp.permission_key = 'inventory.manage'
   where p.is_active
$$;

create or replace function private.stock_level_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
  v_key text := new.id || ':' || txid_current();
  v_payload jsonb;
begin
  if not new.track_inventory then return null; end if;
  v_payload := jsonb_build_object('product_id', new.id, 'name', new.name_en, 'name_am', new.name_am, 'sku', new.sku, 'slug', new.slug,
                                  'stock', new.stock_quantity, 'threshold', new.low_stock_threshold);

  -- Staff: crossed down into "low" or sold out (active products only).
  if new.status = 'active' then
    if new.stock_quantity = 0 and old.stock_quantity > 0 then v_event := 'out_of_stock';
    elsif new.stock_quantity <= new.low_stock_threshold and old.stock_quantity > new.low_stock_threshold then v_event := 'low_stock';
    end if;
    if v_event is not null then
      perform private.enqueue_notification(v_event, v_event || ':' || v_key, v_payload);
      insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, recipient_user_id, max_attempts)
      select 'email', 'staff_' || v_event, 'staff_' || v_event || ':' || v_key || ':' || r, v_payload, r, 6
        from private.stock_alert_recipients() r
      on conflict (dedupe_key) do nothing;
    end if;
  end if;

  -- Customers: back in stock.
  if new.status = 'active' and new.stock_quantity > 0 and old.stock_quantity = 0 then
    perform private.enqueue_customer_email('customer_back_in_stock', 'back_in_stock:' || a.id, a.user_id, v_payload)
       from public.stock_alerts a
      where a.product_id = new.id and a.notified_at is null and private.is_active_user(a.user_id);
    update public.stock_alerts set notified_at = now() where product_id = new.id and notified_at is null;
  end if;
  return null;
end;
$$;
create trigger products_stock_alerts after update of stock_quantity, status on public.products
  for each row when (old.stock_quantity is distinct from new.stock_quantity or old.status is distinct from new.status)
  execute function private.stock_level_changed();

-- Admin menu badge / overview.
create or replace function public.admin_low_stock_count()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select case when private.has_permission('inventory.manage') then
    (select count(*)::int from public.products where track_inventory and status = 'active' and stock_quantity <= low_stock_threshold)
  else 0 end
$$;

revoke all on function public.request_stock_alert(uuid) from public, anon;
revoke all on function public.cancel_stock_alert(uuid) from public, anon;
revoke all on function public.admin_low_stock_count() from public, anon;
revoke all on function private.stock_alert_recipients() from public;
grant execute on function public.request_stock_alert(uuid) to authenticated;
grant execute on function public.cancel_stock_alert(uuid) to authenticated;
grant execute on function public.admin_low_stock_count() to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000032_product_reviews.sql
-- =============================================================================
-- 0032 PRODUCT REVIEWS
--   Customers who received a product (order completed) rate it 1–5 with an optional
--   comment. Reviews appear only after a Super Admin / Manager approves them.
--   Public sees: rating, comment, first name + initial, date. Never email or order.
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('reviews.manage', 'Approve or reject product reviews')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select id, 'reviews.manage' from public.admin_roles where key in ('super_admin', 'manager')
on conflict do nothing;

alter table public.products
  add column rating_avg numeric(2,1) check (rating_avg between 1 and 5),
  add column rating_count integer not null default 0 check (rating_count >= 0);
grant select (rating_avg, rating_count) on public.products to anon;

create table public.product_reviews (
  id           uuid primary key default gen_random_uuid(),
  product_id   uuid not null references public.products(id) on delete cascade,
  user_id      uuid not null references auth.users(id) on delete cascade,
  order_id     uuid references public.orders(id) on delete set null,
  rating       smallint not null check (rating between 1 and 5),
  body         text check (char_length(body) <= 1000),
  display_name text not null check (char_length(display_name) between 1 and 40),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  review_note  text check (char_length(review_note) <= 500),
  reviewed_by  uuid references auth.users(id) on delete set null,
  reviewed_at  timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (product_id, user_id)
);
create index product_reviews_product_idx on public.product_reviews(product_id, created_at desc) where status = 'approved';
create index product_reviews_pending_idx on public.product_reviews(created_at) where status = 'pending';
create trigger product_reviews_updated_at before update on public.product_reviews
  for each row execute function private.set_updated_at();

alter table public.product_reviews enable row level security;
revoke all on public.product_reviews from anon, authenticated;
-- Public: approved reviews, safe columns only. Everything else goes through the functions below.
grant select (id, product_id, rating, body, display_name, created_at) on public.product_reviews to anon, authenticated;
create policy product_reviews_public_read on public.product_reviews for select to anon, authenticated
  using (status = 'approved');

-- "Mekdes Alemu" → "Mekdes A."
create or replace function private.review_display_name(p_user uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(nullif(left(
           split_part(btrim(regexp_replace(coalesce(a.full_name, ''), '\s+', ' ', 'g')), ' ', 1)
           || coalesce(' ' || nullif(left(split_part(btrim(regexp_replace(coalesce(a.full_name, ''), '\s+', ' ', 'g')), ' ', 2), 1), '') || '.', ''),
         40), ''), 'Customer')
    from (select 1) x left join public.customer_accounts a on a.id = p_user
$$;

-- The completed order through which the customer received this product (null = not eligible).
create or replace function private.review_order(p_user uuid, p_product uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select o.id from public.orders o join public.order_items i on i.order_id = o.id
   where o.user_id = p_user and i.product_id = p_product and o.status = 'completed'
   order by o.created_at desc limit 1
$$;

-- Signed-in customer: may I review this product, and what did I write?
create or replace function public.my_product_review(p_product_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  r public.product_reviews;
begin
  if v_uid is null then return jsonb_build_object('eligible', false); end if;
  select * into r from public.product_reviews where product_id = p_product_id and user_id = v_uid;
  return jsonb_build_object(
    'eligible', private.is_active_user(v_uid) and not exists (select 1 from public.profiles where id = v_uid)
                and private.review_order(v_uid, p_product_id) is not null,
    'review', case when r.id is null then null else jsonb_build_object('rating', r.rating, 'body', r.body, 'status', r.status, 'note', r.review_note) end);
end;
$$;

create or replace function public.submit_product_review(p_product_id uuid, p_rating integer, p_body text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_order uuid;
  v_body text := nullif(btrim(regexp_replace(coalesce(p_body, ''), '[\r\n]{3,}', E'\n\n', 'g')), '');
begin
  perform private.assert_confirmed_user(v_uid);
  if p_rating is null or p_rating not between 1 and 5 then perform private.app_error('invalid_request', 'rating'); end if;
  if v_body is not null and char_length(v_body) > 1000 then perform private.app_error('invalid_request', 'body'); end if;
  v_order := private.review_order(v_uid, p_product_id);
  if v_order is null then perform private.app_error('forbidden', 'not_purchased'); end if;
  if (select count(*) from public.product_reviews where user_id = v_uid and updated_at > now() - interval '1 day') >= 20 then
    perform private.app_error('rate_limited');
  end if;
  insert into public.product_reviews (product_id, user_id, order_id, rating, body, display_name)
  values (p_product_id, v_uid, v_order, p_rating, v_body, private.review_display_name(v_uid))
  on conflict (product_id, user_id) do update
     set rating = excluded.rating, body = excluded.body, display_name = excluded.display_name, order_id = excluded.order_id,
         status = 'pending', review_note = null, reviewed_by = null, reviewed_at = null;  -- edits are checked again
end;
$$;

create or replace function public.delete_my_product_review(p_product_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.product_reviews where product_id = p_product_id and user_id = (select auth.uid());
$$;

-- Admin list (reviews.manage).
create or replace function public.admin_product_reviews(p_status text default 'pending', p_limit integer default 100)
returns table (
  id uuid, product_id uuid, product_name text, product_slug text, rating smallint, body text, display_name text,
  customer_email text, order_id uuid, order_number text, status text, review_note text, reviewed_by_name text,
  reviewed_at timestamptz, created_at timestamptz, updated_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('reviews.manage');
  if p_status not in ('pending', 'approved', 'rejected') then perform private.app_error('invalid_request'); end if;
  return query
    select r.id, r.product_id, p.name_en, p.slug, r.rating, r.body, r.display_name, u.email::text, r.order_id, o.order_number,
           r.status, r.review_note, private.actor_name(r.reviewed_by), r.reviewed_at, r.created_at, r.updated_at
      from public.product_reviews r
      join public.products p on p.id = r.product_id
      left join auth.users u on u.id = r.user_id
      left join public.orders o on o.id = r.order_id
     where r.status = p_status
     order by case when p_status = 'pending' then r.updated_at end asc, r.updated_at desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

create or replace function public.admin_moderate_review(p_review_id uuid, p_decision text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.product_reviews;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  perform private.require_permission('reviews.manage');
  if p_decision not in ('approved', 'rejected') then perform private.app_error('invalid_decision'); end if;
  if v_note is not null and char_length(v_note) > 500 then perform private.app_error('invalid_request', 'note'); end if;
  select * into r from public.product_reviews where id = p_review_id for update;
  if not found then perform private.app_error('not_found'); end if;
  update public.product_reviews
     set status = p_decision, review_note = v_note, reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_review_id;
  perform private.audit('review_' || p_decision, 'product_review', p_review_id::text,
                        jsonb_build_object('status', r.status), jsonb_build_object('status', p_decision),
                        jsonb_build_object('product_id', r.product_id, 'rating', r.rating, 'note', v_note));
end;
$$;

-- Keep the product's average / count of APPROVED reviews up to date.
create or replace function private.refresh_product_rating()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_product uuid := coalesce(new.product_id, old.product_id);
begin
  update public.products p
     set rating_avg = s.avg, rating_count = s.n
    from (select round(avg(rating)::numeric, 1) as avg, count(*)::int as n
            from public.product_reviews where product_id = v_product and status = 'approved') s
   where p.id = v_product
     and (p.rating_avg is distinct from s.avg or p.rating_count is distinct from s.n);
  return null;
end;
$$;
create trigger product_reviews_rating after insert or update of status, rating or delete on public.product_reviews
  for each row execute function private.refresh_product_rating();

revoke all on function public.my_product_review(uuid) from public, anon;
