-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000033_sales_reports.sql
-- =============================================================================
-- 0033 SALES REPORTS (daily closing / monthly statement), Super Admin (analytics.view).
--   Money is counted when the payment was VERIFIED (matches the bank statement), in
--   Addis Ababa days. Read-only; exports are recorded via admin_log_export('sales').
-- =============================================================================

create or replace function public.admin_sales_report(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_from timestamptz;
  v_to   timestamptz;
  v jsonb;
begin
  perform private.require_permission('analytics.view');
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then
    perform private.app_error('invalid_request');
  end if;
  v_from := p_from::timestamp at time zone 'Africa/Addis_Ababa';
  v_to   := (p_to + 1)::timestamp at time zone 'Africa/Addis_Ababa';

  with
  placed as (select * from public.orders where created_at >= v_from and created_at < v_to),
  paid as (select * from public.orders where payment_verified_at >= v_from and payment_verified_at < v_to
             and payment_status in ('verified', 'refunded')),
  paid_items as (select i.* from public.order_items i join paid o on o.id = i.order_id),
  topups as (select * from public.wallet_topups where status = 'verified' and reviewed_at >= v_from and reviewed_at < v_to),
  cancelled_paid as (
    select o.*, h.created_at as cancelled_on from public.orders o
      join lateral (select created_at from public.order_status_history
                     where order_id = o.id and to_status = 'cancelled' order by id desc limit 1) h on true
     where o.status = 'cancelled' and o.payment_verified_at is not null
       and h.created_at >= v_from and h.created_at < v_to),
  wallet_refunds as (select * from public.wallet_ledger where kind = 'refund' and created_at >= v_from and created_at < v_to),
  days as (select generate_series(p_from::timestamp, p_to::timestamp, interval '1 day')::date as d),
  addis as (select o.*, (o.payment_verified_at at time zone 'Africa/Addis_Ababa')::date as d from paid o)
  select jsonb_build_object(
    'from', p_from, 'to', p_to,
    'totals', jsonb_build_object(
      'orders_placed', (select count(*) from placed),
      'orders_paid', (select count(*) from paid),
      'sales', (select coalesce(sum(total_etb), 0) from paid),
      'products_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'product'),
      'printing_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'printing'),
      'delivery_fees', (select coalesce(sum(delivery_fee_etb), 0) from paid),
      'discounts', (select coalesce(sum(discount_etb), 0) from paid),
      'average_order', (select coalesce(round(avg(total_etb), 2), 0) from paid),
      'paid_by_bank', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer'),
      'paid_by_wallet', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'wallet'),
      'topups_count', (select count(*) from topups),
      'topups_amount', (select coalesce(sum(amount_etb), 0) from topups),
      'cash_in', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer')
                 + (select coalesce(sum(amount_etb), 0) from topups),
      'cancelled_after_payment_count', (select count(*) from cancelled_paid),
      'cancelled_after_payment_bank', (select coalesce(sum(total_etb), 0) from cancelled_paid where payment_method = 'bank_transfer'),
      'wallet_refunds', (select coalesce(sum(amount_etb), 0) from wallet_refunds)),
    'by_bank', (
      select coalesce(jsonb_agg(x order by x ->> 'bank', x ->> 'account'), '[]'::jsonb) from (
        select jsonb_build_object('bank', bank, 'account', account,
                 'orders', sum(orders), 'orders_amount', sum(orders_amount), 'topups', sum(topups), 'topups_amount', sum(topups_amount),
                 'total', sum(orders_amount) + sum(topups_amount)) as x
          from (
            select coalesce(bank_snapshot ->> 'bank_name', '—') as bank, coalesce(bank_snapshot ->> 'account_number', '—') as account,
                   count(*) as orders, sum(total_etb) as orders_amount, 0 as topups, 0::numeric as topups_amount
              from paid where payment_method = 'bank_transfer' group by 1, 2
            union all
            select coalesce(bank_snapshot ->> 'bank_name', '—'), coalesce(bank_snapshot ->> 'account_number', '—'), 0, 0, count(*), sum(amount_etb)
              from topups group by 1, 2) u
         group by bank, account) t),
    'by_day', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'day', dd.d,
               'placed', (select count(*) from placed o where (o.created_at at time zone 'Africa/Addis_Ababa')::date = dd.d),
               'paid', (select count(*) from addis a where a.d = dd.d),
               'sales', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d),
               'bank', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'bank_transfer'),
               'wallet', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'wallet'),
               'topups', (select coalesce(sum(t.amount_etb), 0) from topups t where (t.reviewed_at at time zone 'Africa/Addis_Ababa')::date = dd.d))
             order by dd.d), '[]'::jsonb) from days dd),
    'by_staff', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'payments', n, 'amount', amount) order by n desc), '[]'::jsonb) from (
        select private.actor_name(payment_verified_by) as name, count(*) as n, sum(total_etb) as amount
          from paid where payment_method = 'bank_transfer' group by payment_verified_by) s),
    'top_products', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name_en, 'sku', sku, 'quantity', q, 'amount', amount) order by q desc, amount desc), '[]'::jsonb) from (
        select name_en, sku, sum(quantity) as q, sum(line_total_etb) as amount
          from paid_items where item_type = 'product' group by name_en, sku order by 3 desc, 4 desc limit 15) tp),
    'cancelled_after_payment', (
      select coalesce(jsonb_agg(jsonb_build_object('order_number', c.order_number, 'total', c.total_etb, 'method', c.payment_method,
               'cancelled_at', c.cancelled_on, 'customer', c.customer_name) order by c.cancelled_on), '[]'::jsonb)
        from cancelled_paid c)
  ) into v;
  return v;
end;
$$;

-- Record sales exports too.
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

revoke all on function public.admin_sales_report(date, date) from public, anon;
grant execute on function public.admin_sales_report(date, date) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000034_data_export_reset.sql
-- =============================================================================
-- 0034 EXPORT EVERYTHING / RESET TEST DATA (Super Admin only: data.manage)
--   * admin_data_export(area, offset, limit): every business area as JSON rows for an
--     Excel export. Secrets (access/tracking token hashes, idempotency keys, push keys)
--     are never exported.
--   * admin_reset_test_data(confirm): removes orders, payments, printing jobs, wallet
--     history, reviews, customer accounts and test logs; KEEPS products, categories,
--     settings, bank accounts, delivery zones, prices, promotions, banners and staff.
--     Refused unless the confirmation phrase matches AND the same admin exported
--     everything in the last 30 minutes. The reset is recorded permanently.
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('data.manage', 'Export all data and reset test data')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select id, 'data.manage' from public.admin_roles where key = 'super_admin'
on conflict do nothing;

create or replace function public.admin_data_export_areas()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array[
    'orders', 'order_items', 'payments', 'order_history', 'order_notes', 'printing_jobs', 'printing_files',
    'customer_accounts', 'customers', 'addresses', 'wallet_topups', 'wallet_ledger', 'reviews', 'stock_requests',
    'products', 'product_images', 'categories', 'inventory', 'promotions', 'promotion_customers',
    'delivery_zones', 'bank_accounts', 'printing_prices', 'banners', 'settings', 'staff', 'activity_log',
    'security_events', 'blocked_emails']
$$;

create or replace function public.admin_data_export(p_area text, p_offset integer default 0, p_limit integer default 1000)
returns setof jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 1000), 1000));
  v_offset integer := greatest(0, coalesce(p_offset, 0));
begin
  perform private.require_permission('data.manage');
  case p_area
    when 'orders' then return query select to_jsonb(t) - array['access_token_hash', 'tracking_code_hash', 'idempotency_key'] from public.orders t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'order_items' then return query select to_jsonb(t) from public.order_items t order by t.order_id, t.id offset v_offset limit v_limit;
    when 'payments' then return query select to_jsonb(t) from public.payment_submissions t order by t.submitted_at, t.id offset v_offset limit v_limit;
    when 'order_history' then return query select to_jsonb(t) from public.order_status_history t order by t.id offset v_offset limit v_limit;
    when 'order_notes' then return query select to_jsonb(t) from public.order_notes t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'printing_jobs' then return query select to_jsonb(t) - array['access_token_hash'] from public.printing_jobs t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'printing_files' then return query select to_jsonb(t) from public.printing_files t order by t.job_id, t.id offset v_offset limit v_limit;
    when 'customer_accounts' then return query
      select to_jsonb(a) || jsonb_build_object('email', u.email, 'email_confirmed_at', u.email_confirmed_at, 'last_sign_in_at', u.last_sign_in_at, 'banned_until', u.banned_until)
        from public.customer_accounts a left join auth.users u on u.id = a.id order by a.created_at, a.id offset v_offset limit v_limit;
    when 'customers' then return query select to_jsonb(t) from public.customers t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'addresses' then return query select to_jsonb(t) from public.addresses t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'wallet_topups' then return query select to_jsonb(t) from public.wallet_topups t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'wallet_ledger' then return query select to_jsonb(t) from public.wallet_ledger t order by t.id offset v_offset limit v_limit;
    when 'reviews' then return query select to_jsonb(t) from public.product_reviews t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'stock_requests' then return query select to_jsonb(t) from public.stock_alerts t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'products' then return query select to_jsonb(t) - array['search_vector'] from public.products t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'product_images' then return query select to_jsonb(t) from public.product_images t order by t.product_id, t.sort_order, t.id offset v_offset limit v_limit;
    when 'categories' then return query select to_jsonb(t) from public.categories t order by t.department, t.sort_order, t.id offset v_offset limit v_limit;
    when 'inventory' then return query select to_jsonb(t) from public.inventory_movements t order by t.id offset v_offset limit v_limit;
    when 'promotions' then return query select to_jsonb(t) from public.promotions t order by t.created_at, t.id offset v_offset limit v_limit;
    when 'promotion_customers' then return query select to_jsonb(t) from public.promotion_customers t order by t.created_at offset v_offset limit v_limit;
    when 'delivery_zones' then return query select to_jsonb(t) from public.delivery_zones t order by t.id offset v_offset limit v_limit;
    when 'bank_accounts' then return query select to_jsonb(t) from public.bank_accounts t order by t.id offset v_offset limit v_limit;
    when 'printing_prices' then return query select to_jsonb(t) from public.printing_price_rules t order by t.id offset v_offset limit v_limit;
    when 'banners' then return query select to_jsonb(t) from public.homepage_banners t order by t.id offset v_offset limit v_limit;
    when 'settings' then return query select to_jsonb(t) from public.website_settings t order by t.key offset v_offset limit v_limit;
    when 'staff' then return query
      select to_jsonb(p) || jsonb_build_object('email', u.email, 'role', r.key)
        from public.profiles p left join auth.users u on u.id = p.id left join public.admin_roles r on r.id = p.role_id
       order by p.created_at, p.id offset v_offset limit v_limit;
    when 'activity_log' then return query select to_jsonb(t) from public.audit_logs t order by t.id offset v_offset limit v_limit;
    when 'security_events' then return query select to_jsonb(t) from public.security_events t order by t.id offset v_offset limit v_limit;
    when 'blocked_emails' then return query select to_jsonb(t) from public.blocked_emails t order by t.created_at offset v_offset limit v_limit;
    else perform private.app_error('invalid_request', 'area');
  end case;
end;
$$;

-- Exports are recorded ('all' = export everything; the reset requires a recent one).
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- The wallet ledger and the activity log stay append-only, except inside the reset below.
create or replace function private.prevent_ledger_mutation()
returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' and current_setting('app.data_reset', true) = 'on' then return old; end if;
  raise exception 'wallet_ledger is append-only';
end;
$$;

create or replace function private.prevent_audit_mutation()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and current_setting('app.audit_purge', true) = 'on' and old.action not in ('audit_cleared', 'data_reset') then
    return old;
  end if;
  raise exception 'audit_logs is append-only';
end;
$$;

-- "RESET <English business name>"
create or replace function public.admin_reset_phrase()
returns text
language sql
stable
security definer
set search_path = ''
as $$ select 'RESET ' || coalesce(nullif(btrim(private.setting('business') -> 'name' ->> 'en'), ''), 'SHOP') $$;

create or replace function public.admin_reset_test_data(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_counts jsonb;
  n_orders int; n_jobs int; n_customers int; n_accounts int; n_topups int; n_reviews int; n_audit int;
begin
  perform private.require_permission('data.manage');
  if p_confirm is distinct from public.admin_reset_phrase() then
    perform private.app_error('invalid_request', 'confirmation');
  end if;
  if not exists (select 1 from public.audit_logs where action = 'export_all' and actor_id = v_uid and created_at > now() - interval '30 minutes') then
    perform private.app_error('invalid_request', 'export_first');
  end if;
  -- One reset at a time.
  perform pg_advisory_xact_lock(hashtext('admin_reset_test_data'));

  select count(*) into n_orders from public.orders;
  select count(*) into n_jobs from public.printing_jobs;
  select count(*) into n_customers from public.customers;
  select count(*) into n_accounts from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id);
  select count(*) into n_topups from public.wallet_topups;
  select count(*) into n_reviews from public.product_reviews;

  perform set_config('app.data_reset', 'on', true);
  perform set_config('app.audit_purge', 'on', true);

  -- ("where true": Supabase refuses DELETE without WHERE on API calls)
  delete from public.inventory_movements where order_id is not null;   -- stock levels stay as they are now
  delete from public.wallet_ledger where true;
  delete from public.wallet_topups where true;
  delete from public.product_reviews where true;
  delete from public.stock_alerts where true;
  delete from public.customer_carts where true;
  delete from public.push_subscriptions where true;
  delete from public.orders where true;                -- items, payments, history, notes
  delete from public.printing_jobs where true;         -- files, history
  delete from public.customers where true;             -- addresses
  delete from public.notifications_outbox where true;
  delete from public.rate_limits where true;
  delete from public.security_events where true;
  -- Before the accounts: their activity entries would otherwise need an (forbidden) update.
  delete from public.audit_logs where action not in ('audit_cleared', 'data_reset');
  get diagnostics n_audit = row_count;
  -- Customer sign-in accounts (staff are kept).
  delete from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id);

  -- New numbering for the real shop.
  alter sequence public.order_number_seq restart with 10001;
  alter sequence public.print_job_number_seq restart with 10001;
  alter sequence public.wallet_topup_number_seq restart with 1001;

  perform set_config('app.data_reset', 'off', true);
  perform set_config('app.audit_purge', 'off', true);

  v_counts := jsonb_build_object('orders', n_orders, 'printing_jobs', n_jobs, 'customers', n_customers, 'customer_accounts', n_accounts,
                                 'wallet_topups', n_topups, 'reviews', n_reviews, 'activity_entries', n_audit, 'reset_at', now());
  perform private.audit('data_reset', 'data', null, null, null, v_counts);
  return v_counts;
end;
$$;

-- Server (service_role), right after a reset: stored receipts / documents no longer referenced.
create or replace function public.reset_storage_leftovers(p_before timestamptz, p_limit integer default 1000)
returns table (bucket text, name text)
language sql
stable
security definer
set search_path = ''
as $$
  select o.bucket_id, o.name
    from storage.objects o
   where o.created_at < p_before
     and ((o.bucket_id = 'payment-receipts'
            and not exists (select 1 from public.payment_submissions s where s.receipt_path = o.name)
            and not exists (select 1 from public.wallet_topups t where t.receipt_path = o.name))
       or (o.bucket_id = 'printing-files'
            and not exists (select 1 from public.printing_files f where f.storage_path = o.name)))
   order by o.created_at
   limit greatest(1, least(coalesce(p_limit, 1000), 1000))
$$;

revoke all on function public.admin_data_export(text, integer, integer) from public, anon;
revoke all on function public.admin_reset_test_data(text) from public, anon;
revoke all on function public.admin_reset_phrase() from public, anon;
revoke all on function public.reset_storage_leftovers(timestamptz, integer) from public, anon, authenticated;
grant execute on function public.admin_data_export(text, integer, integer) to authenticated;
grant execute on function public.admin_data_export_areas() to authenticated;
grant execute on function public.admin_reset_test_data(text) to authenticated;
grant execute on function public.admin_reset_phrase() to authenticated;
grant execute on function public.reset_storage_leftovers(timestamptz, integer) to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000035_security_reviews.sql
-- =============================================================================
-- 0035 SECURITY ALERTS CAN BE CLEARED ("mark as reviewed")
--   A reviewed email / customer leaves the suspicious lists and the red badge; it comes back
--   only if something new happens after the review. Events themselves are kept.
-- =============================================================================

create table public.security_reviews (
  subject_type text not null check (subject_type in ('email', 'customer')),
  subject      text not null check (char_length(subject) between 3 and 320),
  reviewed_at  timestamptz not null default now(),
  reviewed_by  uuid references auth.users(id) on delete set null,
  note         text check (char_length(note) <= 500),
  primary key (subject_type, subject)
);
alter table public.security_reviews enable row level security;
revoke all on public.security_reviews from anon, authenticated;
-- Read/write only through the functions below.

create or replace function private.reviewed_at(p_type text, p_subject text)
returns timestamptz
language sql
stable
security definer
set search_path = ''
as $$ select reviewed_at from public.security_reviews where subject_type = p_type and subject = lower(p_subject) $$;

-- Mark one or many as reviewed (security.manage = Super Admin).
create or replace function public.admin_mark_security_reviewed(p_type text, p_subjects text[], p_note text default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  perform private.require_permission('security.manage');
  if p_type not in ('email', 'customer') or p_subjects is null or cardinality(p_subjects) = 0 or cardinality(p_subjects) > 500 then
    perform private.app_error('invalid_request');
  end if;
  if p_note is not null and char_length(p_note) > 500 then perform private.app_error('invalid_request', 'note'); end if;
  insert into public.security_reviews (subject_type, subject, reviewed_at, reviewed_by, note)
  select p_type, lower(btrim(s)), now(), auth.uid(), nullif(btrim(p_note), '')
    from unnest(p_subjects) s
   where char_length(btrim(s)) between 3 and 320
  on conflict (subject_type, subject) do update set reviewed_at = excluded.reviewed_at, reviewed_by = excluded.reviewed_by, note = excluded.note;
  get diagnostics v_n = row_count;
  perform private.audit('security_reviewed', 'security', p_type, null, null,
                        jsonb_build_object('type', p_type, 'count', v_n, 'subjects', to_jsonb(p_subjects[1:20]), 'note', p_note));
  return v_n;
end;
$$;

-- Suspicious emails: only events after the email's last review count.
create or replace function public.admin_suspicious_emails(p_days integer default 7)
returns table (email text, failed_admin bigint, failed_mfa bigint, failed_customer bigint, blocked_attempts bigint, rate_limited bigint,
               networks bigint, last_seen timestamptz, has_account boolean, is_staff boolean, blocked boolean, score bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
  with e as (
    select s.email,
           count(*) filter (where s.kind in ('admin_login_failed', 'admin_login_not_staff')) as fa,
           count(*) filter (where s.kind = 'admin_mfa_failed') as fm,
           count(*) filter (where s.kind = 'customer_login_failed') as fc,
           count(*) filter (where s.kind in ('login_blocked', 'signup_blocked')) as fb,
           count(*) filter (where s.kind = 'rate_limited') as rl,
           count(distinct s.ip_hash) as nets,
           max(s.created_at) as last
      from public.security_events s
      left join public.security_reviews r on r.subject_type = 'email' and r.subject = lower(s.email)
     where s.email is not null and s.kind <> 'admin_login_success'
       and s.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 7), 180)))
       and (r.reviewed_at is null or s.created_at > r.reviewed_at)
     group by s.email)
  select e.email, e.fa, e.fm, e.fc, e.fb, e.rl, e.nets, e.last,
         exists (select 1 from auth.users u where lower(u.email) = e.email),
         exists (select 1 from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = e.email),
         private.email_is_blocked(e.email),
         e.fa * 3 + e.fm * 4 + e.fc + e.fb * 2 + e.rl * 2 + greatest(e.nets - 1, 0) * 2
    from e
   order by 12 desc, e.last desc
   limit 300;
end;
$$;

-- Suspicious customers: only behaviour after the customer's last review counts.
create or replace function public.admin_suspicious_customers(p_days integer default 30)
returns table (user_id uuid, email text, full_name text, expired_orders bigint, cancelled_unpaid bigint, rejected_payments bigint,
               rejected_topups bigint, reused_receipts bigint, failed_logins bigint, idle_basket_hours integer,
               deactivated boolean, blocked boolean, reasons text[])
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_since timestamptz := now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)));
begin
  perform private.require_permission('audit.view');
  return query
  with base as (
    select u.id, u.email::text as email, ca.full_name, ca.deactivated_at is not null as deact,
           greatest(v_since, coalesce(private.reviewed_at('customer', u.id::text), v_since)) as since
      from auth.users u
      left join public.customer_accounts ca on ca.id = u.id
     where not exists (select 1 from public.profiles p where p.id = u.id)),
  c as (
    select b.id, b.email, b.full_name, b.deact,
      (select count(*) from public.orders o where o.user_id = b.id and o.status = 'expired' and o.created_at > b.since) as exp,
      (select count(*) from public.orders o where o.user_id = b.id and o.status = 'cancelled' and o.payment_verified_at is null and o.created_at > b.since) as canc,
      (select count(*) from public.payment_submissions s join public.orders o on o.id = s.order_id
        where o.user_id = b.id and s.status = 'rejected' and s.submitted_at > b.since) as rejp,
      (select count(*) from public.wallet_topups t where t.user_id = b.id and t.status = 'rejected' and t.created_at > b.since) as rejt,
      (select count(*) from public.payment_submissions s join public.orders o on o.id = s.order_id
        where o.user_id = b.id and s.submitted_at > b.since and (
          exists (select 1 from public.payment_submissions s2 join public.orders o2 on o2.id = s2.order_id
                   where o2.user_id <> b.id and (s2.receipt_sha256 = s.receipt_sha256
                     or (s.transaction_reference is not null and lower(s2.transaction_reference) = lower(s.transaction_reference))))
          or exists (select 1 from public.wallet_topups t where t.user_id <> b.id and t.receipt_sha256 = s.receipt_sha256))) as reused,
      (select count(*) from public.security_events e where lower(e.email) = lower(b.email) and e.kind = 'customer_login_failed' and e.created_at > b.since) as fails,
      (select floor(extract(epoch from now() - k.updated_at) / 3600)::integer from public.customer_carts k
        where k.user_id = b.id and k.item_count > 0 and k.updated_at > b.since) as idle
    from base b)
  select c.id, c.email, c.full_name, c.exp, c.canc, c.rejp, c.rejt, c.reused, c.fails, c.idle, c.deact, private.email_is_blocked(c.email),
         array_remove(array[
           case when c.exp + c.canc >= 3 then 'Many orders placed but never paid' end,
           case when c.rejp + c.rejt >= 2 then 'Several receipts rejected' end,
           case when c.reused > 0 then 'Receipt or bank reference also used by another customer' end,
           case when c.fails >= 5 then 'Many failed sign-ins' end,
           case when c.idle >= 72 and c.exp + c.canc >= 1 then 'Leaves baskets and unpaid orders repeatedly' end], null)
    from c
   where c.exp + c.canc >= 3 or c.rejp + c.rejt >= 2 or c.reused > 0 or c.fails >= 5 or (c.idle >= 72 and c.exp + c.canc >= 1)
   order by (c.reused * 5 + (c.rejp + c.rejt) * 3 + c.exp + c.canc + c.fails) desc
   limit 200;
end;
$$;

-- Recently reviewed (for the page).
create or replace function public.admin_security_reviews(p_limit integer default 50)
returns table (subject_type text, subject text, reviewed_at timestamptz, reviewed_by_name text, note text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
    select r.subject_type, case when r.subject_type = 'customer' then coalesce((select u.email::text from auth.users u where u.id::text = r.subject), r.subject) else r.subject end,
           r.reviewed_at, private.actor_name(r.reviewed_by), r.note
      from public.security_reviews r order by r.reviewed_at desc limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;

revoke all on function public.admin_mark_security_reviewed(text, text[], text) from public, anon;
revoke all on function public.admin_security_reviews(integer) from public, anon;
revoke all on function private.reviewed_at(text, text) from public;
grant execute on function public.admin_mark_security_reviewed(text, text[], text) to authenticated;
grant execute on function public.admin_security_reviews(integer) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000036_telegram_activity_feed.sql
-- =============================================================================
-- 0036 TELEGRAM ACTIVITY FEED
--   Staff Telegram also receives, each with an event name, a service name and details:
--     * security   – every security event (+ a 🚨 alert when an email becomes high-risk)
--     * admin      – sensitive admin actions (blocking, alert clearing, staff / roles / banks /
--                    settings changes, account deactivation / deletion, wallet corrections,
--                    exports, activity clearing, resets, two-step resets)
--     * notifications – a copy of every customer email / phone notification / receipt-archive
--                    email once it was sent (✓) or failed for good (✗)
--   Each part can be switched off (Admin → Notifications). Queued in the same transaction.
-- =============================================================================

-- Switches (private setting; default: all on).
create or replace function private.feed_on(p_part text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$ select coalesce((private.setting('telegram_feed') ->> p_part)::boolean, true) $$;

create or replace function public.admin_set_telegram_feed(p_security boolean, p_admin boolean, p_notifications boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := jsonb_build_object('security', coalesce(p_security, true), 'admin', coalesce(p_admin, true), 'notifications', coalesce(p_notifications, true));
begin
  perform private.require_permission('settings.manage');
  insert into public.website_settings (key, value, is_public, updated_by) values ('telegram_feed', v, false, auth.uid())
  on conflict (key) do update set value = excluded.value, is_public = false, updated_by = excluded.updated_by;
end;
$$;

create or replace function public.admin_telegram_feed()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return jsonb_build_object('security', private.feed_on('security'), 'admin', private.feed_on('admin'), 'notifications', private.feed_on('notifications'));
end;
$$;

-- Risk score of an email over the last 24 h (same weights as the Security page), ignoring reviewed activity.
create or replace function private.email_risk_24h(p_email text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
           count(*) filter (where s.kind in ('admin_login_failed', 'admin_login_not_staff')) * 3
         + count(*) filter (where s.kind = 'admin_mfa_failed') * 4
         + count(*) filter (where s.kind = 'customer_login_failed')
         + count(*) filter (where s.kind in ('login_blocked', 'signup_blocked')) * 2
         + count(*) filter (where s.kind = 'rate_limited') * 2
         + greatest(count(distinct s.ip_hash) - 1, 0) * 2, 0)::int
    from public.security_events s
    left join public.security_reviews r on r.subject_type = 'email' and r.subject = lower(s.email)
   where lower(s.email) = lower(p_email) and s.kind <> 'admin_login_success'
     and s.created_at > now() - interval '24 hours'
     and (r.reviewed_at is null or s.created_at > r.reviewed_at)
$$;

-- (1) Security events. Bursts of the same failure / email / network within 5 minutes become one message with a count
--     (plus at most one follow-up). Successful admin sign-ins are always reported individually.
create or replace function private.feed_security_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key text;
  v_score integer;
begin
  if not private.feed_on('security') then return null; end if;
  if new.kind = 'admin_login_success' then
    v_key := 'feed:sec:' || new.id;   -- every admin sign-in is reported on its own
  else
    v_key := 'feed:sec:' || new.kind || ':' || coalesce(lower(new.email), '-') || ':' || coalesce(new.ip_hash, '-') || ':' || floor(extract(epoch from new.created_at) / 300)::bigint;
    -- First message already sent: further repeats in the same 5 minutes collect in one follow-up message.
    if exists (select 1 from public.notifications_outbox where dedupe_key = v_key and status <> 'pending') then
      v_key := v_key || ':more';
    end if;
  end if;
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload)
  values ('telegram', 'security_event', v_key, jsonb_build_object(
    'kind', new.kind, 'email', new.email, 'account', private.actor_name(new.user_id),
    'is_staff', exists (select 1 from public.profiles p where p.id = new.user_id),
    'network', left(new.ip_hash, 10), 'device', left(new.user_agent, 160), 'details', new.metadata,
    'at', new.created_at, 'repeats', 1))
  on conflict (dedupe_key) do update
     set payload = jsonb_set(public.notifications_outbox.payload, '{repeats}',
                             to_jsonb(coalesce((public.notifications_outbox.payload ->> 'repeats')::int, 1) + 1))
   where public.notifications_outbox.status = 'pending';

  -- 🚨 once per email per day when it becomes high-risk (not blocked, not reviewed).
  if new.email is not null and new.kind <> 'admin_login_success' and not private.email_is_blocked(new.email) then
    v_score := private.email_risk_24h(new.email);
    if v_score >= 6 then
      insert into public.notifications_outbox (channel, event_type, dedupe_key, payload)
      values ('telegram', 'security_alert', 'feed:alert:' || lower(new.email) || ':' || (now() at time zone 'Africa/Addis_Ababa')::date,
              jsonb_build_object('email', new.email, 'score', v_score, 'last_kind', new.kind, 'network', left(new.ip_hash, 10),
                                 'has_account', exists (select 1 from auth.users u where lower(u.email) = lower(new.email)),
                                 'is_staff', exists (select 1 from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(new.email)),
                                 'at', new.created_at))
      on conflict (dedupe_key) do nothing;
    end if;
  end if;
  return null;
end;
$$;
drop trigger if exists security_events_feed on public.security_events;
create trigger security_events_feed after insert on public.security_events
  for each row execute function private.feed_security_event();

-- (2) Sensitive admin actions from the activity log.
create or replace function private.feed_admin_action()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.feed_on('admin') then return null; end if;
  if not (new.action in ('email_blocked', 'email_unblocked', 'security_reviewed', 'data_reset', 'audit_cleared', 'mfa_reset',
                         'wallet_adjusted', 'customer_deactivated', 'customer_reactivated', 'customer_deleted', 'password_reset_sent',
                         'receipt_archive_set', 'receipt_archive_backfill')
          or new.action like 'export\_%'
          or new.entity_type in ('profiles', 'role_permissions', 'bank_accounts', 'website_settings')) then
    return null;
  end if;
  perform private.enqueue_notification('admin_action', 'feed:admin:' || new.id, jsonb_build_object(
    'action', new.action, 'entity_type', new.entity_type, 'entity_id', new.entity_id,
    'actor', coalesce(private.actor_name(new.actor_id), 'System'), 'role', new.actor_role,
    'before', left(coalesce(new.before_data::text, ''), 1500), 'after', left(coalesce(new.after_data::text, ''), 1500),
    'metadata', new.metadata, 'at', new.created_at));
  return null;
end;
$$;
drop trigger if exists audit_logs_feed on public.audit_logs;
create trigger audit_logs_feed after insert on public.audit_logs
  for each row execute function private.feed_admin_action();

-- (3) Copies of customer notifications once they are sent or failed for good.
create or replace function private.feed_notification_copy()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel = 'telegram' or new.status not in ('sent', 'dead') or old.status = new.status then return null; end if;
  if not private.feed_on('notifications') then return null; end if;
  perform private.enqueue_notification('notification_copy', 'feed:copy:' || new.id || ':' || new.status, jsonb_build_object(
    'channel', new.channel, 'event', new.event_type, 'status', new.status, 'attempts', new.attempts,
    'error', left(new.last_error, 300),
    'to', case when new.channel = 'archive' then private.setting('receipt_archive') ->> 'email'
               else (select u.email::text from auth.users u where u.id = new.recipient_user_id) end,
    'order_number', new.payload ->> 'order_number', 'job_number', new.payload ->> 'job_number',
    'number', coalesce(new.payload ->> 'number', new.payload ->> 'topup_number'), 'product', new.payload ->> 'name',
    'amount_etb', coalesce(new.payload ->> 'total_etb', new.payload ->> 'amount_etb'), 'note', left(new.payload ->> 'note', 200),
    'at', coalesce(new.sent_at, now())));
  return null;
end;
$$;
drop trigger if exists notifications_outbox_feed on public.notifications_outbox;
create trigger notifications_outbox_feed after update of status on public.notifications_outbox
  for each row execute function private.feed_notification_copy();

-- Maintenance (service_role): feed messages never sent within 2 days (e.g. Telegram not set up) are dropped.
create or replace function public.purge_stale_telegram_feed()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  delete from public.notifications_outbox
   where channel = 'telegram' and status in ('pending', 'failed', 'dead')
     and event_type in ('security_event', 'security_alert', 'admin_action', 'notification_copy')
     and created_at < now() - interval '2 days';
  get diagnostics n = row_count;
  return n;
end;
$$;

revoke all on function public.admin_set_telegram_feed(boolean, boolean, boolean) from public, anon;
revoke all on function public.admin_telegram_feed() from public, anon;
revoke all on function public.purge_stale_telegram_feed() from public, anon, authenticated;
revoke all on function private.email_risk_24h(text) from public;
revoke all on function private.feed_on(text) from public;
grant execute on function public.admin_set_telegram_feed(boolean, boolean, boolean) to authenticated;
grant execute on function public.admin_telegram_feed() to authenticated;
grant execute on function public.purge_stale_telegram_feed() to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000037_telegram_two_groups.sql
-- =============================================================================
-- 0037 TWO TELEGRAM GROUPS + FULL ORDER / PRINTING PROGRESS
--   * Orders & payments group (TELEGRAM_BOT_TOKEN / TELEGRAM_ADMIN_CHAT_ID): every step of
--     an order and printing job until it is collected, payments, top-ups, stock, copies of
--     customer messages.
--   * Security group (TELEGRAM_SECURITY_BOT_TOKEN / TELEGRAM_SECURITY_CHAT_ID): security
--     events, 🚨 alerts, admin sign-ins and admin actions.
--   The sender claims each group's messages separately (claim_telegram).
-- =============================================================================

-- Which messages belong to the security group.
create or replace function private.is_security_message(p_event text)
returns boolean
language sql
immutable
set search_path = ''
as $$ select p_event in ('security_event', 'security_alert', 'admin_action', 'security_test') $$;

-- Worker (service_role): claim due Telegram rows of one group (SKIP LOCKED).
create or replace function public.claim_telegram(p_security boolean, p_limit integer default 10)
returns setof public.notifications_outbox
language sql
security definer
set search_path = ''
as $$
  update public.notifications_outbox o
     set status = 'processing', attempts = o.attempts + 1, locked_until = now() + interval '2 minutes'
   where o.id in (
     select id from public.notifications_outbox
      where channel = 'telegram'
        and private.is_security_message(event_type) = coalesce(p_security, false)
        and ((status in ('pending', 'failed') and next_attempt_at <= now())
          or (status = 'processing' and locked_until < now()))
      order by id
      limit greatest(1, least(coalesce(p_limit, 10), 50))
      for update skip locked)
  returning o.*;
$$;
revoke all on function public.claim_telegram(boolean, integer) from public, anon, authenticated;
grant execute on function public.claim_telegram(boolean, integer) to service_role;

-- Orders: "order placed (awaiting payment)" — checked at COMMIT, so balance-paid orders
-- (already confirmed by then) are not announced twice.
create or replace function private.telegram_order_placed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  o public.orders;
begin
  select * into o from public.orders where id = new.id;
  if not found or o.status <> 'awaiting_payment' then return null; end if;
  perform private.enqueue_notification('order_placed', 'order_placed:' || o.id, jsonb_build_object(
    'order_id', o.id, 'order_number', o.order_number, 'customer_name', o.customer_name, 'customer_phone', o.customer_phone,
    'total_etb', o.total_etb, 'fulfillment_method', o.fulfillment_method, 'city', o.city, 'address_line', o.address_line,
    'payment_due_at', o.payment_due_at,
    'items', (select coalesce(jsonb_agg(jsonb_build_object('name', i.name_en, 'quantity', i.quantity) order by i.id), '[]'::jsonb)
                from public.order_items i where i.order_id = o.id)));
  return null;
end;
$$;
drop trigger if exists orders_telegram_placed on public.orders;
create constraint trigger orders_telegram_placed after insert on public.orders
  deferrable initially deferred
  for each row execute function private.telegram_order_placed();

-- Orders: every later step until collection (steps already announced elsewhere are skipped:
-- receipt uploaded, payment verified / rejected, cancelled, paid with balance).
create or replace function private.telegram_order_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is not distinct from old.status
     or new.status::text not in ('processing', 'ready_for_pickup', 'out_for_delivery', 'completed', 'expired') then
    return null;
  end if;
  perform private.enqueue_notification('order_status', 'order_status:' || new.id || ':' || new.status, jsonb_build_object(
    'order_id', new.id, 'order_number', new.order_number, 'from', old.status, 'to', new.status,
    'by', private.actor_name((select auth.uid())), 'customer_name', new.customer_name, 'customer_phone', new.customer_phone,
    'total_etb', new.total_etb, 'fulfillment_method', new.fulfillment_method, 'city', new.city, 'address_line', new.address_line,
    'note', nullif(current_setting('app.status_note', true), '')));
  return null;
end;
$$;
drop trigger if exists orders_telegram_status on public.orders;
create trigger orders_telegram_status after update of status on public.orders
  for each row execute function private.telegram_order_status();

-- Printing jobs: quote, printing, ready, collected, cancelled.
create or replace function private.telegram_printing_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status is not distinct from old.status
     or new.status::text not in ('awaiting_payment', 'printing', 'ready', 'completed', 'cancelled')
     or old.status::text = 'submitted' then   -- priced automatically at creation: already in "new printing request"
    return null;
  end if;
  perform private.enqueue_notification('printing_status', 'printing_status:' || new.id || ':' || new.status, jsonb_build_object(
    'job_id', new.id, 'job_number', new.job_number, 'from', old.status, 'to', new.status,
    'by', private.actor_name((select auth.uid())), 'customer_name', new.customer_name, 'customer_phone', new.customer_phone,
    'total_etb', new.total_etb, 'page_count', new.page_count, 'copies', new.copies, 'fulfillment_method', new.fulfillment_method,
    'note', nullif(current_setting('app.status_note', true), '')));
  return null;
end;
$$;
drop trigger if exists printing_jobs_telegram_status on public.printing_jobs;
create trigger printing_jobs_telegram_status after update of status on public.printing_jobs
  for each row execute function private.telegram_printing_status();

-- "Send test message" for the security group (Super Admin).
create or replace function public.admin_queue_security_test()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  perform private.enqueue_notification('security_test', 'security_test:' || gen_random_uuid(),
    jsonb_build_object('requested_by', private.actor_name(auth.uid()), 'requested_at', now()));
end;
$$;
revoke all on function public.admin_queue_security_test() from public, anon;
grant execute on function public.admin_queue_security_test() to authenticated;

-- Notifications list: also the channel (to group the page by category). Signature change → drop first.
drop function if exists public.admin_notifications(integer);
create function public.admin_notifications(p_limit integer default 50)
returns table (
  id bigint, channel text, event_type text, status public.notification_status, attempts integer, max_attempts integer,
  last_error text, created_at timestamptz, sent_at timestamptz, next_attempt_at timestamptz, reference text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return query
    select o.id, o.channel, o.event_type, o.status, o.attempts, o.max_attempts, o.last_error, o.created_at, o.sent_at, o.next_attempt_at,
           coalesce(o.payload ->> 'order_number', o.payload ->> 'job_number', o.payload ->> 'number', o.payload ->> 'topup_number',
                    o.payload ->> 'email', o.payload ->> 'name', o.payload ->> 'label')
    from public.notifications_outbox o
    order by o.id desc
    limit greatest(1, least(coalesce(p_limit, 50), 1000));
end;
$$;
revoke all on function public.admin_notifications(integer) from public, anon;
grant execute on function public.admin_notifications(integer) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000038_activity_categories.sql
-- =============================================================================
-- 0038 ACTIVITY LOG CATEGORIES
--   Orders & printing · Payments & wallet · Customers · Products & catalog ·
--   Staff & settings · Security & data. Counts per category and a filtered list.
-- =============================================================================

create or replace function private.activity_category(p_action text, p_entity_type text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_entity_type in ('security', 'audit', 'data', 'export') or p_action like 'export\_%' then 'security'
    when p_entity_type = 'payment_submission' or p_action like 'topup\_%' or p_action like 'payment\_%' or p_action = 'wallet_adjusted' then 'payments'
    when p_entity_type in ('order', 'printing_job') then 'orders'
    when p_entity_type = 'customer_account' then 'customers'
    when p_entity_type in ('products', 'categories', 'promotions', 'delivery_zones', 'printing_price_rules', 'homepage_banners',
                           'product_review', 'product_images') then 'catalog'
    when p_entity_type in ('profiles', 'role_permissions', 'website_settings', 'bank_accounts', 'notification') then 'staff'
    else 'other'
  end
$$;

-- Counts and latest entry per category over the last p_days days.
create or replace function public.admin_activity_categories(p_days integer default 30)
returns table (category text, total bigint, last_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
    select private.activity_category(a.action, a.entity_type), count(*), max(a.created_at)
      from public.audit_logs a
     where a.created_at > now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 3650)))
     group by 1;
end;
$$;

-- The activity list of one category (or all when null), newest first, with paging.
create or replace function public.admin_activity_by_category(
  p_category text default null, p_search text default null, p_limit integer default 100, p_before_id bigint default null)
returns table (
  id bigint, created_at timestamptz, actor_id uuid, actor_name text, actor_role text,
  action text, entity_type text, entity_id text, entity_label text,
  before_data jsonb, after_data jsonb, metadata jsonb, category text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('audit.view');
  if p_category is not null and p_category not in ('orders', 'payments', 'customers', 'catalog', 'staff', 'security', 'other') then
    perform private.app_error('invalid_request', 'category');
  end if;
  return query
    select a.id, a.created_at, a.actor_id, private.actor_name(a.actor_id), a.actor_role,
           a.action, a.entity_type, a.entity_id,
           case a.entity_type
             when 'order' then (select o.order_number from public.orders o where o.id::text = a.entity_id)
             when 'printing_job' then (select j.job_number from public.printing_jobs j where j.id::text = a.entity_id)
             when 'payment_submission' then (select o.order_number from public.payment_submissions s join public.orders o on o.id = s.order_id where s.id::text = a.entity_id)
             when 'customer_account' then coalesce(
               (select u.email::text from auth.users u where u.id::text = a.entity_id), a.before_data ->> 'email')
             when 'profiles' then private.actor_name(case when a.entity_id ~ '^[0-9a-f-]{36}$' then a.entity_id::uuid end)
             when 'products' then coalesce(a.after_data ->> 'name_en', a.before_data ->> 'name_en')
             else null
           end,
           a.before_data, a.after_data, a.metadata, private.activity_category(a.action, a.entity_type)
      from public.audit_logs a
     where (p_category is null or private.activity_category(a.action, a.entity_type) = p_category)
       and (p_before_id is null or a.id < p_before_id)
       and (v_q is null or a.action ilike '%' || v_q || '%' or a.entity_id ilike '%' || v_q || '%'
            or private.actor_name(a.actor_id) ilike '%' || v_q || '%')
     order by a.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

revoke all on function public.admin_activity_categories(integer) from public, anon;
revoke all on function public.admin_activity_by_category(text, text, integer, bigint) from public, anon;
grant execute on function public.admin_activity_categories(integer) to authenticated;
grant execute on function public.admin_activity_by_category(text, text, integer, bigint) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000039_personal_code_messages.sql
-- =============================================================================
-- 0039 PERSONAL DISCOUNT CODES ARE SENT TO THE CUSTOMER
--   * Giving a personal code now emails the customer (English + Amharic) and sends a
--     phone notification if they turned them on — unless "notify" is unticked.
--   * admin_create_personal_code: create a unique one-customer code (e.g. MEKDES-7K2Q),
--     give it and send it in one step.
-- =============================================================================

create or replace function private.notify_promo_gift(p_promotion_id uuid, p_user uuid, p_note text)
returns void
language sql
security definer
set search_path = ''
as $$
  select private.enqueue_customer_email('customer_promo_gift', 'promo_gift:' || p.id || ':' || p_user, p_user, jsonb_build_object(
           'code', p.code, 'title_en', p.title_en, 'title_am', p.title_am, 'discount_type', p.discount_type,
           'discount_value', p.discount_value, 'min_order_etb', p.min_order_etb, 'ends_at', p.ends_at,
           'note', nullif(btrim(coalesce(p_note, '')), ''),
           'name', (select a.full_name from public.customer_accounts a where a.id = p_user)))
    from public.promotions p
   where p.id = p_promotion_id and p.code is not null
$$;

-- Same as before, plus notify (default on) and an optional personal note.
drop function if exists public.admin_assign_promotion(uuid, text[]);
create or replace function public.admin_assign_promotion(p_promotion_id uuid, p_emails text[], p_notify boolean default true, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_promo public.promotions;
  v_email text;
  v_user uuid;
  v_added text[] := '{}';
  v_already text[] := '{}';
  v_missing text[] := '{}';
begin
  perform private.require_permission('promotions.manage');
  if p_note is not null and char_length(p_note) > 300 then perform private.app_error('invalid_request', 'note'); end if;
  select * into v_promo from public.promotions where id = p_promotion_id;
  if not found then perform private.app_error('not_found'); end if;
  if not v_promo.restricted then perform private.app_error('invalid_request', 'promotion is not personal'); end if;
  if p_emails is null or cardinality(p_emails) = 0 or cardinality(p_emails) > 200 then
    perform private.app_error('invalid_request');
  end if;
  foreach v_email in array p_emails loop
    v_email := lower(btrim(v_email));
    continue when v_email = '';
    select u.id into v_user from auth.users u where lower(u.email) = v_email;
    if v_user is null then
      v_missing := v_missing || v_email;
      continue;
    end if;
    insert into public.promotion_customers (promotion_id, user_id) values (p_promotion_id, v_user)
    on conflict do nothing;
    if found then
      v_added := v_added || v_email;
      if coalesce(p_notify, true) and v_promo.is_active then perform private.notify_promo_gift(p_promotion_id, v_user, p_note); end if;
    else
      v_already := v_already || v_email;
    end if;
  end loop;
  return jsonb_build_object('added', to_jsonb(v_added), 'already', to_jsonb(v_already), 'not_found', to_jsonb(v_missing));
end;
$$;
revoke all on function public.admin_assign_promotion(uuid, text[], boolean, text) from public, anon;
grant execute on function public.admin_assign_promotion(uuid, text[], boolean, text) to authenticated;

-- Create a unique code for ONE customer, give it and (by default) send it.
create or replace function public.admin_create_personal_code(
  p_user_id uuid, p_discount_type text, p_value numeric, p_min_order numeric default 0, p_days integer default 30,
  p_note text default null, p_notify boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_first text;
  v_prefix text;
  v_code text;
  v_id uuid;
  v_alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';  -- no 0/O, 1/I
  i int;
begin
  perform private.require_permission('promotions.manage');
  perform private.assert_confirmed_user(p_user_id);       -- a real, active customer (not staff)
  if p_discount_type not in ('percent', 'fixed') then perform private.app_error('invalid_request', 'type'); end if;
  if p_value is null or p_value <= 0 or (p_discount_type = 'percent' and p_value > 90) or (p_discount_type = 'fixed' and p_value > 100000)
     or p_value <> round(p_value, 2) then
    perform private.app_error('invalid_amount');
  end if;
  if coalesce(p_min_order, 0) < 0 or coalesce(p_min_order, 0) > 1000000 then perform private.app_error('invalid_amount'); end if;
  if p_days is null or p_days not between 1 and 365 then perform private.app_error('invalid_request', 'days'); end if;
  if p_note is not null and char_length(p_note) > 300 then perform private.app_error('invalid_request', 'note'); end if;

  select nullif(split_part(btrim(coalesce(a.full_name, '')), ' ', 1), '') into v_first from public.customer_accounts a where a.id = p_user_id;
  v_prefix := left(upper(regexp_replace(coalesce(v_first, ''), '[^A-Za-z]', '', 'g')), 10);
  if char_length(v_prefix) < 2 then v_prefix := 'GIFT'; end if;
  for attempt in 1..20 loop
    v_code := v_prefix || '-';
    for i in 1..4 loop v_code := v_code || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1); end loop;
    exit when not exists (select 1 from public.promotions where code = v_code);
  end loop;

  insert into public.promotions (title_en, title_am, description_en, description_am, code, discount_type, discount_value, min_order_etb,
                                 starts_at, ends_at, is_active, show_on_homepage, restricted, once_per_customer, max_redemptions)
  values ('Your personal discount', 'የእርስዎ የግል ቅናሽ',
          coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'A personal discount code just for you.'),
          coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'ለእርስዎ ብቻ የተሰጠ የግል የቅናሽ ኮድ።'),
          v_code, p_discount_type, p_value, coalesce(p_min_order, 0),
          now(), now() + make_interval(days => p_days), true, false, true, true, 1)
  returning id into v_id;
  insert into public.promotion_customers (promotion_id, user_id) values (v_id, p_user_id);
  if coalesce(p_notify, true) then perform private.notify_promo_gift(v_id, p_user_id, p_note); end if;
  return jsonb_build_object('promotion_id', v_id, 'code', v_code, 'ends_at', now() + make_interval(days => p_days));
end;
$$;
revoke all on function public.admin_create_personal_code(uuid, text, numeric, numeric, integer, text, boolean) from public, anon;
revoke all on function private.notify_promo_gift(uuid, uuid, text) from public;
grant execute on function public.admin_create_personal_code(uuid, text, numeric, numeric, integer, text, boolean) to authenticated;

-- Telegram copies of customer messages: show the discount code; product name only for back-in-stock.
create or replace function private.feed_notification_copy()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel = 'telegram' or new.status not in ('sent', 'dead') or old.status = new.status then return null; end if;
  if not private.feed_on('notifications') then return null; end if;
  perform private.enqueue_notification('notification_copy', 'feed:copy:' || new.id || ':' || new.status, jsonb_build_object(
    'channel', new.channel, 'event', new.event_type, 'status', new.status, 'attempts', new.attempts,
    'error', left(new.last_error, 300),
    'to', case when new.channel = 'archive' then private.setting('receipt_archive') ->> 'email'
               else (select u.email::text from auth.users u where u.id = new.recipient_user_id) end,
    'order_number', new.payload ->> 'order_number', 'job_number', new.payload ->> 'job_number',
    'number', coalesce(new.payload ->> 'number', new.payload ->> 'topup_number', new.payload ->> 'code'),
    'product', case when new.event_type = 'customer_back_in_stock' then new.payload ->> 'name' end,
    'amount_etb', coalesce(new.payload ->> 'total_etb', new.payload ->> 'amount_etb',
                           case when new.payload ->> 'discount_type' = 'fixed' then new.payload ->> 'discount_value' end),
    'note', left(new.payload ->> 'note', 200),
    'at', coalesce(new.sent_at, now())));
  return null;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000040_customers_without_staff.sql
-- =============================================================================
-- 0040 STAFF ARE NOT LISTED UNDER CUSTOMERS
--   Staff accounts (in profiles) are managed only under Staff. The customer list,
--   search and customer pages no longer include them. (is_staff is kept, always false.)
-- =============================================================================

create or replace function public.admin_customer_accounts(p_search text default null, p_limit integer default 100, p_user_id uuid default null)
returns table (
  id uuid, email text, full_name text, phone text, created_at timestamptz,
  email_confirmed_at timestamptz, last_sign_in_at timestamptz, is_staff boolean,
  order_count bigint, last_order_at timestamptz,
  deactivated_at timestamptz, deactivation_reason text, deactivated_by_name text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('customers.view');
  return query
    select u.id, u.email::text, c.full_name, c.phone, u.created_at, u.email_confirmed_at, u.last_sign_in_at,
           false as is_staff,
           (select count(*) from public.orders o where o.user_id = u.id) as order_count,
           (select max(o.created_at) from public.orders o where o.user_id = u.id) as last_order_at,
           c.deactivated_at, c.deactivation_reason,
           (select p.full_name from public.profiles p where p.id = c.deactivated_by)
    from auth.users u
    left join public.customer_accounts c on c.id = u.id
    where not exists (select 1 from public.profiles p where p.id = u.id)   -- staff: see Staff
      and (p_user_id is null or u.id = p_user_id)
      and (v_q is null
       or u.email ilike '%' || v_q || '%'
       or c.full_name ilike '%' || v_q || '%'
       or c.phone ilike '%' || v_q || '%')
    order by u.created_at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

-- Is this id a staff account? (lets the customer page send you to Staff instead.)
create or replace function public.admin_is_staff_account(p_user_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('customers.view');
  return exists (select 1 from public.profiles where id = p_user_id);
end;
$$;
revoke all on function public.admin_is_staff_account(uuid) from public, anon;
grant execute on function public.admin_is_staff_account(uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000041_telegram_four_groups.sql
-- =============================================================================
-- 0041 TELEGRAM: ORDERS GROUP ONLY FOR APPROVALS; STOCK AND RECEIPTS GROUPS
--   * Orders & payments group: by default only what needs you — receipts to verify,
--     top-ups to verify, printing requests to quote. Order / printing progress, payment
--     decisions, cancellations, balance payments and customer-message copies are
--     switches (off by default).
--   * Stock group (TELEGRAM_STOCK_*): low stock / sold out, instead of staff emails.
--   * Receipts group (TELEGRAM_RECEIPTS_*): every verified / rejected receipt file
--     with its details (in addition to the receipt-archive email).
-- =============================================================================

-- Switch defaults (missing keys): order_progress, notifications (copies) off; the rest on.
create or replace function private.feed_on(p_part text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((private.setting('telegram_feed') ->> p_part)::boolean,
                  p_part not in ('order_progress', 'notifications'))
$$;
-- The owner asked for approvals only: switch copies of customer messages off.
update public.website_settings set value = value || '{"notifications": false, "order_progress": false}'::jsonb
 where key = 'telegram_feed';

drop function if exists public.admin_set_telegram_feed(boolean, boolean, boolean);
create or replace function public.admin_set_telegram_feed(p_security boolean, p_admin boolean, p_notifications boolean,
                                                          p_order_progress boolean default false, p_printing_requests boolean default true)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := jsonb_build_object('security', coalesce(p_security, true), 'admin', coalesce(p_admin, true),
                                'notifications', coalesce(p_notifications, false), 'order_progress', coalesce(p_order_progress, false),
                                'printing_requests', coalesce(p_printing_requests, true));
begin
  perform private.require_permission('settings.manage');
  insert into public.website_settings (key, value, is_public, updated_by) values ('telegram_feed', v, false, auth.uid())
  on conflict (key) do update set value = excluded.value, is_public = false, updated_by = excluded.updated_by;
end;
$$;
revoke all on function public.admin_set_telegram_feed(boolean, boolean, boolean, boolean, boolean) from public, anon;
grant execute on function public.admin_set_telegram_feed(boolean, boolean, boolean, boolean, boolean) to authenticated;

create or replace function public.admin_telegram_feed()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return jsonb_build_object('security', private.feed_on('security'), 'admin', private.feed_on('admin'),
                            'notifications', private.feed_on('notifications'), 'order_progress', private.feed_on('order_progress'),
                            'printing_requests', private.feed_on('printing_requests'));
end;
$$;

-- Telegram messages that are switched off are never queued.
create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_verified', 'payment_rejected', 'wallet_order_paid')
     and not private.feed_on('order_progress') then
    return null;
  end if;
  if new.event_type = 'printing_request' and not private.feed_on('printing_requests') then return null; end if;
  return new;
end;
$$;
drop trigger if exists notifications_outbox_telegram_filter on public.notifications_outbox;
create trigger notifications_outbox_telegram_filter before insert on public.notifications_outbox
  for each row execute function private.telegram_filter();

-- Which group a Telegram message belongs to.
create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test') then 'receipts'
    else 'orders'
  end
$$;

-- Worker (service_role): claim due rows of the given groups (stock falls back to the orders bot if it has none).
create or replace function public.claim_telegram_groups(p_groups text[], p_limit integer default 10)
returns setof public.notifications_outbox
language sql
security definer
set search_path = ''
as $$
  update public.notifications_outbox o
     set status = 'processing', attempts = o.attempts + 1, locked_until = now() + interval '2 minutes'
   where o.id in (
     select id from public.notifications_outbox
      where channel = 'telegram'
        and private.telegram_group(event_type) = any(p_groups)
        and ((status in ('pending', 'failed') and next_attempt_at <= now())
          or (status = 'processing' and locked_until < now()))
      order by id
      limit greatest(1, least(coalesce(p_limit, 10), 50))
      for update skip locked)
  returning o.*;
$$;
revoke all on function public.claim_telegram_groups(text[], integer) from public, anon, authenticated;
grant execute on function public.claim_telegram_groups(text[], integer) to service_role;

-- Stock: Telegram only (no more staff emails).
create or replace function private.stock_level_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
  v_key text := new.id || ':' || txid_current();
  v_payload jsonb;
begin
  if not new.track_inventory then return null; end if;
  v_payload := jsonb_build_object('product_id', new.id, 'name', new.name_en, 'name_am', new.name_am, 'sku', new.sku, 'slug', new.slug,
                                  'stock', new.stock_quantity, 'threshold', new.low_stock_threshold);
  if new.status = 'active' then
    if new.stock_quantity = 0 and old.stock_quantity > 0 then v_event := 'out_of_stock';
    elsif new.stock_quantity <= new.low_stock_threshold and old.stock_quantity > new.low_stock_threshold then v_event := 'low_stock';
    end if;
    if v_event is not null then
      perform private.enqueue_notification(v_event, v_event || ':' || v_key, v_payload);
    end if;
  end if;
  if new.status = 'active' and new.stock_quantity > 0 and old.stock_quantity = 0 then
    perform private.enqueue_customer_email('customer_back_in_stock', 'back_in_stock:' || a.id, a.user_id, v_payload)
       from public.stock_alerts a
      where a.product_id = new.id and a.notified_at is null and private.is_active_user(a.user_id);
    update public.stock_alerts set notified_at = now() where product_id = new.id and notified_at is null;
  end if;
  return null;
end;
$$;

-- Receipts group: the receipt file with the decision, for every verified / rejected payment or top-up.
create or replace function private.telegram_receipt_record(p_kind text, p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'payment' then
    insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, attachment_bucket, attachment_path, max_attempts)
    select 'telegram', 'receipt_record', 'tg_receipt:payment:' || s.id || ':' || s.status,
           jsonb_build_object('kind', 'order_payment', 'result', s.status, 'number', o.order_number, 'order_id', o.id,
             'amount_etb', s.amount_expected_etb, 'reference', s.transaction_reference, 'customer_name', o.customer_name,
             'customer_phone', o.customer_phone, 'bank_name', o.bank_snapshot ->> 'bank_name', 'account_number', o.bank_snapshot ->> 'account_number',
             'decided_at', s.reviewed_at, 'decided_by', private.actor_name(s.reviewed_by), 'reason', s.review_note),
           'payment-receipts', s.receipt_path, 10
      from public.payment_submissions s join public.orders o on o.id = s.order_id
     where s.id = p_id
    on conflict (dedupe_key) do nothing;
  else
    insert into public.notifications_outbox (channel, event_type, dedupe_key, payload, attachment_bucket, attachment_path, max_attempts)
    select 'telegram', 'receipt_record', 'tg_receipt:topup:' || t.id || ':' || t.status,
           jsonb_build_object('kind', 'wallet_topup', 'result', t.status, 'number', t.topup_number,
             'amount_etb', t.amount_etb, 'reference', t.transaction_reference, 'customer_name', a.full_name, 'customer_phone', a.phone,
             'bank_name', t.bank_snapshot ->> 'bank_name', 'account_number', t.bank_snapshot ->> 'account_number',
             'decided_at', t.reviewed_at, 'decided_by', private.actor_name(t.reviewed_by), 'reason', t.review_note),
           'payment-receipts', t.receipt_path, 10
      from public.wallet_topups t left join public.customer_accounts a on a.id = t.user_id
     where t.id = p_id
    on conflict (dedupe_key) do nothing;
  end if;
end;
$$;

create or replace function private.archive_on_payment_decision()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status::text in ('verified', 'rejected') and old.status::text is distinct from new.status::text then
    if tg_table_name = 'payment_submissions' then
      perform private.archive_payment_receipt(new.id);
      perform private.telegram_receipt_record('payment', new.id);
    else
      perform private.archive_topup_receipt(new.id);
      perform private.telegram_receipt_record('topup', new.id);
    end if;
  end if;
  return null;
end;
$$;

-- Test buttons for the stock and receipts groups.
create or replace function public.admin_queue_group_test(p_group text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  if p_group not in ('stock', 'receipts') then perform private.app_error('invalid_request'); end if;
  perform private.enqueue_notification(p_group || '_test', p_group || '_test:' || gen_random_uuid(),
    jsonb_build_object('requested_by', private.actor_name(auth.uid()), 'requested_at', now()));
end;
$$;
revoke all on function public.admin_queue_group_test(text) from public, anon;
grant execute on function public.admin_queue_group_test(text) to authenticated;

-- Messages for a group that was never set up are dropped after 2 days.
create or replace function public.purge_stale_telegram_feed()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  delete from public.notifications_outbox
   where channel = 'telegram' and status in ('pending', 'failed', 'dead')
     and event_type in ('security_event', 'security_alert', 'admin_action', 'notification_copy', 'receipt_record', 'stock_test', 'receipts_test')
     and created_at < now() - interval '2 days';
  get diagnostics n = row_count;
  return n;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000042_staff_remove.sql
-- =============================================================================
-- 0042 STAFF: DEACTIVATE AND DELETE (Super Admin)
-- "Delete" removes a staff member for good: no dashboard access, hidden from
-- the Staff list, cannot be switched back on. The profile row is KEPT (marked
-- removed) so history — activity log, order notes, payment decisions — still
-- shows who did what. The server action also blocks their sign-in.
-- =============================================================================
alter table public.profiles
  add column removed_at timestamptz,
  add column removed_by uuid references auth.users(id) on delete set null;
alter table public.profiles add constraint profiles_removed_inactive check (removed_at is null or not is_active);

-- Role / access changes: removed staff cannot be changed or switched back on.
create or replace function public.admin_set_staff_role(p_user_id uuid, p_role_key text, p_is_active boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role smallint;
  v_super smallint;
begin
  perform private.require_permission('staff.manage');
  if p_user_id = (select auth.uid()) then perform private.app_error('cannot_modify_self'); end if;
  select id into v_role from public.admin_roles where key = p_role_key;
  if not found then perform private.app_error('invalid_role'); end if;
  select id into v_super from public.admin_roles where key = 'super_admin';

  perform pg_advisory_xact_lock(hashtext('staff_roles'));
  -- (The profiles audit trigger records every change, incl. the Telegram copy.)
  update public.profiles set role_id = v_role, is_active = p_is_active where id = p_user_id and removed_at is null;
  if not found then perform private.app_error('not_found'); end if;
  if not exists (select 1 from public.profiles where role_id = v_super and is_active) then
    perform private.app_error('last_super_admin');
  end if;
end;
$$;
revoke all on function public.admin_set_staff_role(uuid, text, boolean) from public, anon;
grant execute on function public.admin_set_staff_role(uuid, text, boolean) to authenticated;

-- Delete (remove for good). Returns the staff member's name for the message.
create or replace function public.admin_remove_staff(p_user_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_super smallint;
  v_p public.profiles;
begin
  perform private.require_permission('staff.manage');
  if p_user_id = (select auth.uid()) then perform private.app_error('cannot_modify_self'); end if;
  select id into v_super from public.admin_roles where key = 'super_admin';
  perform pg_advisory_xact_lock(hashtext('staff_roles'));
  select * into v_p from public.profiles where id = p_user_id and removed_at is null for update;
  if not found then perform private.app_error('not_found'); end if;
  -- Recorded by the profiles audit trigger (activity log + Telegram admin feed).
  update public.profiles set is_active = false, removed_at = now(), removed_by = (select auth.uid()) where id = p_user_id;
  if not exists (select 1 from public.profiles where role_id = v_super and is_active) then
    perform private.app_error('last_super_admin');
  end if;
  -- Unassign their open work so nothing is stuck with someone who has left.
  update public.orders set assigned_to = null where assigned_to = p_user_id
     and status not in ('completed', 'cancelled', 'expired');
  update public.printing_jobs set assigned_to = null where assigned_to = p_user_id
     and status not in ('completed', 'cancelled');
  return v_p.full_name;
end;
$$;
revoke all on function public.admin_remove_staff(uuid) from public, anon;
grant execute on function public.admin_remove_staff(uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000043_product_audience.sql
-- =============================================================================
-- 0043 PRODUCT "FOR": WOMEN / MEN / UNISEX
-- Optional on every product (e.g. perfume). The shop shows a Women / Men
-- filter when products in that list have it; unisex products appear in both.
-- =============================================================================
alter table public.products add column audience text check (audience in ('women', 'men', 'unisex'));
create index products_audience_idx on public.products(audience) where audience is not null;
grant select (audience) on public.products to anon;
grant insert (audience), update (audience) on public.products to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000044_single_session_push_owner.sql
-- =============================================================================
-- 0044 ONE DEVICE PER ACCOUNT, ONE REVIEW AT A TIME, PUSH TO THE LATEST ACCOUNT
--   * Signing in on a new device/browser ends the account's other sessions
--     (the app calls Supabase sign-out "others"; the session rows are deleted).
--     private.session_alive() makes the database refuse a token whose session
--     was ended, even before the token expires: staff lose every permission and
--     customers can no longer act (orders, wallet, reviews …).
--   * Security alerts are cleared one at a time (no bulk "mark all").
--   * A device's phone notifications belong to the account that signed in on
--     it most recently (claim_push_device moves the device).
-- =============================================================================

-- Is the session this token belongs to still open? (Tokens always carry session_id.)
create or replace function private.session_alive()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select case when nullif(auth.jwt() ->> 'session_id', '') is null then true
              else exists (select 1 from auth.sessions s where s.id = (auth.jwt() ->> 'session_id')::uuid) end
$$;
revoke all on function private.session_alive() from public, anon;
grant execute on function private.session_alive() to authenticated, service_role;

-- Staff: every permission check (has_permission, is_admin, current_role_key) goes through this.
create or replace function private.mfa_verified()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce((select auth.jwt() ->> 'aal'), 'aal1') = 'aal2' and private.session_alive()
$$;

-- Customers.
create or replace function private.is_active_customer()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.is_active_user((select auth.uid())) and private.session_alive()
$$;

-- For the website: is my session still the open one? (false = signed in elsewhere / signed out)
create or replace function public.session_is_current()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select auth.uid()) is not null and private.session_alive()
$$;
revoke all on function public.session_is_current() from public, anon;
grant execute on function public.session_is_current() to authenticated;

-- One alert at a time.
create or replace function public.admin_mark_security_reviewed(p_type text, p_subjects text[], p_note text default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  perform private.require_permission('security.manage');
  if p_type not in ('email', 'customer') or p_subjects is null or cardinality(p_subjects) <> 1 then
    perform private.app_error('invalid_request', 'review one alert at a time');
  end if;
  if p_note is not null and char_length(p_note) > 500 then perform private.app_error('invalid_request', 'note'); end if;
  insert into public.security_reviews (subject_type, subject, reviewed_at, reviewed_by, note)
  select p_type, lower(btrim(s)), now(), auth.uid(), nullif(btrim(p_note), '')
    from unnest(p_subjects) s
   where char_length(btrim(s)) between 3 and 320
  on conflict (subject_type, subject) do update set reviewed_at = excluded.reviewed_at, reviewed_by = excluded.reviewed_by, note = excluded.note;
  get diagnostics v_n = row_count;
  perform private.audit('security_reviewed', 'security', p_type, null, null,
                        jsonb_build_object('type', p_type, 'count', v_n, 'subjects', to_jsonb(p_subjects), 'note', p_note));
  return v_n;
end;
$$;

-- This device now notifies the signed-in customer only (taken from any other account).
create or replace function public.claim_push_device(p_endpoint text, p_p256dh text, p_auth text, p_locale text default 'en')
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  delete from public.push_subscriptions where endpoint = p_endpoint;
  -- Column checks (allowed push services, key formats) apply to this insert.
  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth, locale)
  values ((select auth.uid()), p_endpoint, p_p256dh, p_auth, case when p_locale = 'am' then 'am' else 'en' end);
end;
$$;
revoke all on function public.claim_push_device(text, text, text, text) from public, anon;
grant execute on function public.claim_push_device(text, text, text, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000045_paid_orders_locked_details.sql
-- =============================================================================
-- 0045 PAID ORDERS ONLY, PAYMENT-ONLY ALERTS, LOCKED PERSONAL DETAILS
--   * Orders group on Telegram: only payments — receipts / top-ups waiting for
--     approval and completed payments (verified, paid with balance) — plus
--     printing requests that need a price (switch). No order steps,
--     cancellations, rejections or copies of customer messages.
--   * Dashboard counts an order only once it is paid (receipt pending approval,
--     verified or refunded). Unpaid checkouts live under "Stalled checkouts".
--   * Customers set their name and phone once; after that only staff can
--     change them (and the sign-in email). Delivery city / address stay theirs.
-- =============================================================================

create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_rejected', 'notification_copy') then
    return null;
  end if;
  if new.event_type = 'printing_request' and not private.feed_on('printing_requests') then return null; end if;
  return new;
end;
$$;

create or replace function public.admin_dashboard_stats(p_days integer default 14)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_all       boolean := private.has_permission('orders.view_all');
  v_assigned  boolean := private.has_permission('orders.view_assigned');
  v_revenue   boolean := private.has_permission('analytics.view');
  v_days      integer := greatest(1, least(coalesce(p_days, 14), 90));
  v_today     date := (now() at time zone 'Africa/Addis_Ababa')::date;
  v_result    jsonb;
begin
  perform private.require_permission('dashboard.view');

  with visible as (
    -- An order counts once the customer has paid: receipt waiting for approval, verified, or refunded.
    select o.* from public.orders o
    where (v_all or (v_assigned and o.assigned_to = v_uid))
      and o.payment_status in ('pending_verification', 'verified', 'refunded')
  )
  select jsonb_build_object(
    'orders_total', (select count(*) from visible),
    'orders_today', (select count(*) from visible where (created_at at time zone 'Africa/Addis_Ababa')::date = v_today),
    'awaiting_processing', (select count(*) from visible where status in ('confirmed', 'processing')),
    'awaiting_payment', (select count(*) from visible where status in ('awaiting_payment', 'payment_rejected')),
    'pending_payments', case when private.has_permission('payments.view')
        then (select count(*) from public.payment_submissions where status = 'pending') end,
    'products_active', case when private.has_permission('products.view')
        then (select count(*) from public.products where status = 'active') end,
    'low_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory
              and stock_quantity > 0 and stock_quantity <= low_stock_threshold) end,
    'out_of_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity = 0) end,
    'printing_open', case when private.has_permission('printing.view')
        then (select count(*) from public.printing_jobs where status in ('awaiting_quote', 'payment_verification', 'printing', 'ready')) end,
    'revenue_verified_total', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified') end,
    'revenue_verified_period', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified'
              and (payment_verified_at at time zone 'Africa/Addis_Ababa')::date > v_today - v_days) end,
    'daily', (
      select jsonb_agg(jsonb_build_object(
               'day', d.day,
               'orders', (select count(*) from visible v where (v.created_at at time zone 'Africa/Addis_Ababa')::date = d.day),
               'revenue', case when v_revenue then (
                   select coalesce(sum(o.total_etb), 0) from public.orders o
                    where o.payment_status = 'verified'
                      and (o.payment_verified_at at time zone 'Africa/Addis_Ababa')::date = d.day) end)
             order by d.day)
      from (select generate_series(v_today - (v_days - 1), v_today, interval '1 day')::date as day) d
    )
  ) into v_result;
  return v_result;
end;
$$;
revoke execute on function public.admin_dashboard_stats(integer) from public, anon;
grant execute on function public.admin_dashboard_stats(integer) to authenticated;

-- Name and phone: the customer fills them in once; later changes only through staff.
create or replace function private.customer_details_lock()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Staff tools are security definer functions (they do not run as "authenticated").
  if current_user <> 'authenticated' then return new; end if;
  if nullif(btrim(coalesce(old.full_name, '')), '') is not null then new.full_name := old.full_name; end if;
  if old.phone is not null then new.phone := old.phone; end if;
  return new;
end;
$$;
drop trigger if exists customer_details_lock on public.customer_accounts;
create trigger customer_details_lock before update on public.customer_accounts
  for each row execute function private.customer_details_lock();

-- The sign-in email cannot be changed by the customer (an email-change request is refused);
-- staff change it directly through the Auth admin API, which does not use email_change.
create or replace function private.refuse_self_email_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(new.email_change, '') <> '' and new.email_change is distinct from old.email_change then
    raise exception 'email_change_not_allowed' using errcode = 'P0001',
      hint = 'Customers cannot change their email; staff can (Admin → Customers).';
  end if;
  return new;
end;
$$;
drop trigger if exists refuse_self_email_change on auth.users;
create trigger refuse_self_email_change before update on auth.users
  for each row execute function private.refuse_self_email_change();

-- Staff: change a customer's name / phone (recorded in the activity log). The email itself is changed
-- by the server with the Auth admin API first; p_old_email is then recorded here with the new one.
create or replace function public.admin_update_customer_details(p_user_id uuid, p_full_name text, p_phone text, p_old_email text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_before public.customer_accounts;
begin
  perform private.require_permission('customers.manage');
  if p_user_id is null or not exists (select 1 from auth.users where id = p_user_id) then perform private.app_error('not_found'); end if;
  if exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('invalid_request', 'staff account'); end if;
  if char_length(btrim(coalesce(p_full_name, ''))) not between 2 and 120 then perform private.app_error('invalid_name'); end if;
  if p_phone is not null and p_phone !~ '^\+251[79][0-9]{8}$' then perform private.app_error('invalid_phone'); end if;
  insert into public.customer_accounts (id) values (p_user_id) on conflict do nothing;
  select * into v_before from public.customer_accounts where id = p_user_id for update;
  update public.customer_accounts set full_name = btrim(p_full_name), phone = p_phone where id = p_user_id;
  perform private.audit('profile_updated', 'customer_account', p_user_id::text,
    jsonb_strip_nulls(jsonb_build_object('full_name', v_before.full_name, 'phone', v_before.phone, 'email', p_old_email)),
    jsonb_strip_nulls(jsonb_build_object('full_name', btrim(p_full_name), 'phone', p_phone,
      'email', case when p_old_email is not null then (select u.email::text from auth.users u where u.id = p_user_id) end)),
    jsonb_build_object('by', 'staff'));
end;
$$;
revoke all on function public.admin_update_customer_details(uuid, text, text, text) from public, anon;
grant execute on function public.admin_update_customer_details(uuid, text, text, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000046_warsaw_gmail_printing_cancel.sql
-- =============================================================================
-- 0046 WARSAW TIME, GMAIL-ONLY SIGN-UPS, PRINTING DOCUMENTS GROUP, CUSTOMER CANCEL
--   * Days (dashboard, analytics, sales reports) are counted in Europe/Warsaw
--     time (with summer time). The shop itself stays in Ethiopia (ETB, +251).
--   * New accounts only with an @gmail.com address (website_settings
--     'signup_email_domains'; local test data may add test domains).
--   * Printing group (own Telegram bot): each document of a printing job, sent
--     once its payment is approved (job moves to "printing").
--   * Customers can cancel their own order until staff approve the payment.
-- =============================================================================

-- ---------------------------------------------------------------- Warsaw time
create or replace function public.admin_dashboard_stats(p_days integer default 14)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_all       boolean := private.has_permission('orders.view_all');
  v_assigned  boolean := private.has_permission('orders.view_assigned');
  v_revenue   boolean := private.has_permission('analytics.view');
  v_days      integer := greatest(1, least(coalesce(p_days, 14), 90));
  v_today     date := (now() at time zone 'Europe/Warsaw')::date;
  v_result    jsonb;
begin
  perform private.require_permission('dashboard.view');

  with visible as (
    -- An order counts once the customer has paid: receipt waiting for approval, verified, or refunded.
    select o.* from public.orders o
    where (v_all or (v_assigned and o.assigned_to = v_uid))
      and o.payment_status in ('pending_verification', 'verified', 'refunded')
  )
  select jsonb_build_object(
    'orders_total', (select count(*) from visible),
    'orders_today', (select count(*) from visible where (created_at at time zone 'Europe/Warsaw')::date = v_today),
    'awaiting_processing', (select count(*) from visible where status in ('confirmed', 'processing')),
    'awaiting_payment', (select count(*) from visible where status in ('awaiting_payment', 'payment_rejected')),
    'pending_payments', case when private.has_permission('payments.view')
        then (select count(*) from public.payment_submissions where status = 'pending') end,
    'products_active', case when private.has_permission('products.view')
        then (select count(*) from public.products where status = 'active') end,
    'low_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory
              and stock_quantity > 0 and stock_quantity <= low_stock_threshold) end,
    'out_of_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity = 0) end,
    'printing_open', case when private.has_permission('printing.view')
        then (select count(*) from public.printing_jobs where status in ('awaiting_quote', 'payment_verification', 'printing', 'ready')) end,
    'revenue_verified_total', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified') end,
    'revenue_verified_period', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified'
              and (payment_verified_at at time zone 'Europe/Warsaw')::date > v_today - v_days) end,
    'daily', (
      select jsonb_agg(jsonb_build_object(
               'day', d.day,
               'orders', (select count(*) from visible v where (v.created_at at time zone 'Europe/Warsaw')::date = d.day),
               'revenue', case when v_revenue then (
                   select coalesce(sum(o.total_etb), 0) from public.orders o
                    where o.payment_status = 'verified'
                      and (o.payment_verified_at at time zone 'Europe/Warsaw')::date = d.day) end)
             order by d.day)
      from (select generate_series(v_today - (v_days - 1), v_today, interval '1 day')::date as day) d
    )
  ) into v_result;
  return v_result;
end;
$$;

create or replace function public.admin_analytics(p_from date, p_to date, p_bucket text default 'day')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_money  boolean := private.has_permission('analytics.view');
  v_bucket text := case when p_bucket in ('day', 'week', 'month') then p_bucket else 'day' end;
  v_from   timestamptz;
  v_to     timestamptz;
  v_result jsonb;
begin
  if not (v_money or private.has_permission('reports.operational')) then
    perform private.app_error('forbidden', 'analytics.view');
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then
    perform private.app_error('invalid_request');
  end if;
  v_from := p_from::timestamp at time zone 'Europe/Warsaw';
  v_to   := (p_to + 1)::timestamp at time zone 'Europe/Warsaw';

  with
  placed as (select * from public.orders where created_at >= v_from and created_at < v_to),
  paid as (select * from public.orders where payment_status = 'verified'
                    and payment_verified_at >= v_from and payment_verified_at < v_to),
  paid_items as (
    select i.*, p.category_id, coalesce(c.parent_id, c.id) as top_category
      from public.order_items i join paid o on o.id = i.order_id
      left join public.products p on p.id = i.product_id
      left join public.categories c on c.id = p.category_id),
  buckets as (
    select generate_series(date_trunc(v_bucket, p_from::timestamp), p_to::timestamp, ('1 ' || v_bucket)::interval)::date as b)
  select jsonb_build_object(
    'money', v_money,
    'bucket', v_bucket,
    'totals', jsonb_build_object(
      'orders_placed', (select count(*) from placed),
      'orders_paid', (select count(*) from paid),
      'orders_expired', (select count(*) from placed where status = 'expired'),
      'orders_cancelled', (select count(*) from placed where status = 'cancelled'),
      'items_sold', (select coalesce(sum(quantity), 0) from paid_items where item_type = 'product'),
      'revenue', case when v_money then (select coalesce(sum(total_etb), 0) from paid) end,
      'products_revenue', case when v_money then (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'product') end,
      'printing_revenue', case when v_money then (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'printing') end,
      'delivery_fees', case when v_money then (select coalesce(sum(delivery_fee_etb), 0) from paid) end,
      'discounts', case when v_money then (select coalesce(sum(discount_etb), 0) from paid) end,
      'average_order', case when v_money then (select round(avg(total_etb), 2) from paid) end),
    'series', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'bucket', bk.b,
               'orders', (select count(*) from placed o
                           where date_trunc(v_bucket, (o.created_at at time zone 'Europe/Warsaw'))::date = bk.b),
               'paid', (select count(*) from paid o
                         where date_trunc(v_bucket, (o.payment_verified_at at time zone 'Europe/Warsaw'))::date = bk.b),
               'revenue', case when v_money then (select coalesce(sum(o.total_etb), 0) from paid o
                         where date_trunc(v_bucket, (o.payment_verified_at at time zone 'Europe/Warsaw'))::date = bk.b) end)
             order by bk.b), '[]'::jsonb)
        from buckets bk),
    'by_category', (
      select coalesce(jsonb_agg(x order by x.qty desc), '[]'::jsonb) from (
        select coalesce(c.name_en, case when pi.item_type = 'printing' then 'Printing services' else 'Other' end) as name,
               coalesce(c.department::text, case when pi.item_type = 'printing' then 'printing' end) as department,
               sum(pi.quantity) as qty,
               case when v_money then sum(pi.line_total_etb) end as revenue
          from paid_items pi left join public.categories c on c.id = pi.top_category
         group by 1, 2) x),
    'best_sellers', (
      select coalesce(jsonb_agg(x order by x.qty desc, x.name), '[]'::jsonb) from (
        select pi.product_id, max(pi.name_en) as name, max(pi.sku) as sku, sum(pi.quantity) as qty,
               case when v_money then sum(pi.line_total_etb) end as revenue
          from paid_items pi where pi.item_type = 'product'
         group by pi.product_id
         order by sum(pi.quantity) desc
         limit 10) x),
    'statuses', (
      select coalesce(jsonb_object_agg(status, n), '{}'::jsonb)
        from (select status::text, count(*) as n from placed group by 1) s),
    'fulfillment', (
      select coalesce(jsonb_object_agg(fulfillment_method, n), '{}'::jsonb)
        from (select fulfillment_method::text, count(*) as n from placed group by 1) s),
    'promotions', (
      select coalesce(jsonb_agg(x order by x.orders desc), '[]'::jsonb) from (
        select pr.title_en as name, pr.code::text as code, count(*) as orders,
               case when v_money then sum(o.discount_etb) end as discount
          from placed o join public.promotions pr on pr.id = o.promotion_id
         where o.status not in ('expired', 'cancelled')
         group by pr.id) x),
    'inventory', jsonb_build_object(
      'active_products', (select count(*) from public.products where status = 'active'),
      'tracked', (select count(*) from public.products where status = 'active' and track_inventory),
      'out_of_stock', (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity <= 0),
      'low_stock', (select count(*) from public.products where status = 'active' and track_inventory
                      and stock_quantity > 0 and stock_quantity <= low_stock_threshold),
      'units_in_stock', (select coalesce(sum(stock_quantity), 0) from public.products where status = 'active' and track_inventory),
      'stock_value', case when v_money then (select coalesce(sum(stock_quantity * coalesce(sale_price_etb, price_etb)), 0)
                       from public.products where status = 'active' and track_inventory) end)
  ) into v_result;
  return v_result;
end;
$$;

create or replace function public.admin_sales_report(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_from timestamptz;
  v_to   timestamptz;
  v jsonb;
begin
  perform private.require_permission('analytics.view');
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then
    perform private.app_error('invalid_request');
  end if;
  v_from := p_from::timestamp at time zone 'Europe/Warsaw';
  v_to   := (p_to + 1)::timestamp at time zone 'Europe/Warsaw';

  with
  placed as (select * from public.orders where created_at >= v_from and created_at < v_to),
  paid as (select * from public.orders where payment_verified_at >= v_from and payment_verified_at < v_to
             and payment_status in ('verified', 'refunded')),
  paid_items as (select i.* from public.order_items i join paid o on o.id = i.order_id),
  topups as (select * from public.wallet_topups where status = 'verified' and reviewed_at >= v_from and reviewed_at < v_to),
  cancelled_paid as (
    select o.*, h.created_at as cancelled_on from public.orders o
      join lateral (select created_at from public.order_status_history
                     where order_id = o.id and to_status = 'cancelled' order by id desc limit 1) h on true
     where o.status = 'cancelled' and o.payment_verified_at is not null
       and h.created_at >= v_from and h.created_at < v_to),
  wallet_refunds as (select * from public.wallet_ledger where kind = 'refund' and created_at >= v_from and created_at < v_to),
  days as (select generate_series(p_from::timestamp, p_to::timestamp, interval '1 day')::date as d),
  addis as (select o.*, (o.payment_verified_at at time zone 'Europe/Warsaw')::date as d from paid o)
  select jsonb_build_object(
    'from', p_from, 'to', p_to,
    'totals', jsonb_build_object(
      'orders_placed', (select count(*) from placed),
      'orders_paid', (select count(*) from paid),
      'sales', (select coalesce(sum(total_etb), 0) from paid),
      'products_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'product'),
      'printing_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'printing'),
      'delivery_fees', (select coalesce(sum(delivery_fee_etb), 0) from paid),
      'discounts', (select coalesce(sum(discount_etb), 0) from paid),
      'average_order', (select coalesce(round(avg(total_etb), 2), 0) from paid),
      'paid_by_bank', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer'),
      'paid_by_wallet', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'wallet'),
      'topups_count', (select count(*) from topups),
      'topups_amount', (select coalesce(sum(amount_etb), 0) from topups),
      'cash_in', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer')
                 + (select coalesce(sum(amount_etb), 0) from topups),
      'cancelled_after_payment_count', (select count(*) from cancelled_paid),
      'cancelled_after_payment_bank', (select coalesce(sum(total_etb), 0) from cancelled_paid where payment_method = 'bank_transfer'),
      'wallet_refunds', (select coalesce(sum(amount_etb), 0) from wallet_refunds)),
    'by_bank', (
      select coalesce(jsonb_agg(x order by x ->> 'bank', x ->> 'account'), '[]'::jsonb) from (
        select jsonb_build_object('bank', bank, 'account', account,
                 'orders', sum(orders), 'orders_amount', sum(orders_amount), 'topups', sum(topups), 'topups_amount', sum(topups_amount),
                 'total', sum(orders_amount) + sum(topups_amount)) as x
          from (
            select coalesce(bank_snapshot ->> 'bank_name', '—') as bank, coalesce(bank_snapshot ->> 'account_number', '—') as account,
                   count(*) as orders, sum(total_etb) as orders_amount, 0 as topups, 0::numeric as topups_amount
              from paid where payment_method = 'bank_transfer' group by 1, 2
            union all
            select coalesce(bank_snapshot ->> 'bank_name', '—'), coalesce(bank_snapshot ->> 'account_number', '—'), 0, 0, count(*), sum(amount_etb)
              from topups group by 1, 2) u
         group by bank, account) t),
    'by_day', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'day', dd.d,
               'placed', (select count(*) from placed o where (o.created_at at time zone 'Europe/Warsaw')::date = dd.d),
               'paid', (select count(*) from addis a where a.d = dd.d),
               'sales', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d),
               'bank', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'bank_transfer'),
               'wallet', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'wallet'),
               'topups', (select coalesce(sum(t.amount_etb), 0) from topups t where (t.reviewed_at at time zone 'Europe/Warsaw')::date = dd.d))
             order by dd.d), '[]'::jsonb) from days dd),
    'by_staff', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'payments', n, 'amount', amount) order by n desc), '[]'::jsonb) from (
        select private.actor_name(payment_verified_by) as name, count(*) as n, sum(total_etb) as amount
          from paid where payment_method = 'bank_transfer' group by payment_verified_by) s),
    'top_products', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name_en, 'sku', sku, 'quantity', q, 'amount', amount) order by q desc, amount desc), '[]'::jsonb) from (
        select name_en, sku, sum(quantity) as q, sum(line_total_etb) as amount
          from paid_items where item_type = 'product' group by name_en, sku order by 3 desc, 4 desc limit 15) tp),
    'cancelled_after_payment', (
      select coalesce(jsonb_agg(jsonb_build_object('order_number', c.order_number, 'total', c.total_etb, 'method', c.payment_method,
               'cancelled_at', c.cancelled_on, 'customer', c.customer_name) order by c.cancelled_on), '[]'::jsonb)
        from cancelled_paid c)
  ) into v;
  return v;
end;
$$;

create or replace function private.feed_security_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key text;
  v_score integer;
begin
  if not private.feed_on('security') then return null; end if;
  if new.kind = 'admin_login_success' then
    v_key := 'feed:sec:' || new.id;   -- every admin sign-in is reported on its own
  else
    v_key := 'feed:sec:' || new.kind || ':' || coalesce(lower(new.email), '-') || ':' || coalesce(new.ip_hash, '-') || ':' || floor(extract(epoch from new.created_at) / 300)::bigint;
    -- First message already sent: further repeats in the same 5 minutes collect in one follow-up message.
    if exists (select 1 from public.notifications_outbox where dedupe_key = v_key and status <> 'pending') then
      v_key := v_key || ':more';
    end if;
  end if;
  insert into public.notifications_outbox (channel, event_type, dedupe_key, payload)
  values ('telegram', 'security_event', v_key, jsonb_build_object(
    'kind', new.kind, 'email', new.email, 'account', private.actor_name(new.user_id),
    'is_staff', exists (select 1 from public.profiles p where p.id = new.user_id),
    'network', left(new.ip_hash, 10), 'device', left(new.user_agent, 160), 'details', new.metadata,
    'at', new.created_at, 'repeats', 1))
  on conflict (dedupe_key) do update
     set payload = jsonb_set(public.notifications_outbox.payload, '{repeats}',
                             to_jsonb(coalesce((public.notifications_outbox.payload ->> 'repeats')::int, 1) + 1))
   where public.notifications_outbox.status = 'pending';

  -- 🚨 once per email per day when it becomes high-risk (not blocked, not reviewed).
  if new.email is not null and new.kind <> 'admin_login_success' and not private.email_is_blocked(new.email) then
    v_score := private.email_risk_24h(new.email);
    if v_score >= 6 then
      insert into public.notifications_outbox (channel, event_type, dedupe_key, payload)
      values ('telegram', 'security_alert', 'feed:alert:' || lower(new.email) || ':' || (now() at time zone 'Europe/Warsaw')::date,
              jsonb_build_object('email', new.email, 'score', v_score, 'last_kind', new.kind, 'network', left(new.ip_hash, 10),
                                 'has_account', exists (select 1 from auth.users u where lower(u.email) = lower(new.email)),
                                 'is_staff', exists (select 1 from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(new.email)),
                                 'at', new.created_at))
      on conflict (dedupe_key) do nothing;
    end if;
  end if;
  return null;
end;
$$;


-- ---------------------------------------------------------------- Gmail only
insert into public.website_settings (key, value, is_public)
values ('signup_email_domains', '{"domains": ["gmail.com"]}', false)
