create or replace function private.signup_domain_allowed(p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select lower(split_part(btrim(coalesce(p_email, '')), '@', 2)) in (
    select lower(jsonb_array_elements_text(coalesce(private.setting('signup_email_domains') -> 'domains', '["gmail.com"]'::jsonb))))
$$;
grant execute on function private.signup_domain_allowed(text) to authenticated, service_role;

-- Every new account (customer sign-up, invitation, staff) — existing accounts are not affected.
create or replace function private.refuse_other_email_domains()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.signup_domain_allowed(new.email) then
    raise exception using errcode = 'P0001', message = 'email_domain_not_allowed';
  end if;
  return new;
end;
$$;
drop trigger if exists refuse_other_email_domains on auth.users;
create trigger refuse_other_email_domains before insert on auth.users
  for each row execute function private.refuse_other_email_domains();

-- For the website's forms (a friendly message before trying to create the account).
create or replace function public.signup_email_allowed(p_email text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.signup_domain_allowed(p_email)
$$;
revoke all on function public.signup_email_allowed(text) from public;
grant execute on function public.signup_email_allowed(text) to anon, authenticated, service_role;

-- ---------------------------------------------------------------- Printing documents group
create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test') then 'receipts'
    when p_event in ('printing_document', 'printing_test') then 'printing'
    else 'orders'
  end
$$;

-- Payment approved (job moves to "printing"): every document of the job, one message each.
create or replace function private.printing_documents_on_paid()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total integer;
  v_i integer := 0;
  f record;
begin
  if new.status <> 'printing' or old.status = 'printing' then return null; end if;
  select count(*) into v_total from public.printing_files where job_id = new.id and deleted_at is null;
  for f in select * from public.printing_files where job_id = new.id and deleted_at is null order by created_at, id loop
    v_i := v_i + 1;
    perform private.enqueue_notification('printing_document', 'printing_document:' || f.id,
      jsonb_build_object('job_id', new.id, 'job_number', new.job_number, 'file_name', f.original_name, 'mime', f.mime_type,
        'size_bytes', f.size_bytes, 'pages', f.page_count, 'n', v_i, 'of', v_total,
        'customer', new.customer_name, 'phone', new.customer_phone, 'color_mode', new.color_mode, 'paper_size', new.paper_size,
        'sides', new.sides, 'copies', new.copies, 'page_count', new.page_count, 'total_etb', new.total_etb,
        'fulfillment', new.fulfillment_method, 'notes', left(new.customer_notes, 300)),
      'printing-files', f.storage_path);
  end loop;
  return null;
end;
$$;
drop trigger if exists printing_documents_on_paid on public.printing_jobs;
create trigger printing_documents_on_paid after update of status on public.printing_jobs
  for each row execute function private.printing_documents_on_paid();

create or replace function public.admin_queue_group_test(p_group text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  if p_group not in ('stock', 'receipts', 'printing') then perform private.app_error('invalid_request'); end if;
  perform private.enqueue_notification(p_group || '_test', p_group || '_test:' || gen_random_uuid(),
    jsonb_build_object('requested_by', private.actor_name(auth.uid()), 'requested_at', now()));
end;
$$;

-- Documents for a printing group that was never set up are dropped after 2 days.
create or replace function public.purge_stale_telegram_feed()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  delete from public.notifications_outbox
   where channel = 'telegram' and status in ('pending', 'failed', 'dead')
     and event_type in ('security_event', 'security_alert', 'admin_action', 'notification_copy', 'receipt_record', 'stock_test', 'receipts_test',
                        'printing_document', 'printing_test')
     and created_at < now() - interval '2 days';
  get diagnostics n = row_count;
  return n;
end;
$$;

-- ---------------------------------------------------------------- Customer cancels
create or replace function public.customer_cancel_order(p_order_id uuid, p_reason text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders;
  v_reason text := nullif(left(btrim(coalesce(p_reason, '')), 500), '');
  v_note text;
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  select * into v_order from public.orders where id = p_order_id and user_id = (select auth.uid()) for update;
  if not found then perform private.app_error('not_found'); end if;
  -- Until staff approve the payment (a verified / balance-paid order is handled by the shop).
  if v_order.status not in ('awaiting_payment', 'pending_verification', 'payment_rejected') or v_order.payment_status in ('verified', 'refunded') then
    perform private.app_error('invalid_transition', v_order.status::text || '->cancelled');
  end if;
  v_note := 'Cancelled by the customer' || coalesce(': ' || v_reason, '');
  perform private.release_order_stock(v_order.id);
  -- A receipt still waiting for approval is closed (kept for the records).
  update public.payment_submissions
     set status = 'rejected', reviewed_at = now(), review_note = 'Order cancelled by the customer'
   where order_id = v_order.id and status = 'pending';
  update public.printing_jobs set status = 'cancelled'
   where order_id = v_order.id and status not in ('completed', 'cancelled');
  perform private.set_status_note(v_note);
  update public.orders set status = 'cancelled', cancelled_at = now() where id = v_order.id;
  perform private.audit('order_status', 'order', v_order.id::text,
    jsonb_build_object('status', v_order.status), jsonb_build_object('status', 'cancelled', 'note', v_note),
    jsonb_build_object('by', 'customer', 'order_number', v_order.order_number));
end;
$$;
revoke all on function public.customer_cancel_order(uuid, text) from public, anon;
grant execute on function public.customer_cancel_order(uuid, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000047_age_sex.sql
-- =============================================================================
-- 0047 DATE OF BIRTH AND SEX (customers and staff)
--   * Customers can give them at sign-up or once on My account; afterwards only
--     staff change them (same lock as name and phone).
--   * Staff: set by a Super Admin (Staff → Personal details).
-- =============================================================================
alter table public.customer_accounts
  add column date_of_birth date check (date_of_birth >= date '1900-01-01'),
  add column sex text check (sex in ('female', 'male'));
grant update (date_of_birth, sex) on public.customer_accounts to authenticated;

alter table public.profiles
  add column date_of_birth date check (date_of_birth >= date '1900-01-01'),
  add column sex text check (sex in ('female', 'male'));

-- Lock: set once by the customer, then only by staff.
create or replace function private.customer_details_lock()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Staff tools are security definer functions (they do not run as "authenticated").
  if current_user <> 'authenticated' then return new; end if;
  if nullif(btrim(coalesce(old.full_name, '')), '') is not null then new.full_name := old.full_name; end if;
  if old.phone is not null then new.phone := old.phone; end if;
  if old.date_of_birth is not null then new.date_of_birth := old.date_of_birth; end if;
  if old.sex is not null then new.sex := old.sex; end if;
  if new.date_of_birth is not null and new.date_of_birth > (current_date - interval '10 years')::date then
    raise exception using errcode = 'P0001', message = 'invalid_request', detail = 'date of birth';
  end if;
  return new;
end;
$$;

-- Sign-up: optional date of birth and sex from the form.
create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_dob date;
begin
  begin
    v_dob := nullif(new.raw_user_meta_data ->> 'date_of_birth', '')::date;
    if v_dob not between date '1900-01-01' and (current_date - interval '10 years')::date then v_dob := null; end if;
  exception when others then v_dob := null;
  end;
  insert into public.customer_accounts (id, full_name, accepted_terms_at, date_of_birth, sex)
  values (
    new.id,
    left(nullif(btrim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), ''), 120),
    case when (new.raw_user_meta_data ->> 'accepted_terms') = 'true' then now() end,
    v_dob,
    case when new.raw_user_meta_data ->> 'sex' in ('female', 'male') then new.raw_user_meta_data ->> 'sex' end)
  on conflict (id) do nothing;
  return new;
end;
$$;

-- Staff change a customer's details (now with date of birth and sex).
drop function if exists public.admin_update_customer_details(uuid, text, text, text);
create or replace function public.admin_update_customer_details(
  p_user_id uuid, p_full_name text, p_phone text, p_old_email text default null, p_date_of_birth date default null, p_sex text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_before public.customer_accounts;
begin
  perform private.require_permission('customers.manage');
  if p_user_id is null or not exists (select 1 from auth.users where id = p_user_id) then perform private.app_error('not_found'); end if;
  if exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('invalid_request', 'staff account'); end if;
  if char_length(btrim(coalesce(p_full_name, ''))) not between 2 and 120 then perform private.app_error('invalid_name'); end if;
  if p_phone is not null and p_phone !~ '^\+251[79][0-9]{8}$' then perform private.app_error('invalid_phone'); end if;
  if p_sex is not null and p_sex not in ('female', 'male') then perform private.app_error('invalid_request', 'sex'); end if;
  if p_date_of_birth is not null and p_date_of_birth not between date '1900-01-01' and (current_date - interval '10 years')::date then
    perform private.app_error('invalid_request', 'date of birth');
  end if;
  insert into public.customer_accounts (id) values (p_user_id) on conflict do nothing;
  select * into v_before from public.customer_accounts where id = p_user_id for update;
  update public.customer_accounts
     set full_name = btrim(p_full_name), phone = p_phone, date_of_birth = p_date_of_birth, sex = p_sex
   where id = p_user_id;
  perform private.audit('profile_updated', 'customer_account', p_user_id::text,
    jsonb_strip_nulls(jsonb_build_object('full_name', v_before.full_name, 'phone', v_before.phone, 'email', p_old_email,
      'date_of_birth', v_before.date_of_birth, 'sex', v_before.sex)),
    jsonb_strip_nulls(jsonb_build_object('full_name', btrim(p_full_name), 'phone', p_phone,
      'email', case when p_old_email is not null then (select u.email::text from auth.users u where u.id = p_user_id) end,
      'date_of_birth', p_date_of_birth, 'sex', p_sex)),
    jsonb_build_object('by', 'staff'));
end;
$$;
revoke all on function public.admin_update_customer_details(uuid, text, text, text, date, text) from public, anon;
grant execute on function public.admin_update_customer_details(uuid, text, text, text, date, text) to authenticated;

-- Super Admin: a staff member's personal details (recorded by the profiles audit trigger).
create or replace function public.admin_update_staff_details(p_user_id uuid, p_full_name text, p_phone text, p_date_of_birth date, p_sex text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('staff.manage');
  if char_length(btrim(coalesce(p_full_name, ''))) not between 1 and 120 then perform private.app_error('invalid_name'); end if;
  if p_phone is not null and p_phone !~ '^\+251[79][0-9]{8}$' then perform private.app_error('invalid_phone'); end if;
  if p_sex is not null and p_sex not in ('female', 'male') then perform private.app_error('invalid_request', 'sex'); end if;
  if p_date_of_birth is not null and p_date_of_birth not between date '1900-01-01' and (current_date - interval '14 years')::date then
    perform private.app_error('invalid_request', 'date of birth');
  end if;
  update public.profiles
     set full_name = btrim(p_full_name), phone = p_phone, date_of_birth = p_date_of_birth, sex = p_sex
   where id = p_user_id and removed_at is null;
  if not found then perform private.app_error('not_found'); end if;
end;
$$;
revoke all on function public.admin_update_staff_details(uuid, text, text, date, text) from public, anon;
grant execute on function public.admin_update_staff_details(uuid, text, text, date, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000048_manage_services.sql
-- =============================================================================
-- 0048 MANAGE SERVICES
-- Super Admin switches customer services on / off (Admin → Manage services).
-- A switched-off service is refused by the database (not only hidden on the
-- website): ordering / paying for products, printing (upload and payment),
-- wallet (top-ups and paying with the balance), writing reviews. New sign-ups
-- are switched off on the website. Customers see "temporarily unavailable".
-- Delivery / pickup keep their own switches under Settings → Delivery.
-- =============================================================================
insert into public.website_settings (key, value, is_public)
values ('services', '{"shop": true, "printing": true, "wallet": true, "reviews": true, "signup": true, "note": {"en": "", "am": ""}}', true)
on conflict (key) do nothing;

create or replace function private.service_on(p_service text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((private.setting('services') ->> p_service)::boolean, true)
$$;
grant execute on function private.service_on(text) to authenticated, service_role;

-- Order lines: products need the shop, printing lines need printing.
create or replace function private.order_item_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.item_type = 'product' and not private.service_on('shop') then perform private.app_error('service_unavailable', 'shop'); end if;
  if new.item_type = 'printing' and not private.service_on('printing') then perform private.app_error('service_unavailable', 'printing'); end if;
  return new;
end;
$$;
drop trigger if exists order_item_service_check on public.order_items;
create trigger order_item_service_check before insert on public.order_items
  for each row execute function private.order_item_service_check();

-- Paying with the balance needs the wallet.
create or replace function private.order_wallet_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.payment_method = 'wallet' and (tg_op = 'INSERT' or old.payment_method is distinct from 'wallet') and not private.service_on('wallet') then
    perform private.app_error('service_unavailable', 'wallet');
  end if;
  return new;
end;
$$;
drop trigger if exists order_wallet_service_check on public.orders;
create trigger order_wallet_service_check before insert or update of payment_method on public.orders
  for each row execute function private.order_wallet_service_check();

-- Uploading a payment receipt: refused while the order's service is off.
create or replace function private.payment_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.service_on('shop') and exists (select 1 from public.order_items i where i.order_id = new.order_id and i.item_type = 'product') then
    perform private.app_error('service_unavailable', 'shop');
  end if;
  if not private.service_on('printing') and exists (select 1 from public.order_items i where i.order_id = new.order_id and i.item_type = 'printing') then
    perform private.app_error('service_unavailable', 'printing');
  end if;
  return new;
end;
$$;
drop trigger if exists payment_service_check on public.payment_submissions;
create trigger payment_service_check before insert on public.payment_submissions
  for each row execute function private.payment_service_check();

-- Printing: no new jobs (uploads).
create or replace function private.printing_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.service_on('printing') then perform private.app_error('service_unavailable', 'printing'); end if;
  return new;
end;
$$;
drop trigger if exists printing_service_check on public.printing_jobs;
create trigger printing_service_check before insert on public.printing_jobs
  for each row execute function private.printing_service_check();

-- Wallet: no new top-ups.
create or replace function private.topup_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.service_on('wallet') then perform private.app_error('service_unavailable', 'wallet'); end if;
  return new;
end;
$$;
drop trigger if exists topup_service_check on public.wallet_topups;
create trigger topup_service_check before insert on public.wallet_topups
  for each row execute function private.topup_service_check();

-- Reviews: no new reviews.
create or replace function private.review_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not private.service_on('reviews') then perform private.app_error('service_unavailable', 'reviews'); end if;
  return new;
end;
$$;
drop trigger if exists review_service_check on public.product_reviews;
create trigger review_service_check before insert on public.product_reviews
  for each row execute function private.review_service_check();

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000049_instore_clear_tools.sql
-- =============================================================================
-- 0049 IN-STORE SALES, CLEARING WITH AN EXPORT FIRST, CLEARING THE REVIEWED LIST
--   * In-store (walk-in) sales are recorded in the dashboard as orders with
--     channel 'in_store': paid and completed at once, stock taken, counted in
--     orders, dashboard, analytics and sales reports. A sale can be voided
--     (stock comes back). Online-shop switches do not affect the counter.
--   * Activity log and notifications can be cleared for any date range, only
--     after the same admin exported that range to Excel (last 30 minutes).
--   * "Recently reviewed" security entries can be cleared from the list (the
--     review itself stays, so the alert does not come back).
-- =============================================================================

-- ---------------------------------------------------------------- In-store sales
alter table public.orders add column channel text not null default 'online' check (channel in ('online', 'in_store'));
alter table public.orders drop constraint orders_payment_method_check;
alter table public.orders add constraint orders_payment_method_check
  check (payment_method in ('bank_transfer', 'wallet', 'cash', 'mobile_money'));
create index orders_channel_idx on public.orders(channel, created_at desc) where channel = 'in_store';

-- Online orders need the customer's account; a counter sale has none.
create or replace function private.require_ordering_user()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_table_name = 'orders' then
    if to_jsonb(new) ->> 'channel' = 'in_store' then return new; end if;
  end if;
  new.user_id := coalesce(new.user_id, nullif(current_setting('app.ordering_user_id', true), '')::uuid);
  if new.user_id is null then
    raise exception using errcode = 'P0001', message = 'login_required';
  end if;
  return new;
end;
$$;

-- Pausing the online shop does not stop sales at the counter.
create or replace function private.order_item_service_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.orders o where o.id = new.order_id and o.channel = 'in_store') then return new; end if;
  if new.item_type = 'product' and not private.service_on('shop') then perform private.app_error('service_unavailable', 'shop'); end if;
  if new.item_type = 'printing' and not private.service_on('printing') then perform private.app_error('service_unavailable', 'printing'); end if;
  return new;
end;
$$;

-- Staff record a counter sale: [{product_id, quantity}], payment method, optional customer and discount.
create or replace function public.admin_create_instore_sale(
  p_items jsonb, p_payment_method text, p_customer_name text default null, p_customer_phone text default null,
  p_discount_etb numeric default 0, p_note text default null, p_idempotency_key uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key uuid := coalesce(p_idempotency_key, gen_random_uuid());
  v_existing public.orders;
  v_name text := coalesce(nullif(btrim(coalesce(p_customer_name, '')), ''), 'Walk-in customer');
  v_phone text := coalesce(nullif(btrim(coalesce(p_customer_phone, '')), ''), '+251900000000');
  v_customer uuid;
  v_order uuid;
  v_number text;
  v_subtotal numeric := 0;
  v_discount numeric := coalesce(p_discount_etb, 0);
  v_after integer;
  r record;
  p public.products;
begin
  perform private.require_permission('orders.manage');
  select * into v_existing from public.orders where idempotency_key = v_key;
  if found then return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number, 'total_etb', v_existing.total_etb, 'replayed', true); end if;
  if p_payment_method not in ('cash', 'bank_transfer', 'mobile_money') then perform private.app_error('invalid_request', 'payment method'); end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) not between 1 and 50 then perform private.app_error('invalid_cart'); end if;
  if char_length(v_name) not between 2 and 120 then perform private.app_error('invalid_name'); end if;
  if v_phone !~ '^\+251[79][0-9]{8}$' then perform private.app_error('invalid_phone'); end if;
  if p_note is not null and char_length(p_note) > 500 then perform private.app_error('invalid_request', 'note'); end if;
  if v_discount < 0 or v_discount <> round(v_discount, 2) then perform private.app_error('invalid_amount'); end if;

  -- Lines at today's price, locked in a stable order.
  create temp table if not exists pg_temp.instore_lines (product_id uuid, qty integer) on commit drop;
  delete from pg_temp.instore_lines where true;
  insert into pg_temp.instore_lines
  select (x ->> 'product_id')::uuid, sum((x ->> 'quantity')::integer)
    from jsonb_array_elements(p_items) x group by 1;
  if exists (select 1 from pg_temp.instore_lines where qty is null or qty not between 1 and 1000) then perform private.app_error('invalid_quantity'); end if;
  for r in select l.product_id, l.qty from pg_temp.instore_lines l order by l.product_id loop
    select * into p from public.products where id = r.product_id and status <> 'archived' for update;
    if not found then perform private.app_error('product_unavailable'); end if;
    if p.track_inventory and p.stock_quantity < r.qty then perform private.app_error('insufficient_stock', p.sku); end if;
    v_subtotal := v_subtotal + p.effective_price_etb * r.qty;
  end loop;
  if v_discount >= v_subtotal then perform private.app_error('invalid_amount', 'discount'); end if;

  insert into public.customers (full_name, phone) values (v_name, v_phone)
  on conflict (phone) do update set full_name = case when excluded.phone = '+251900000000' then public.customers.full_name else excluded.full_name end
  returning id into v_customer;

  insert into public.orders (access_token_hash, tracking_code_hash, idempotency_key, customer_id, customer_name, customer_phone,
                             fulfillment_method, subtotal_etb, delivery_fee_etb, discount_etb, total_etb, status, payment_status,
                             payment_method, bank_snapshot, payment_due_at, payment_verified_at, payment_verified_by, channel)
  values (encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex'), encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex'),
          v_key, v_customer, v_name, v_phone, 'pickup', v_subtotal, 0, v_discount, v_subtotal - v_discount, 'completed', 'verified',
          p_payment_method, jsonb_build_object('in_store', true, 'note', nullif(btrim(coalesce(p_note, '')), '')), now(), now(), (select auth.uid()), 'in_store')
  returning id, order_number into v_order, v_number;

  for r in select l.product_id, l.qty from pg_temp.instore_lines l order by l.product_id loop
    select * into p from public.products where id = r.product_id;
    insert into public.order_items (order_id, item_type, product_id, name_en, name_am, sku, unit_price_etb, quantity, line_total_etb)
    values (v_order, 'product', p.id, p.name_en, p.name_am, p.sku, p.effective_price_etb, r.qty, p.effective_price_etb * r.qty);
    if p.track_inventory then
      update public.products set stock_quantity = stock_quantity - r.qty where id = p.id returning stock_quantity into v_after;
      insert into public.inventory_movements (product_id, change, quantity_after, reason, order_id, note, actor_id)
      values (p.id, -r.qty, v_after, 'order_reserved', v_order, 'In-store sale', (select auth.uid()));
    end if;
  end loop;

  perform private.audit('instore_sale', 'order', v_order::text, null,
    jsonb_build_object('order_number', v_number, 'total_etb', v_subtotal - v_discount, 'payment_method', p_payment_method),
    jsonb_build_object('order_number', v_number));
  return jsonb_build_object('order_id', v_order, 'order_number', v_number, 'total_etb', v_subtotal - v_discount, 'replayed', false);
end;
$$;
revoke all on function public.admin_create_instore_sale(jsonb, text, text, text, numeric, text, uuid) from public, anon;
grant execute on function public.admin_create_instore_sale(jsonb, text, text, text, numeric, text, uuid) to authenticated;

-- Void a counter sale (mistake / return): stock comes back, money marked refunded.
create or replace function public.admin_void_instore_sale(p_order_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  perform private.require_permission('orders.manage');
  if v_reason is null or char_length(v_reason) > 500 then perform private.app_error('note_required'); end if;
  select * into v from public.orders where id = p_order_id and channel = 'in_store' for update;
  if not found then perform private.app_error('not_found'); end if;
  if v.status = 'cancelled' then perform private.app_error('invalid_transition', 'already voided'); end if;
  perform private.release_order_stock(v.id);
  perform private.set_status_note('Sale voided: ' || v_reason);
  update public.orders set status = 'cancelled', payment_status = 'refunded', cancelled_at = now() where id = v.id;
  perform private.audit('instore_sale_voided', 'order', v.id::text, null, jsonb_build_object('reason', v_reason),
    jsonb_build_object('order_number', v.order_number, 'total_etb', v.total_etb));
end;
$$;
revoke all on function public.admin_void_instore_sale(uuid, text) from public, anon;
grant execute on function public.admin_void_instore_sale(uuid, text) to authenticated;

-- Sales report: in-store money (cash / mobile money / transfer at the counter) counted separately.
create or replace function public.admin_sales_report(p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_from timestamptz;
  v_to   timestamptz;
  v jsonb;
begin
  perform private.require_permission('analytics.view');
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then
    perform private.app_error('invalid_request');
  end if;
  v_from := p_from::timestamp at time zone 'Europe/Warsaw';
  v_to   := (p_to + 1)::timestamp at time zone 'Europe/Warsaw';

  with
  placed as (select * from public.orders where created_at >= v_from and created_at < v_to),
  paid as (select * from public.orders where payment_verified_at >= v_from and payment_verified_at < v_to
             and payment_status in ('verified', 'refunded')),
  paid_items as (select i.* from public.order_items i join paid o on o.id = i.order_id),
  topups as (select * from public.wallet_topups where status = 'verified' and reviewed_at >= v_from and reviewed_at < v_to),
  cancelled_paid as (
    select o.*, h.created_at as cancelled_on from public.orders o
      join lateral (select created_at from public.order_status_history
                     where order_id = o.id and to_status = 'cancelled' order by id desc limit 1) h on true
     where o.status = 'cancelled' and o.payment_verified_at is not null
       and h.created_at >= v_from and h.created_at < v_to),
  wallet_refunds as (select * from public.wallet_ledger where kind = 'refund' and created_at >= v_from and created_at < v_to),
  days as (select generate_series(p_from::timestamp, p_to::timestamp, interval '1 day')::date as d),
  addis as (select o.*, (o.payment_verified_at at time zone 'Europe/Warsaw')::date as d from paid o)
  select jsonb_build_object(
    'from', p_from, 'to', p_to,
    'totals', jsonb_build_object(
      'orders_placed', (select count(*) from placed),
      'orders_paid', (select count(*) from paid),
      'sales', (select coalesce(sum(total_etb), 0) from paid),
      'products_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'product'),
      'printing_sales', (select coalesce(sum(line_total_etb), 0) from paid_items where item_type = 'printing'),
      'delivery_fees', (select coalesce(sum(delivery_fee_etb), 0) from paid),
      'discounts', (select coalesce(sum(discount_etb), 0) from paid),
      'average_order', (select coalesce(round(avg(total_etb), 2), 0) from paid),
      'paid_by_bank', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer' and channel = 'online'),
      'in_store_sales', (select coalesce(sum(total_etb), 0) from paid where channel = 'in_store'),
      'in_store_count', (select count(*) from paid where channel = 'in_store'),
      'in_store_cash', (select coalesce(sum(total_etb), 0) from paid where channel = 'in_store' and payment_method = 'cash'),
      'in_store_mobile', (select coalesce(sum(total_etb), 0) from paid where channel = 'in_store' and payment_method = 'mobile_money'),
      'in_store_bank', (select coalesce(sum(total_etb), 0) from paid where channel = 'in_store' and payment_method = 'bank_transfer'),
      'paid_by_wallet', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'wallet'),
      'topups_count', (select count(*) from topups),
      'topups_amount', (select coalesce(sum(amount_etb), 0) from topups),
      'cash_in', (select coalesce(sum(total_etb), 0) from paid where payment_method = 'bank_transfer' and channel = 'online')
                 + (select coalesce(sum(total_etb), 0) from paid where channel = 'in_store')
                 + (select coalesce(sum(amount_etb), 0) from topups),
      'cancelled_after_payment_count', (select count(*) from cancelled_paid),
      'cancelled_after_payment_bank', (select coalesce(sum(total_etb), 0) from cancelled_paid where payment_method = 'bank_transfer'),
      'wallet_refunds', (select coalesce(sum(amount_etb), 0) from wallet_refunds)),
    'by_bank', (
      select coalesce(jsonb_agg(x order by x ->> 'bank', x ->> 'account'), '[]'::jsonb) from (
        select jsonb_build_object('bank', bank, 'account', account,
                 'orders', sum(orders), 'orders_amount', sum(orders_amount), 'topups', sum(topups), 'topups_amount', sum(topups_amount),
                 'total', sum(orders_amount) + sum(topups_amount)) as x
          from (
            select coalesce(bank_snapshot ->> 'bank_name', '—') as bank, coalesce(bank_snapshot ->> 'account_number', '—') as account,
                   count(*) as orders, sum(total_etb) as orders_amount, 0 as topups, 0::numeric as topups_amount
              from paid where payment_method = 'bank_transfer' and channel = 'online' group by 1, 2
            union all
            select coalesce(bank_snapshot ->> 'bank_name', '—'), coalesce(bank_snapshot ->> 'account_number', '—'), 0, 0, count(*), sum(amount_etb)
              from topups group by 1, 2) u
         group by bank, account) t),
    'by_day', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'day', dd.d,
               'placed', (select count(*) from placed o where (o.created_at at time zone 'Europe/Warsaw')::date = dd.d),
               'paid', (select count(*) from addis a where a.d = dd.d),
               'sales', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d),
               'bank', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'bank_transfer'),
               'wallet', (select coalesce(sum(a.total_etb), 0) from addis a where a.d = dd.d and a.payment_method = 'wallet'),
               'topups', (select coalesce(sum(t.amount_etb), 0) from topups t where (t.reviewed_at at time zone 'Europe/Warsaw')::date = dd.d))
             order by dd.d), '[]'::jsonb) from days dd),
    'by_staff', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'payments', n, 'amount', amount) order by n desc), '[]'::jsonb) from (
        select private.actor_name(payment_verified_by) as name, count(*) as n, sum(total_etb) as amount
          from paid where payment_method = 'bank_transfer' group by payment_verified_by) s),
    'top_products', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name_en, 'sku', sku, 'quantity', q, 'amount', amount) order by q desc, amount desc), '[]'::jsonb) from (
        select name_en, sku, sum(quantity) as q, sum(line_total_etb) as amount
          from paid_items where item_type = 'product' group by name_en, sku order by 3 desc, 4 desc limit 15) tp),
    'cancelled_after_payment', (
      select coalesce(jsonb_agg(jsonb_build_object('order_number', c.order_number, 'total', c.total_etb, 'method', c.payment_method,
               'cancelled_at', c.cancelled_on, 'customer', c.customer_name) order by c.cancelled_on), '[]'::jsonb)
        from cancelled_paid c)
  ) into v;
  return v;
end;
$$;

-- ---------------------------------------------------------------- Export first, then clear
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- Did this admin export (at least) these days in the last 30 minutes?
create or replace function private.exported_recently(p_kind text, p_from date, p_to date)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.audit_logs a
     where a.action = 'export_' || p_kind and a.actor_id = (select auth.uid()) and a.created_at > now() - interval '30 minutes'
       and (a.metadata ->> 'from') ~ '^\d{4}-\d{2}-\d{2}$' and (a.metadata ->> 'to') ~ '^\d{4}-\d{2}-\d{2}$'
       and (a.metadata ->> 'from')::date <= p_from and (a.metadata ->> 'to')::date >= p_to
       and coalesce(a.metadata ->> 'type', 'all') = 'all')
$$;

-- Activity log: clear any date range (Warsaw days, inclusive) once it was exported.
create or replace function public.admin_clear_audit_range(p_from date, p_to date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  perform private.require_permission('audit.manage');
  if p_from is null or p_to is null or p_to < p_from or p_to > (now() at time zone 'Europe/Warsaw')::date then perform private.app_error('invalid_request', 'dates'); end if;
  if not private.exported_recently('activity', p_from, p_to) then perform private.app_error('invalid_request', 'export_first'); end if;
  perform set_config('app.audit_purge', 'on', true);
  with d as (
    delete from public.audit_logs
     where created_at >= (p_from::timestamp at time zone 'Europe/Warsaw') and created_at < ((p_to + 1)::timestamp at time zone 'Europe/Warsaw')
       and action not in ('audit_cleared', 'data_reset', 'notifications_cleared') and action not like 'export\_%'
    returning 1)
  select count(*)::integer into v_count from d;
  perform set_config('app.audit_purge', '', true);
  perform private.audit('audit_cleared', 'audit', null, null, null, jsonb_build_object('from', p_from, 'to', p_to, 'deleted', v_count));
  return v_count;
end;
$$;
revoke all on function public.admin_clear_audit_range(date, date) from public, anon;
grant execute on function public.admin_clear_audit_range(date, date) to authenticated;

-- Notifications: rows for the Excel export.
create or replace function public.admin_notifications_export(p_from date, p_to date)
returns table (id bigint, created_at timestamptz, sent_at timestamptz, channel text, event_type text, status text, attempts integer,
               reference text, recipient text, last_error text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then perform private.app_error('invalid_request', 'dates'); end if;
  return query
    select o.id, o.created_at, o.sent_at, o.channel, o.event_type, o.status::text, o.attempts,
           coalesce(o.payload ->> 'order_number', o.payload ->> 'job_number', o.payload ->> 'number', o.payload ->> 'label'),
           (select u.email::text from auth.users u where u.id = o.recipient_user_id), o.last_error
      from public.notifications_outbox o
     where o.created_at >= (p_from::timestamp at time zone 'Europe/Warsaw') and o.created_at < ((p_to + 1)::timestamp at time zone 'Europe/Warsaw')
     order by o.id;
end;
$$;
revoke all on function public.admin_notifications_export(date, date) from public, anon;
grant execute on function public.admin_notifications_export(date, date) to authenticated;

-- Notifications: clear a date range once exported (messages still waiting to be sent are kept).
create or replace function public.admin_clear_notifications(p_from date, p_to date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  perform private.require_permission('settings.manage');
  if p_from is null or p_to is null or p_to < p_from or p_to > (now() at time zone 'Europe/Warsaw')::date then perform private.app_error('invalid_request', 'dates'); end if;
  if not private.exported_recently('notifications', p_from, p_to) then perform private.app_error('invalid_request', 'export_first'); end if;
  with d as (
    delete from public.notifications_outbox
     where created_at >= (p_from::timestamp at time zone 'Europe/Warsaw') and created_at < ((p_to + 1)::timestamp at time zone 'Europe/Warsaw')
       and status in ('sent', 'dead', 'failed')
    returning 1)
  select count(*)::integer into v_count from d;
  perform private.audit('notifications_cleared', 'notifications', null, null, null, jsonb_build_object('from', p_from, 'to', p_to, 'deleted', v_count));
  return v_count;
end;
$$;
revoke all on function public.admin_clear_notifications(date, date) from public, anon;
grant execute on function public.admin_clear_notifications(date, date) to authenticated;

-- ---------------------------------------------------------------- Reviewed list
alter table public.security_reviews add column hidden_at timestamptz;

create or replace function public.admin_mark_security_reviewed(p_type text, p_subjects text[], p_note text default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  perform private.require_permission('security.manage');
  if p_type not in ('email', 'customer') or p_subjects is null or cardinality(p_subjects) <> 1 then
    perform private.app_error('invalid_request', 'review one alert at a time');
  end if;
  if p_note is not null and char_length(p_note) > 500 then perform private.app_error('invalid_request', 'note'); end if;
  insert into public.security_reviews (subject_type, subject, reviewed_at, reviewed_by, note)
  select p_type, lower(btrim(s)), now(), auth.uid(), nullif(btrim(p_note), '')
    from unnest(p_subjects) s
   where char_length(btrim(s)) between 3 and 320
  on conflict (subject_type, subject) do update set reviewed_at = excluded.reviewed_at, reviewed_by = excluded.reviewed_by, note = excluded.note, hidden_at = null;
  get diagnostics v_n = row_count;
  perform private.audit('security_reviewed', 'security', p_type, null, null,
                        jsonb_build_object('type', p_type, 'count', v_n, 'subjects', to_jsonb(p_subjects), 'note', p_note));
  return v_n;
end;
$$;


create or replace function public.admin_security_reviews(p_limit integer default 50)
returns table (subject_type text, subject text, reviewed_at timestamptz, reviewed_by_name text, note text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  return query
    select r.subject_type, case when r.subject_type = 'customer' then coalesce((select u.email::text from auth.users u where u.id::text = r.subject), r.subject) else r.subject end,
           r.reviewed_at, private.actor_name(r.reviewed_by), r.note
      from public.security_reviews r
     where r.hidden_at is null
     order by r.reviewed_at desc limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;

-- Clear one entry (type + subject) or the whole "Recently reviewed" list. The review stays in force.
create or replace function public.admin_clear_reviewed_list(p_type text default null, p_subject text default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  perform private.require_permission('security.manage');
  update public.security_reviews r set hidden_at = now()
   where r.hidden_at is null
     and (p_type is null or (r.subject_type = p_type and (r.subject = lower(btrim(p_subject))
          or (p_type = 'customer' and r.subject in (select u.id::text from auth.users u where lower(u.email) = lower(btrim(p_subject)))))));
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;
revoke all on function public.admin_clear_reviewed_list(text, text) from public, anon;
grant execute on function public.admin_clear_reviewed_list(text, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000050_search_permissions.sql
-- =============================================================================
-- 0050 SEARCH BY DATE, PERMISSION SETS, PERSONAL PERMISSIONS
--   * Security events, activity log and notifications can be searched by
--     text and a date range.
--   * Super Admin manages permission sets (roles): edit what Manager / Staff
--     can do, create new sets, assign them. Super Admin keeps everything.
--   * Extra permissions for one staff member or manager on top of their set.
--   * "Manage staff" (staff.manage) stays Super Admin only.
-- =============================================================================

-- ---------------------------------------------------------------- Search with dates
drop function if exists public.admin_security_events(text, text, integer);
create or replace function public.admin_security_events(
  p_kind text default null, p_email text default null, p_limit integer default 100,
  p_from timestamptz default null, p_to timestamptz default null, p_search text default null)
returns table (id bigint, kind text, email text, user_name text, ip_hash text, user_agent text, metadata jsonb, created_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('audit.view');
  return query
    select s.id, s.kind, s.email, private.actor_name(s.user_id), left(s.ip_hash, 8), s.user_agent, s.metadata, s.created_at
      from public.security_events s
     where (p_kind is null or s.kind = p_kind) and (p_email is null or s.email = lower(btrim(p_email)))
       and (p_from is null or s.created_at >= p_from) and (p_to is null or s.created_at < p_to)
       and (v_q is null or s.email ilike '%' || v_q || '%' or s.kind ilike '%' || v_q || '%' or s.user_agent ilike '%' || v_q || '%'
            or s.ip_hash ilike v_q || '%')
     order by s.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 1000));
end;
$$;
revoke all on function public.admin_security_events(text, text, integer, timestamptz, timestamptz, text) from public, anon;
grant execute on function public.admin_security_events(text, text, integer, timestamptz, timestamptz, text) to authenticated;

drop function if exists public.admin_activity_by_category(text, text, integer, bigint);
create or replace function public.admin_activity_by_category(
  p_category text default null, p_search text default null, p_limit integer default 100, p_before_id bigint default null,
  p_from timestamptz default null, p_to timestamptz default null)
returns table (
  id bigint, created_at timestamptz, actor_id uuid, actor_name text, actor_role text,
  action text, entity_type text, entity_id text, entity_label text,
  before_data jsonb, after_data jsonb, metadata jsonb, category text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('audit.view');
  if p_category is not null and p_category not in ('orders', 'payments', 'customers', 'catalog', 'staff', 'security', 'other') then
    perform private.app_error('invalid_request', 'category');
  end if;
  return query
    select a.id, a.created_at, a.actor_id, private.actor_name(a.actor_id), a.actor_role,
           a.action, a.entity_type, a.entity_id,
           case a.entity_type
             when 'order' then (select o.order_number from public.orders o where o.id::text = a.entity_id)
             when 'printing_job' then (select j.job_number from public.printing_jobs j where j.id::text = a.entity_id)
             when 'payment_submission' then (select o.order_number from public.payment_submissions s join public.orders o on o.id = s.order_id where s.id::text = a.entity_id)
             when 'customer_account' then coalesce(
               (select u.email::text from auth.users u where u.id::text = a.entity_id), a.before_data ->> 'email')
             when 'profiles' then private.actor_name(case when a.entity_id ~ '^[0-9a-f-]{36}$' then a.entity_id::uuid end)
             when 'products' then coalesce(a.after_data ->> 'name_en', a.before_data ->> 'name_en')
             else null
           end,
           a.before_data, a.after_data, a.metadata, private.activity_category(a.action, a.entity_type)
      from public.audit_logs a
     where (p_category is null or private.activity_category(a.action, a.entity_type) = p_category)
       and (p_before_id is null or a.id < p_before_id)
       and (p_from is null or a.created_at >= p_from) and (p_to is null or a.created_at < p_to)
       and (v_q is null or a.action ilike '%' || v_q || '%' or a.entity_id ilike '%' || v_q || '%'
            or private.actor_name(a.actor_id) ilike '%' || v_q || '%')
     order by a.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

revoke all on function public.admin_activity_by_category(text, text, integer, bigint, timestamptz, timestamptz) from public, anon;
grant execute on function public.admin_activity_by_category(text, text, integer, bigint, timestamptz, timestamptz) to authenticated;

create or replace function public.admin_notifications_search(p_from timestamptz default null, p_to timestamptz default null, p_search text default null, p_limit integer default 600)
returns table (
  id bigint, channel text, event_type text, status public.notification_status, attempts integer, max_attempts integer,
  last_error text, created_at timestamptz, sent_at timestamptz, next_attempt_at timestamptz, reference text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('settings.manage');
  return query
    select o.id, o.channel, o.event_type, o.status, o.attempts, o.max_attempts, o.last_error, o.created_at, o.sent_at, o.next_attempt_at,
           coalesce(o.payload ->> 'order_number', o.payload ->> 'job_number', o.payload ->> 'number', o.payload ->> 'topup_number',
                    o.payload ->> 'email', o.payload ->> 'name', o.payload ->> 'label')
      from public.notifications_outbox o
     where (p_from is null or o.created_at >= p_from) and (p_to is null or o.created_at < p_to)
       and (v_q is null or o.event_type ilike '%' || v_q || '%' or o.channel ilike '%' || v_q || '%' or o.last_error ilike '%' || v_q || '%'
            or o.payload::text ilike '%' || v_q || '%'
            or exists (select 1 from auth.users u where u.id = o.recipient_user_id and u.email ilike '%' || v_q || '%'))
     order by o.id desc
     limit greatest(1, least(coalesce(p_limit, 600), 2000));
end;
$$;
revoke all on function public.admin_notifications_search(timestamptz, timestamptz, text, integer) from public, anon;
grant execute on function public.admin_notifications_search(timestamptz, timestamptz, text, integer) to authenticated;

-- ---------------------------------------------------------------- Personal permissions
create table public.profile_permissions (
  profile_id     uuid not null references public.profiles(id) on delete cascade,
  permission_key text not null references public.admin_permissions(key) on delete cascade,
  granted_by     uuid references auth.users(id) on delete set null default auth.uid(),
  granted_at     timestamptz not null default now(),
  primary key (profile_id, permission_key)
);
alter table public.profile_permissions enable row level security;
revoke all on public.profile_permissions from anon, authenticated;
grant select on public.profile_permissions to authenticated;
create policy profile_permissions_read on public.profile_permissions for select to authenticated using ((select private.is_admin()));
create trigger audit_profile_permissions after insert or delete on public.profile_permissions
  for each row execute function private.audit_row_change();

-- Permission = from the person's set OR given to them personally.
create or replace function private.has_permission(p_permission text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.mfa_verified() and exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid()) and p.is_active
      and (exists (select 1 from public.role_permissions rp where rp.role_id = p.role_id and rp.permission_key = p_permission)
        or exists (select 1 from public.profile_permissions pp where pp.profile_id = p.id and pp.permission_key = p_permission))
  )
$$;

create or replace function public.my_admin_context()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when p.id is null then null else jsonb_build_object(
    'user_id', p.id,
    'full_name', p.full_name,
    'role', r.key,
    'role_name', r.name,
    'permissions', coalesce((
      select jsonb_agg(k order by k) from (
        select rp.permission_key as k from public.role_permissions rp where rp.role_id = p.role_id
        union
        select pp.permission_key from public.profile_permissions pp where pp.profile_id = p.id) x
    ), '[]'::jsonb)
  ) end
  from (select 1) d
  left join public.profiles p on p.id = (select auth.uid()) and p.is_active and private.mfa_verified()
  left join public.admin_roles r on r.id = p.role_id
$$;

-- ---------------------------------------------------------------- Permission sets (roles)
alter table public.admin_roles add column is_builtin boolean not null default false;
update public.admin_roles set is_builtin = true where key in ('super_admin', 'manager', 'staff');

-- Checks a list of permission keys (staff.manage stays with Super Admin).
create or replace function private.check_permission_list(p_permissions text[])
returns text[]
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v text[] := coalesce((select array_agg(distinct btrim(x)) from unnest(coalesce(p_permissions, '{}')) x where btrim(x) <> ''), '{}');
begin
  if exists (select 1 from unnest(v) x where x not in (select key from public.admin_permissions)) then
    perform private.app_error('invalid_request', 'unknown permission');
  end if;
  if 'staff.manage' = any(v) then perform private.app_error('invalid_request', 'staff.manage is Super Admin only'); end if;
  return v;
end;
$$;

create or replace function public.admin_save_role(p_role_id smallint, p_name text, p_description text, p_permissions text[])
returns smallint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id smallint := p_role_id;
  v_key text;
  v_perms text[];
  v_role public.admin_roles;
begin
  perform private.require_permission('staff.manage');
  if char_length(btrim(coalesce(p_name, ''))) not between 2 and 60 then perform private.app_error('invalid_name'); end if;
  if p_description is not null and char_length(p_description) > 300 then perform private.app_error('invalid_request', 'description'); end if;
  v_perms := private.check_permission_list(p_permissions);
  perform pg_advisory_xact_lock(hashtext('staff_roles'));
  if v_id is null then
    v_key := left(trim(both '_' from regexp_replace(lower(btrim(p_name)), '[^a-z]+', '_', 'g')), 30);
    if char_length(v_key) < 2 then v_key := 'role'; end if;
    while exists (select 1 from public.admin_roles where key = v_key) loop
      v_key := left(v_key, 26) || '_' || floor(random() * 900 + 100)::int;
    end loop;
    insert into public.admin_roles (key, name, description) values (v_key, btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''))
    returning id into v_id;
  else
    select * into v_role from public.admin_roles where id = v_id;
    if not found then perform private.app_error('not_found'); end if;
    if v_role.key = 'super_admin' then perform private.app_error('invalid_request', 'Super Admin always has every permission'); end if;
    update public.admin_roles set name = btrim(p_name), description = nullif(btrim(coalesce(p_description, '')), '') where id = v_id;
  end if;
  delete from public.role_permissions where role_id = v_id and permission_key <> all(v_perms);
  insert into public.role_permissions (role_id, permission_key) select v_id, x from unnest(v_perms) x on conflict do nothing;
  return v_id;
end;
$$;
revoke all on function public.admin_save_role(smallint, text, text, text[]) from public, anon;
grant execute on function public.admin_save_role(smallint, text, text, text[]) to authenticated;

create or replace function public.admin_delete_role(p_role_id smallint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.admin_roles;
begin
  perform private.require_permission('staff.manage');
  select * into v from public.admin_roles where id = p_role_id;
  if not found then perform private.app_error('not_found'); end if;
  if v.is_builtin then perform private.app_error('invalid_request', 'built-in set'); end if;
  if exists (select 1 from public.profiles where role_id = p_role_id) then perform private.app_error('invalid_request', 'set still assigned'); end if;
  delete from public.admin_roles where id = p_role_id;
end;
$$;
revoke all on function public.admin_delete_role(smallint) from public, anon;
grant execute on function public.admin_delete_role(smallint) to authenticated;

-- Extra permissions for one person (not yourself; not a Super Admin, who has everything).
create or replace function public.admin_set_member_permissions(p_user_id uuid, p_permissions text[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_perms text[];
begin
  perform private.require_permission('staff.manage');
  if p_user_id = (select auth.uid()) then perform private.app_error('cannot_modify_self'); end if;
  if not exists (select 1 from public.profiles where id = p_user_id and removed_at is null) then perform private.app_error('not_found'); end if;
  v_perms := private.check_permission_list(p_permissions);
  delete from public.profile_permissions where profile_id = p_user_id and permission_key <> all(v_perms);
  insert into public.profile_permissions (profile_id, permission_key) select p_user_id, x from unnest(v_perms) x on conflict do nothing;
end;
$$;
revoke all on function public.admin_set_member_permissions(uuid, text[]) from public, anon;
grant execute on function public.admin_set_member_permissions(uuid, text[]) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261120000051_member_id.sql
-- 0051: a unique, random member ID for every account (customers AND staff).
--
-- 6 characters of capital letters and digits, e.g. K7Q2X9. Characters that are
-- easy to confuse (0/O, 1/I/L) are never used. Given automatically when an
-- account is created; existing accounts get one now. It never changes, and
-- customers cannot change it (they may only update their own name / phone /
-- delivery columns). Staff search customers by it.

-- 1. Generator: random until unused.
create or replace function private.new_member_id()
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_chars constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  v_id text;
begin
  loop
    v_id := '';
    for i in 1..6 loop
      v_id := v_id || substr(v_chars, 1 + floor(random() * length(v_chars))::int, 1);
    end loop;
    exit when not exists (select 1 from public.customer_accounts where member_id = v_id);
  end loop;
  return v_id;
end;
$$;
revoke all on function private.new_member_id() from public, anon, authenticated;

-- 2. Column, filled for everyone who already has an account.
alter table public.customer_accounts add column if not exists member_id text;

do $$
declare r record;
begin
  -- every sign-in account has a customer_accounts row (staff included)
  insert into public.customer_accounts (id) select u.id from auth.users u on conflict (id) do nothing;
  for r in select id from public.customer_accounts where member_id is null loop
    update public.customer_accounts set member_id = private.new_member_id() where id = r.id;
  end loop;
end;
$$;

alter table public.customer_accounts alter column member_id set not null;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'customer_accounts_member_id_key') then
    alter table public.customer_accounts add constraint customer_accounts_member_id_key unique (member_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'customer_accounts_member_id_format') then
    alter table public.customer_accounts add constraint customer_accounts_member_id_format
      check (member_id ~ '^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{6}$');
  end if;
end;
$$;

-- 3. New accounts get one automatically; it can never be changed afterwards.
create or replace function private.member_id_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.member_id := private.new_member_id();   -- always generated, never chosen
  elsif new.member_id is distinct from old.member_id then
    new.member_id := old.member_id;
  end if;
  return new;
end;
$$;
revoke all on function private.member_id_guard() from public, anon, authenticated;

drop trigger if exists customer_accounts_member_id on public.customer_accounts;
create trigger customer_accounts_member_id
  before insert or update on public.customer_accounts
  for each row execute function private.member_id_guard();

-- 4. Admin customer list: shows the member ID and searches by it.
drop function if exists public.admin_customer_accounts(text, integer, uuid);
create function public.admin_customer_accounts(p_search text default null, p_limit integer default 100, p_user_id uuid default null)
returns table (
  id uuid, email text, full_name text, phone text, created_at timestamptz,
  email_confirmed_at timestamptz, last_sign_in_at timestamptz, is_staff boolean,
  order_count bigint, last_order_at timestamptz,
  deactivated_at timestamptz, deactivation_reason text, deactivated_by_name text,
  member_id text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('customers.view');
  return query
    select u.id, u.email::text, c.full_name, c.phone, u.created_at, u.email_confirmed_at, u.last_sign_in_at,
           false as is_staff,
           (select count(*) from public.orders o where o.user_id = u.id) as order_count,
           (select max(o.created_at) from public.orders o where o.user_id = u.id) as last_order_at,
           c.deactivated_at, c.deactivation_reason,
           (select p.full_name from public.profiles p where p.id = c.deactivated_by),
           c.member_id
    from auth.users u
    left join public.customer_accounts c on c.id = u.id
    where not exists (select 1 from public.profiles p where p.id = u.id)   -- staff: see Staff
      and (p_user_id is null or u.id = p_user_id)
      and (v_q is null
       or u.email ilike '%' || v_q || '%'
       or c.full_name ilike '%' || v_q || '%'
       or c.phone ilike '%' || v_q || '%'
       or c.member_id = upper(v_q))
    order by u.created_at desc
    limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;
revoke all on function public.admin_customer_accounts(text, integer, uuid) from public, anon;
grant execute on function public.admin_customer_accounts(text, integer, uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261122000052_user_id_sessions_support.sql
-- 0052:
--   * User ID: 6 digits (numbers only, 100000–999999) for every account; shown with
--     every activity-log entry (who did it, and which customer it concerns) and searchable.
--   * Signed-in users: active sessions, last sign-in of every account (date range / before),
--     and sign a user out (Super Admin: security.manage).
--   * App installs: devices that installed the app (list + count).
--   * Printing: staff alerts only once the payment is submitted (documents go to the printing
--     Telegram group at that moment); payment rejected → the job is cancelled and its files are
--     deleted from storage (they stay in Telegram).
--   * Support & feedback tickets (signed-in customers), managed by staff (support.view /
--     support.manage), with their own Telegram group ("support").

-- ============================================================ 1. User ID: 6 digits
create or replace function private.new_member_id()
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_id text;
begin
  loop
    v_id := (100000 + floor(random() * 900000))::int::text;
    exit when not exists (select 1 from public.customer_accounts where member_id = v_id);
  end loop;
  return v_id;
end;
$$;
revoke all on function private.new_member_id() from public, anon, authenticated;

alter table public.customer_accounts drop constraint if exists customer_accounts_member_id_format;
alter table public.customer_accounts disable trigger customer_accounts_member_id;
do $$
declare r record;
begin
  -- the letter IDs given yesterday become numbers (nobody relies on them yet)
  for r in select id from public.customer_accounts where member_id !~ '^[1-9][0-9]{5}$' loop
    update public.customer_accounts set member_id = 'tmp-' || r.id where id = r.id;
  end loop;
  for r in select id from public.customer_accounts where member_id like 'tmp-%' loop
    update public.customer_accounts set member_id = private.new_member_id() where id = r.id;
  end loop;
end;
$$;
alter table public.customer_accounts enable trigger customer_accounts_member_id;
alter table public.customer_accounts add constraint customer_accounts_member_id_format check (member_id ~ '^[1-9][0-9]{5}$');

-- The User ID of an account (null if unknown).
create or replace function private.member_of(p_user uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select member_id from public.customer_accounts where id = p_user
$$;
revoke all on function private.member_of(uuid) from public, anon, authenticated;

-- ============================================================ 2. Support tickets 
create sequence if not exists public.support_ticket_number_seq start 1001;
revoke all on sequence public.support_ticket_number_seq from anon, authenticated;

create table if not exists public.support_tickets (
  id              uuid primary key default gen_random_uuid(),
  ticket_number   text not null unique default ('T-' || nextval('public.support_ticket_number_seq')),
  user_id         uuid not null references auth.users(id) on delete cascade,
  category        text not null check (category in ('order', 'payment', 'delivery', 'printing', 'wallet', 'account', 'product', 'app', 'other')),
  order_id        uuid references public.orders(id) on delete set null,
  order_number    text check (order_number is null or order_number ~ '^ET-[0-9]{5,9}$'),
  subject         text not null check (char_length(subject) between 3 and 120),
  details         text not null check (char_length(details) between 10 and 3000),
  status          text not null default 'open' check (status in ('open', 'in_progress', 'waiting_customer', 'resolved', 'closed')),
  assigned_to     uuid references public.profiles(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  last_message_at timestamptz not null default now(),
  resolved_at     timestamptz,
  closed_at       timestamptz
);
create index if not exists support_tickets_user_idx on public.support_tickets(user_id, created_at desc);
create index if not exists support_tickets_status_idx on public.support_tickets(status, created_at desc);
drop trigger if exists support_tickets_updated_at on public.support_tickets;
create trigger support_tickets_updated_at before update on public.support_tickets
  for each row execute function private.set_updated_at();

create table if not exists public.support_ticket_messages (
  id          bigint generated always as identity primary key,
  ticket_id   uuid not null references public.support_tickets(id) on delete cascade,
  author_id   uuid references auth.users(id) on delete set null,
  from_staff  boolean not null default false,
  internal    boolean not null default false check (not internal or from_staff),
  body        text not null check (char_length(body) between 1 and 3000),
  created_at  timestamptz not null default now()
);
create index if not exists support_ticket_messages_ticket_idx on public.support_ticket_messages(ticket_id, id);

alter table public.support_tickets enable row level security;
alter table public.support_ticket_messages enable row level security;
revoke all on public.support_tickets, public.support_ticket_messages from anon, authenticated;
grant select on public.support_tickets, public.support_ticket_messages to authenticated;

insert into public.admin_permissions (key, description) values
  ('support.view', 'See support tickets'),
  ('support.manage', 'Answer support tickets and change their status')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, p.key from public.admin_roles r cross join (values ('support.view'), ('support.manage')) p(key)
 where r.key in ('super_admin', 'manager')
on conflict do nothing;

drop policy if exists support_tickets_own_read on public.support_tickets;
create policy support_tickets_own_read on public.support_tickets for select to authenticated
  using (user_id = (select auth.uid()) and (select private.is_active_customer()));
drop policy if exists support_tickets_staff_read on public.support_tickets;
create policy support_tickets_staff_read on public.support_tickets for select to authenticated
  using ((select private.has_permission('support.view')));
drop policy if exists support_messages_own_read on public.support_ticket_messages;
create policy support_messages_own_read on public.support_ticket_messages for select to authenticated
  using (not internal and (select private.is_active_customer())
         and exists (select 1 from public.support_tickets t where t.id = ticket_id and t.user_id = (select auth.uid())));
drop policy if exists support_messages_staff_read on public.support_ticket_messages;
create policy support_messages_staff_read on public.support_ticket_messages for select to authenticated
  using ((select private.has_permission('support.view')));

-- Customer opens a ticket. Order-related topics need one of the customer's own order numbers.
create or replace function public.customer_create_ticket(p_category text, p_order_number text, p_subject text, p_details text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_number text := nullif(upper(regexp_replace(coalesce(p_order_number, ''), '\s', '', 'g')), '');
  v_order public.orders;
  v_subject text := nullif(left(btrim(coalesce(p_subject, '')), 120), '');
  v_details text := btrim(coalesce(p_details, ''));
  v_ticket public.support_tickets;
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  if p_category not in ('order', 'payment', 'delivery', 'printing', 'wallet', 'account', 'product', 'app', 'other') then
    perform private.app_error('invalid_request', 'category');
  end if;
  if char_length(v_details) < 10 or char_length(v_details) > 3000 then perform private.app_error('invalid_request', 'details'); end if;
  if p_category = 'other' and (v_subject is null or char_length(v_subject) < 3) then perform private.app_error('invalid_request', 'subject'); end if;
  if (select count(*) from public.support_tickets where user_id = v_uid and created_at > now() - interval '1 day') >= 10
     or (select count(*) from public.support_tickets where user_id = v_uid and status in ('open', 'in_progress', 'waiting_customer')) >= 5 then
    perform private.app_error('rate_limited');
  end if;
  if v_number is not null then
    v_number := regexp_replace(v_number, '^ET-?', 'ET-');
    select * into v_order from public.orders where order_number = v_number and user_id = v_uid;
    if not found then perform private.app_error('order_not_found'); end if;
  elsif p_category in ('order', 'payment', 'delivery') then
    perform private.app_error('order_not_found');
  end if;
  insert into public.support_tickets (user_id, category, order_id, order_number, subject, details)
  values (v_uid, p_category, v_order.id, v_order.order_number,
          coalesce(v_subject, case p_category
            when 'order' then 'Order problem' when 'payment' then 'Payment problem' when 'delivery' then 'Delivery or pickup'
            when 'printing' then 'Printing service' when 'wallet' then 'My balance' when 'account' then 'My account'
            when 'product' then 'Product question' when 'app' then 'Website or app problem' end),
          v_details)
  returning * into v_ticket;
  perform private.audit('ticket_created', 'support_ticket', v_ticket.id::text, null,
    jsonb_build_object('category', p_category, 'subject', v_ticket.subject), jsonb_build_object('ticket_number', v_ticket.ticket_number));
  perform private.enqueue_notification('support_ticket', 'support_ticket:' || v_ticket.id,
    jsonb_build_object('ticket_id', v_ticket.id, 'number', v_ticket.ticket_number, 'category', p_category, 'subject', v_ticket.subject,
      'details', left(v_details, 1500), 'order_number', v_ticket.order_number, 'user_id', private.member_of(v_uid),
      'customer', (select full_name from public.customer_accounts where id = v_uid),
      'email', (select email::text from auth.users where id = v_uid)));
  return jsonb_build_object('ticket_id', v_ticket.id, 'ticket_number', v_ticket.ticket_number);
end;
$$;
revoke all on function public.customer_create_ticket(text, text, text, text) from public, anon;
grant execute on function public.customer_create_ticket(text, text, text, text) to authenticated;

-- Customer adds a message to their own ticket (re-opens a resolved one; closed tickets are final).
create or replace function public.customer_reply_ticket(p_ticket_id uuid, p_body text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_t public.support_tickets;
  v_body text := btrim(coalesce(p_body, ''));
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  select * into v_t from public.support_tickets where id = p_ticket_id and user_id = (select auth.uid()) for update;
  if not found then perform private.app_error('not_found'); end if;
  if v_t.status = 'closed' then perform private.app_error('invalid_transition', 'closed'); end if;
  if char_length(v_body) < 1 or char_length(v_body) > 3000 then perform private.app_error('invalid_request', 'message'); end if;
  if (select count(*) from public.support_ticket_messages where ticket_id = v_t.id and not from_staff and created_at > now() - interval '1 hour') >= 20 then
    perform private.app_error('rate_limited');
  end if;
  insert into public.support_ticket_messages (ticket_id, author_id, from_staff, body) values (v_t.id, (select auth.uid()), false, v_body);
  update public.support_tickets
     set last_message_at = now(),
         status = case when status in ('waiting_customer', 'resolved') then 'open' else status end,
         resolved_at = case when status = 'resolved' then null else resolved_at end
   where id = v_t.id;
  perform private.enqueue_notification('support_reply', 'support_reply:' || v_t.id || ':' || (select max(id) from public.support_ticket_messages where ticket_id = v_t.id),
    jsonb_build_object('ticket_id', v_t.id, 'number', v_t.ticket_number, 'subject', v_t.subject, 'message', left(v_body, 1500),
      'user_id', private.member_of(v_t.user_id), 'customer', (select full_name from public.customer_accounts where id = v_t.user_id)));
end;
$$;
revoke all on function public.customer_reply_ticket(uuid, text) from public, anon;
grant execute on function public.customer_reply_ticket(uuid, text) to authenticated;

-- Staff: status, assignee, and a message (to the customer, or an internal note).
create or replace function public.admin_update_ticket(
  p_ticket_id uuid, p_status text default null, p_assigned_to uuid default null, p_unassign boolean default false,
  p_message text default null, p_internal boolean default false)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_t public.support_tickets;
  v_msg text := nullif(btrim(coalesce(p_message, '')), '');
  v_status text;
begin
  perform private.require_permission('support.manage');
  select * into v_t from public.support_tickets where id = p_ticket_id for update;
  if not found then perform private.app_error('not_found'); end if;
  if p_status is not null and p_status not in ('open', 'in_progress', 'waiting_customer', 'resolved', 'closed') then
    perform private.app_error('invalid_request', 'status');
  end if;
  if p_assigned_to is not null and not exists (select 1 from public.profiles where id = p_assigned_to and is_active and removed_at is null) then
    perform private.app_error('invalid_assignee');
  end if;
  if v_msg is not null and char_length(v_msg) > 3000 then perform private.app_error('invalid_request', 'message'); end if;
  -- A reply to the customer waits for them unless another status is chosen.
  v_status := coalesce(p_status, case when v_msg is not null and not p_internal and v_t.status in ('open', 'in_progress') then 'waiting_customer' else v_t.status end);
  if v_msg is not null then
    insert into public.support_ticket_messages (ticket_id, author_id, from_staff, internal, body)
    values (v_t.id, (select auth.uid()), true, coalesce(p_internal, false), v_msg);
  end if;
  update public.support_tickets
     set status = v_status,
         assigned_to = case when p_unassign then null else coalesce(p_assigned_to, assigned_to) end,
         last_message_at = case when v_msg is not null then now() else last_message_at end,
         resolved_at = case when v_status = 'resolved' and v_t.status <> 'resolved' then now() when v_status in ('open', 'in_progress', 'waiting_customer') then null else resolved_at end,
         closed_at = case when v_status = 'closed' and v_t.status <> 'closed' then now() when v_status <> 'closed' then null else closed_at end
   where id = v_t.id;
  perform private.audit('ticket_updated', 'support_ticket', v_t.id::text,
    jsonb_build_object('status', v_t.status, 'assigned_to', private.actor_name(v_t.assigned_to)),
    jsonb_build_object('status', v_status, 'assigned_to', private.actor_name(case when p_unassign then null else coalesce(p_assigned_to, v_t.assigned_to) end),
                       'replied', v_msg is not null and not p_internal, 'note', v_msg is not null and p_internal),
    jsonb_build_object('ticket_number', v_t.ticket_number));
  -- The customer hears about replies and status changes (email + phone notification).
  if (v_msg is not null and not p_internal) or v_status is distinct from v_t.status then
    perform private.enqueue_customer_email('customer_ticket_update', 'ticket:' || v_t.id || ':' || extract(epoch from clock_timestamp())::text, v_t.user_id,
      jsonb_build_object('ticket_id', v_t.id, 'number', v_t.ticket_number, 'subject', v_t.subject, 'status', v_status,
        'message', case when p_internal then null else left(v_msg, 1500) end));
  end if;
end;
$$;
revoke all on function public.admin_update_ticket(uuid, text, uuid, boolean, text, boolean) from public, anon;
grant execute on function public.admin_update_ticket(uuid, text, uuid, boolean, text, boolean) to authenticated;

create or replace function public.admin_support_tickets(
  p_status text default null, p_search text default null, p_from timestamptz default null, p_to timestamptz default null, p_limit integer default 300)
returns table (
  id uuid, ticket_number text, user_id uuid, member_id text, customer_name text, email text, category text, order_id uuid, order_number text,
  subject text, status text, assigned_name text, created_at timestamptz, last_message_at timestamptz, messages bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('support.view');
  return query
    select t.id, t.ticket_number, t.user_id, c.member_id, c.full_name, u.email::text, t.category, t.order_id, t.order_number,
           t.subject, t.status, private.actor_name(t.assigned_to), t.created_at, t.last_message_at,
           (select count(*) from public.support_ticket_messages m where m.ticket_id = t.id)
      from public.support_tickets t
      join auth.users u on u.id = t.user_id
      left join public.customer_accounts c on c.id = t.user_id
     where (p_status is null or t.status = p_status)
       and (p_from is null or t.created_at >= p_from) and (p_to is null or t.created_at < p_to)
       and (v_q is null or t.ticket_number ilike '%' || v_q || '%' or t.subject ilike '%' || v_q || '%' or t.details ilike '%' || v_q || '%'
            or c.member_id = v_q or c.full_name ilike '%' || v_q || '%' or u.email ilike '%' || v_q || '%' or t.order_number ilike '%' || v_q || '%')
     order by case t.status when 'open' then 0 when 'in_progress' then 1 when 'waiting_customer' then 2 else 3 end, t.last_message_at desc
     limit greatest(1, least(coalesce(p_limit, 300), 1000));
end;
$$;
revoke all on function public.admin_support_tickets(text, text, timestamptz, timestamptz, integer) from public, anon;
grant execute on function public.admin_support_tickets(text, text, timestamptz, timestamptz, integer) to authenticated;

-- The person an activity entry is about (customer of an order, payment, printing job, top-up, ticket; the account itself).
create or replace function private.subject_user(p_entity_type text, p_entity_id text)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_entity_id !~ '^[0-9a-fA-F-]{36}$' then null
    when p_entity_type in ('customer_account', 'profiles') then p_entity_id::uuid
    when p_entity_type = 'order' then (select o.user_id from public.orders o where o.id = p_entity_id::uuid)
    when p_entity_type = 'payment_submission' then
      (select o.user_id from public.payment_submissions s join public.orders o on o.id = s.order_id where s.id = p_entity_id::uuid)
    when p_entity_type = 'printing_job' then
      (select o.user_id from public.printing_jobs j join public.orders o on o.id = j.order_id where j.id = p_entity_id::uuid)
    when p_entity_type = 'wallet_topup' then (select t.user_id from public.wallet_topups t where t.id = p_entity_id::uuid)
    when p_entity_type = 'support_ticket' then (select t.user_id from public.support_tickets t where t.id = p_entity_id::uuid)
    else null
  end
$$;
revoke all on function private.subject_user(text, text) from public, anon, authenticated;

-- ============================================================ 3. Activity log with User IDs
drop function if exists public.admin_activity_by_category(text, text, integer, bigint, timestamptz, timestamptz);
create function public.admin_activity_by_category(
  p_category text default null, p_search text default null, p_limit integer default 100, p_before_id bigint default null,
  p_from timestamptz default null, p_to timestamptz default null)
returns table (
  id bigint, created_at timestamptz, actor_id uuid, actor_name text, actor_role text,
  action text, entity_type text, entity_id text, entity_label text,
  before_data jsonb, after_data jsonb, metadata jsonb, category text,
  actor_member_id text, subject_member_id text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
  v_uid uuid;
begin
  perform private.require_permission('audit.view');
  if p_category is not null and p_category not in ('orders', 'payments', 'customers', 'catalog', 'staff', 'security', 'other') then
    perform private.app_error('invalid_request', 'category');
  end if;
  -- A 6-digit search is a User ID: everything that person did, and everything about them.
  if v_q ~ '^[0-9]{6}$' then select c.id into v_uid from public.customer_accounts c where c.member_id = v_q; end if;
  return query
    select a.id, a.created_at, a.actor_id, private.actor_name(a.actor_id), a.actor_role,
           a.action, a.entity_type, a.entity_id,
           case a.entity_type
             when 'order' then (select o.order_number from public.orders o where o.id::text = a.entity_id)
             when 'printing_job' then (select j.job_number from public.printing_jobs j where j.id::text = a.entity_id)
             when 'payment_submission' then (select o.order_number from public.payment_submissions s join public.orders o on o.id = s.order_id where s.id::text = a.entity_id)
             when 'customer_account' then coalesce(
               (select u.email::text from auth.users u where u.id::text = a.entity_id), a.before_data ->> 'email')
             when 'profiles' then private.actor_name(case when a.entity_id ~ '^[0-9a-f-]{36}$' then a.entity_id::uuid end)
             when 'products' then coalesce(a.after_data ->> 'name_en', a.before_data ->> 'name_en')
             when 'support_ticket' then (select t.ticket_number from public.support_tickets t where t.id::text = a.entity_id)
             else null
           end,
           a.before_data, a.after_data, a.metadata, private.activity_category(a.action, a.entity_type),
           private.member_of(a.actor_id), private.member_of(private.subject_user(a.entity_type, a.entity_id))
      from public.audit_logs a
     where (p_category is null or private.activity_category(a.action, a.entity_type) = p_category)
       and (p_before_id is null or a.id < p_before_id)
       and (p_from is null or a.created_at >= p_from) and (p_to is null or a.created_at < p_to)
       and (v_q is null
            or (v_uid is not null and (a.actor_id = v_uid or private.subject_user(a.entity_type, a.entity_id) = v_uid))
            or a.action ilike '%' || v_q || '%' or a.entity_id ilike '%' || v_q || '%'
            or private.actor_name(a.actor_id) ilike '%' || v_q || '%')
     order by a.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;
revoke all on function public.admin_activity_by_category(text, text, integer, bigint, timestamptz, timestamptz) from public, anon;
grant execute on function public.admin_activity_by_category(text, text, integer, bigint, timestamptz, timestamptz) to authenticated;

drop function if exists public.admin_activity_export(timestamptz, timestamptz, text);
create function public.admin_activity_export(p_from timestamptz, p_to timestamptz, p_entity_type text default null)
returns table (
  id bigint, created_at timestamptz, actor_name text, actor_role text, action text, entity_type text, entity_id text,
  entity_label text, before_data jsonb, after_data jsonb, metadata jsonb, actor_member_id text, subject_member_id text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('audit.view');
  if p_from is null or p_to is null or p_to <= p_from then perform private.app_error('invalid_request'); end if;
  return query
    select a.id, a.created_at, private.actor_name(a.actor_id), a.actor_role, a.action, a.entity_type, a.entity_id,
           case a.entity_type
             when 'order' then (select o.order_number from public.orders o where o.id::text = a.entity_id)
             when 'printing_job' then (select j.job_number from public.printing_jobs j where j.id::text = a.entity_id)
             when 'customer_account' then coalesce((select u.email::text from auth.users u where u.id::text = a.entity_id), a.before_data ->> 'email')
             when 'products' then coalesce(a.after_data ->> 'name_en', a.before_data ->> 'name_en')
             when 'support_ticket' then (select t.ticket_number from public.support_tickets t where t.id::text = a.entity_id)
             else null
           end,
           a.before_data, a.after_data, a.metadata,
           private.member_of(a.actor_id), private.member_of(private.subject_user(a.entity_type, a.entity_id))
      from public.audit_logs a
     where a.created_at >= p_from and a.created_at < p_to
       and (p_entity_type is null or a.entity_type = p_entity_type)
     order by a.id
     limit 50000;
end;
$$;
revoke all on function public.admin_activity_export(timestamptz, timestamptz, text) from public, anon;
grant execute on function public.admin_activity_export(timestamptz, timestamptz, text) to authenticated;

create or replace function private.activity_category(p_action text, p_entity_type text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_entity_type in ('security', 'audit', 'data', 'export') or p_action like 'export\_%' or p_action = 'user_signed_out' then 'security'
    when p_entity_type = 'payment_submission' or p_action like 'topup\_%' or p_action like 'payment\_%' or p_action = 'wallet_adjusted' then 'payments'
    when p_entity_type in ('order', 'printing_job') then 'orders'
    when p_entity_type in ('customer_account', 'support_ticket') then 'customers'
    when p_entity_type in ('products', 'categories', 'promotions', 'delivery_zones', 'printing_price_rules', 'homepage_banners',
                           'product_review', 'product_images') then 'catalog'
    when p_entity_type in ('profiles', 'role_permissions', 'website_settings', 'bank_accounts', 'notification') then 'staff'
    else 'other'
  end
$$;

-- ============================================================ 4. Signed-in users
create or replace function public.admin_signed_in_users(p_search text default null)
returns table (
  session_id uuid, user_id uuid, member_id text, full_name text, email text, is_staff boolean, role_name text,
  signed_in_at timestamptz, last_active_at timestamptz, ip text, user_agent text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('security.manage');
  return query
    select s.id, s.user_id, c.member_id, coalesce(p.full_name, c.full_name), u.email::text, p.id is not null, r.name,
           s.created_at,
           greatest(s.created_at, s.updated_at, s.refreshed_at at time zone 'UTC'),
           host(s.ip), left(s.user_agent, 300)
      from auth.sessions s
      join auth.users u on u.id = s.user_id
      left join public.customer_accounts c on c.id = s.user_id
      left join public.profiles p on p.id = s.user_id and p.removed_at is null
      left join public.admin_roles r on r.id = p.role_id
     where (s.not_after is null or s.not_after > now())
       and (v_q is null or c.member_id = v_q or u.email ilike '%' || v_q || '%' or coalesce(p.full_name, c.full_name) ilike '%' || v_q || '%')
     order by 9 desc
     limit 1000;
end;
$$;
revoke all on function public.admin_signed_in_users(text) from public, anon;
grant execute on function public.admin_signed_in_users(text) to authenticated;

-- Last sign-in of every account: in a date range, or before a date (not seen since).
create or replace function public.admin_last_sign_ins(
  p_from timestamptz default null, p_to timestamptz default null, p_before timestamptz default null, p_search text default null)
returns table (
  user_id uuid, member_id text, full_name text, email text, is_staff boolean, role_name text,
  last_sign_in_at timestamptz, created_at timestamptz, signed_in_now boolean
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('security.manage');
  return query
    select u.id, c.member_id, coalesce(p.full_name, c.full_name), u.email::text, p.id is not null, r.name,
           u.last_sign_in_at, u.created_at,
           exists (select 1 from auth.sessions s where s.user_id = u.id and (s.not_after is null or s.not_after > now()))
      from auth.users u
      left join public.customer_accounts c on c.id = u.id
      left join public.profiles p on p.id = u.id and p.removed_at is null
      left join public.admin_roles r on r.id = p.role_id
     where (p_from is null or u.last_sign_in_at >= p_from) and (p_to is null or u.last_sign_in_at < p_to)
       and (p_before is null or u.last_sign_in_at is null or u.last_sign_in_at < p_before)
       and (v_q is null or c.member_id = v_q or u.email ilike '%' || v_q || '%' or coalesce(p.full_name, c.full_name) ilike '%' || v_q || '%')
     order by u.last_sign_in_at desc nulls last
     limit 2000;
end;
$$;
revoke all on function public.admin_last_sign_ins(timestamptz, timestamptz, timestamptz, text) from public, anon;
grant execute on function public.admin_last_sign_ins(timestamptz, timestamptz, timestamptz, text) to authenticated;

-- Sign a user out everywhere (their tokens stop working at once: private.session_alive).
create or replace function public.admin_sign_out_user(p_user_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  perform private.require_permission('security.manage');
  if p_user_id = (select auth.uid()) then perform private.app_error('cannot_modify_self'); end if;
  if not exists (select 1 from auth.users where id = p_user_id) then perform private.app_error('user_not_found'); end if;
  delete from auth.sessions where user_id = p_user_id;
  get diagnostics n = row_count;
  perform private.audit('user_signed_out', case when exists (select 1 from public.profiles where id = p_user_id) then 'profiles' else 'customer_account' end,
    p_user_id::text, null, jsonb_build_object('sessions_ended', n), jsonb_build_object('user_id', private.member_of(p_user_id)));
  return n;
end;
$$;
revoke all on function public.admin_sign_out_user(uuid) from public, anon;
grant execute on function public.admin_sign_out_user(uuid) to authenticated;

-- ============================================================ 5. App installs
create table if not exists public.app_installs (
  device_id    uuid primary key,
  user_id      uuid references auth.users(id) on delete set null,
  platform     text not null check (platform in ('android', 'ios', 'windows', 'mac', 'linux', 'other')),
  first_seen   timestamptz not null default now(),
  last_seen    timestamptz not null default now(),
  opens        integer not null default 1
);
create index if not exists app_installs_user_idx on public.app_installs(user_id);
alter table public.app_installs enable row level security;
revoke all on public.app_installs from anon, authenticated;
-- No policies: written by the server (after validation + rate limiting), read through admin_app_installs().

create or replace function public.record_app_install(p_device_id uuid, p_platform text, p_user_id uuid default null)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.app_installs (device_id, user_id, platform)
  values (p_device_id, p_user_id, case when p_platform in ('android', 'ios', 'windows', 'mac', 'linux') then p_platform else 'other' end)
  on conflict (device_id) do update
     set last_seen = now(), opens = public.app_installs.opens + 1,
         user_id = coalesce(excluded.user_id, public.app_installs.user_id),
         platform = excluded.platform
$$;
revoke all on function public.record_app_install(uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.record_app_install(uuid, text, uuid) to service_role;

create or replace function public.admin_app_installs()
returns table (device_id uuid, user_id uuid, member_id text, full_name text, email text, is_staff boolean, platform text,
               first_seen timestamptz, last_seen timestamptz, opens integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('customers.view');
  return query
    select i.device_id, i.user_id, c.member_id, coalesce(p.full_name, c.full_name), u.email::text, p.id is not null, i.platform,
           i.first_seen, i.last_seen, i.opens
      from public.app_installs i
      left join auth.users u on u.id = i.user_id
      left join public.customer_accounts c on c.id = i.user_id
      left join public.profiles p on p.id = i.user_id
     order by i.last_seen desc
     limit 5000;
end;
$$;
revoke all on function public.admin_app_installs() from public, anon;
grant execute on function public.admin_app_installs() to authenticated;

-- ============================================================ 6. Printing: alerts after payment; rejected → files deleted
-- No staff alert when a printing request is created (only once its payment is submitted).
create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_rejected', 'notification_copy', 'printing_request') then
    return null;
  end if;
  return new;
end;
$$;

-- Documents go to the printing group as soon as the payment is submitted (or paid from the balance).
create or replace function private.printing_documents_on_paid()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total integer;
  v_i integer := 0;
  f record;
begin
  if new.status not in ('payment_verification', 'printing')
     or old.status in ('payment_verification', 'printing', 'ready', 'completed') then return null; end if;
  select count(*) into v_total from public.printing_files where job_id = new.id and deleted_at is null;
  for f in select * from public.printing_files where job_id = new.id and deleted_at is null order by created_at, id loop
    v_i := v_i + 1;
    perform private.enqueue_notification('printing_document', 'printing_document:' || f.id,
      jsonb_build_object('job_id', new.id, 'job_number', new.job_number, 'file_name', f.original_name, 'mime', f.mime_type,
        'size_bytes', f.size_bytes, 'pages', f.page_count, 'n', v_i, 'of', v_total,
        'stage', case when new.status = 'printing' then 'paid' else 'payment_submitted' end,
        'customer', new.customer_name, 'phone', new.customer_phone, 'color_mode', new.color_mode, 'paper_size', new.paper_size,
        'sides', new.sides, 'copies', new.copies, 'page_count', new.page_count, 'total_etb', new.total_etb,
        'fulfillment', new.fulfillment_method, 'notes', left(new.customer_notes, 300)),
      'printing-files', f.storage_path);
  end loop;
  return null;
end;
$$;

-- A cancelled job's documents are deleted right away (by the storage clean-up).
create or replace function private.printing_files_due_on_cancel()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.status = 'cancelled' and old.status <> 'cancelled' then new.files_delete_after := now(); end if;
  return new;
end;
$$;
drop trigger if exists printing_jobs_files_due_on_cancel on public.printing_jobs;
create trigger printing_jobs_files_due_on_cancel before update of status on public.printing_jobs
  for each row execute function private.printing_files_due_on_cancel();

-- Payment rejected on an order with printing: the printing job (and the order) are cancelled;
-- the customer uploads the documents again with a new request.
create or replace function private.cancel_printing_on_rejection()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status <> 'payment_rejected' or old.status = 'payment_rejected' then return null; end if;
  if not exists (select 1 from public.printing_jobs where order_id = new.id and status not in ('completed', 'cancelled')) then return null; end if;
  perform private.set_status_note('Payment rejected: printing documents deleted — please send a new printing request');
  update public.printing_jobs set status = 'cancelled' where order_id = new.id and status not in ('completed', 'cancelled');
  perform private.release_order_stock(new.id);
  perform private.set_status_note('Payment rejected — order with printing cancelled (documents deleted)');
  update public.orders set status = 'cancelled', cancelled_at = now() where id = new.id;
  return null;
end;
$$;
drop trigger if exists orders_cancel_printing_on_rejection on public.orders;
create trigger orders_cancel_printing_on_rejection after update of status on public.orders
  for each row execute function private.cancel_printing_on_rejection();

-- Files are only deleted once their Telegram copy has gone out (or could not be sent within 2 days).
create or replace function public.printing_files_due_for_deletion(p_limit integer default 200)
returns table (file_id uuid, job_id uuid, storage_path text)
language sql
stable
security definer
set search_path = ''
as $$
  select f.id, f.job_id, f.storage_path
  from public.printing_files f
  join public.printing_jobs j on j.id = f.job_id
  where f.deleted_at is null
    and j.files_delete_after <= now()
    and j.status not in ('payment_verification', 'printing', 'ready')
    and not exists (select 1 from public.notifications_outbox o
                     where o.dedupe_key = 'printing_document:' || f.id and o.status in ('pending', 'processing')
                       and o.created_at > now() - interval '2 days')
  order by j.files_delete_after
  limit greatest(1, least(coalesce(p_limit, 200), 1000))
$$;

-- ============================================================ 7. Support Telegram group
create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test') then 'receipts'
    when p_event in ('printing_document', 'printing_test') then 'printing'
    when p_event in ('support_ticket', 'support_reply', 'support_test') then 'support'
    else 'orders'
  end
$$;

create or replace function public.admin_queue_group_test(p_group text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  if p_group not in ('stock', 'receipts', 'printing', 'support') then perform private.app_error('invalid_request'); end if;
  perform private.enqueue_notification(p_group || '_test', p_group || '_test:' || gen_random_uuid(),
    jsonb_build_object('requested_by', private.actor_name(auth.uid()), 'requested_at', now()));
end;
$$;

create or replace function public.purge_stale_telegram_feed()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  n integer;
begin
  delete from public.notifications_outbox
   where channel = 'telegram' and status in ('pending', 'failed', 'dead')
     and event_type in ('security_event', 'security_alert', 'admin_action', 'notification_copy', 'receipt_record', 'stock_test', 'receipts_test',
                        'printing_document', 'printing_test', 'support_test')
     and created_at < now() - interval '2 days';
  get diagnostics n = row_count;
  return n;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261122000053_reject_cancels_users_export.sql
-- 0053:
--   * A rejected payment cancels the order automatically (stock released, printing documents deleted).
--     The customer gets ONE message: "payment not verified — order cancelled" (with the reason).
--   * Exports of the signed-in users lists are recorded ('users').
--   * User ID → person lookup for the admin (admin_find_user).

-- ------------------------------------------------------------ payment rejected → order cancelled
drop trigger if exists orders_cancel_printing_on_rejection on public.orders;
drop function if exists private.cancel_printing_on_rejection();

create or replace function private.cancel_order_on_rejection()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status <> 'payment_rejected' or old.status = 'payment_rejected' then return null; end if;
  if exists (select 1 from public.printing_jobs where order_id = new.id and status not in ('completed', 'cancelled')) then
    perform private.set_status_note('Payment rejected: printing documents deleted');
    update public.printing_jobs set status = 'cancelled' where order_id = new.id and status not in ('completed', 'cancelled');
  end if;
  perform private.release_order_stock(new.id);
  perform private.set_status_note('Payment rejected — order cancelled automatically');
  update public.orders set status = 'cancelled', cancelled_at = now() where id = new.id;
  return null;
end;
$$;
revoke all on function private.cancel_order_on_rejection() from public, anon, authenticated;
create trigger orders_cancel_on_rejection after update of status on public.orders
  for each row execute function private.cancel_order_on_rejection();

-- One customer message for a rejection: the "payment rejected" one already says the order is cancelled.
create or replace function private.email_order_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
  v_note text;
begin
  if new.user_id is null then return new; end if;
  if tg_op = 'INSERT' then
    v_event := 'order_placed';
  elsif new.status is distinct from old.status then
    if new.status = 'cancelled' and old.status = 'payment_rejected' then return new; end if;
    v_event := case new.status
      when 'confirmed' then 'order_confirmed'
      when 'payment_rejected' then 'order_payment_rejected'
      when 'ready_for_pickup' then 'order_ready_for_pickup'
      when 'out_for_delivery' then 'order_out_for_delivery'
      when 'completed' then 'order_completed'
      when 'cancelled' then 'order_cancelled'
      when 'expired' then 'order_expired'
    end;
  end if;
  if v_event is null then return new; end if;
  if v_event = 'order_payment_rejected' then
    select s.review_note into v_note from public.payment_submissions s
     where s.order_id = new.id and s.status = 'rejected' order by s.reviewed_at desc limit 1;
  end if;
  perform private.enqueue_customer_email(
    'customer_' || v_event,
    'email:' || v_event || ':' || new.id || ':' || (select count(*) from public.order_status_history h where h.order_id = new.id),
    new.user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'order_id', new.id, 'order_number', new.order_number, 'total_etb', new.total_etb,
      'fulfillment', new.fulfillment_method, 'locale', new.locale, 'note', v_note,
      'payment_due_at', case when v_event = 'order_placed' then new.payment_due_at end,
      'bank', case when v_event = 'order_placed' then new.bank_snapshot end)));
  return new;
end;
$$;

-- Orders still waiting with a rejected payment (from before this change) are cancelled now.
do $$
declare r record;
begin
  for r in select id from public.orders where status = 'payment_rejected' loop
    perform private.set_status_note('Payment rejected — order cancelled automatically');
    if exists (select 1 from public.printing_jobs where order_id = r.id and status not in ('completed', 'cancelled')) then
      update public.printing_jobs set status = 'cancelled' where order_id = r.id and status not in ('completed', 'cancelled');
    end if;
    perform private.release_order_stock(r.id);
    update public.orders set status = 'cancelled', cancelled_at = now() where id = r.id;
  end loop;
end;
$$;

-- ------------------------------------------------------------ exports of the users lists are recorded
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  elsif p_kind = 'users' then perform private.require_permission('security.manage');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- ------------------------------------------------------------ User ID → person
create or replace function public.admin_find_user(p_member_id text)
returns table (user_id uuid, member_id text, is_staff boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not (private.has_permission('customers.view') or private.has_permission('staff.manage')
          or private.has_permission('security.manage') or private.has_permission('support.view')) then
    perform private.app_error('forbidden');
  end if;
  return query
    select c.id, c.member_id, exists (select 1 from public.profiles p where p.id = c.id)
      from public.customer_accounts c
     where c.member_id = btrim(coalesce(p_member_id, ''));
end;
$$;
revoke all on function public.admin_find_user(text) from public, anon;
grant execute on function public.admin_find_user(text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261122000054_tickets_rating_orders_30min_exports.sql
-- 0054:
--   * Support tickets: closed tickets disappear from the customer app 24 h after closing;
--     a ticket waiting for the customer's answer closes automatically after 48 h;
--     customers rate closed / resolved tickets 1–5 stars (optional comment).
--   * Unpaid orders are released after 30 minutes (setting "payment_window_minutes");
--     overdue orders are released before every new order, so the first to pay gets the item.
--   * Exports: customers, products, wallet, printing, support (recorded); closed tickets can be
--     cleared for a date range after they were exported.

-- ============================================================ Tickets: rating, 24 h visibility, 48 h auto-close
alter table public.support_tickets add column if not exists rating smallint check (rating between 1 and 5);
alter table public.support_tickets add column if not exists rating_comment text check (char_length(rating_comment) <= 500);
alter table public.support_tickets add column if not exists rated_at timestamptz;

drop policy if exists support_tickets_own_read on public.support_tickets;
create policy support_tickets_own_read on public.support_tickets for select to authenticated
  using (user_id = (select auth.uid()) and (select private.is_active_customer())
         and (status <> 'closed' or closed_at > now() - interval '24 hours'));
drop policy if exists support_messages_own_read on public.support_ticket_messages;
create policy support_messages_own_read on public.support_ticket_messages for select to authenticated
  using (not internal and (select private.is_active_customer())
         and exists (select 1 from public.support_tickets t where t.id = ticket_id and t.user_id = (select auth.uid())
                       and (t.status <> 'closed' or t.closed_at > now() - interval '24 hours')));

-- Customer replies only to tickets they can still see.
create or replace function public.customer_reply_ticket(p_ticket_id uuid, p_body text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_t public.support_tickets;
  v_body text := btrim(coalesce(p_body, ''));
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  select * into v_t from public.support_tickets where id = p_ticket_id and user_id = (select auth.uid()) for update;
  if not found or (v_t.status = 'closed' and v_t.closed_at <= now() - interval '24 hours') then perform private.app_error('not_found'); end if;
  if v_t.status = 'closed' then perform private.app_error('invalid_transition', 'closed'); end if;
  if char_length(v_body) < 1 or char_length(v_body) > 3000 then perform private.app_error('invalid_request', 'message'); end if;
  if (select count(*) from public.support_ticket_messages where ticket_id = v_t.id and not from_staff and created_at > now() - interval '1 hour') >= 20 then
    perform private.app_error('rate_limited');
  end if;
  insert into public.support_ticket_messages (ticket_id, author_id, from_staff, body) values (v_t.id, (select auth.uid()), false, v_body);
  update public.support_tickets
     set last_message_at = now(),
         status = case when status in ('waiting_customer', 'resolved') then 'open' else status end,
         resolved_at = case when status = 'resolved' then null else resolved_at end
   where id = v_t.id;
  perform private.enqueue_notification('support_reply', 'support_reply:' || v_t.id || ':' || (select max(id) from public.support_ticket_messages where ticket_id = v_t.id),
    jsonb_build_object('ticket_id', v_t.id, 'number', v_t.ticket_number, 'subject', v_t.subject, 'message', left(v_body, 1500),
      'user_id', private.member_of(v_t.user_id), 'customer', (select full_name from public.customer_accounts where id = v_t.user_id)));
end;
$$;

-- 1–5 stars once the ticket is resolved or closed.
create or replace function public.customer_rate_ticket(p_ticket_id uuid, p_rating integer, p_comment text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_t public.support_tickets;
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  if p_rating is null or p_rating not between 1 and 5 then perform private.app_error('invalid_request', 'rating'); end if;
  select * into v_t from public.support_tickets where id = p_ticket_id and user_id = (select auth.uid()) for update;
  if not found or (v_t.status = 'closed' and v_t.closed_at <= now() - interval '24 hours') then perform private.app_error('not_found'); end if;
  if v_t.status not in ('resolved', 'closed') then perform private.app_error('invalid_transition', v_t.status); end if;
  if v_t.rating is not null then perform private.app_error('already_reviewed'); end if;
  update public.support_tickets
     set rating = p_rating, rating_comment = nullif(left(btrim(coalesce(p_comment, '')), 500), ''), rated_at = now()
   where id = v_t.id;
  perform private.audit('ticket_rated', 'support_ticket', v_t.id::text, null, jsonb_build_object('rating', p_rating), jsonb_build_object('ticket_number', v_t.ticket_number));
end;
$$;
revoke all on function public.customer_rate_ticket(uuid, integer, text) from public, anon;
grant execute on function public.customer_rate_ticket(uuid, integer, text) to authenticated;

-- Waiting for the customer for 48 h without an answer → closed (run on page loads and daily).
create or replace function public.close_stale_tickets()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
  n integer := 0;
begin
  for r in select * from public.support_tickets
            where status = 'waiting_customer' and last_message_at < now() - interval '48 hours'
            order by last_message_at limit 200 for update skip locked loop
    insert into public.support_ticket_messages (ticket_id, author_id, from_staff, body)
    values (r.id, null, true, 'Closed automatically: no answer within 48 hours. Open a new report if you still need help.');
    update public.support_tickets set status = 'closed', closed_at = now(), last_message_at = now() where id = r.id;
    perform private.audit('ticket_auto_closed', 'support_ticket', r.id::text, jsonb_build_object('status', r.status), jsonb_build_object('status', 'closed'),
      jsonb_build_object('ticket_number', r.ticket_number, 'reason', 'no answer within 48 hours'));
    perform private.enqueue_customer_email('customer_ticket_update', 'ticket:' || r.id || ':autoclose', r.user_id,
      jsonb_build_object('ticket_id', r.id, 'number', r.ticket_number, 'subject', r.subject, 'status', 'closed',
        'message', 'Closed automatically: no answer within 48 hours.'));
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke all on function public.close_stale_tickets() from public, anon;
grant execute on function public.close_stale_tickets() to authenticated, service_role;

-- Staff list: also details, rating and closing time.
drop function if exists public.admin_support_tickets(text, text, timestamptz, timestamptz, integer);
create function public.admin_support_tickets(
  p_status text default null, p_search text default null, p_from timestamptz default null, p_to timestamptz default null, p_limit integer default 300)
returns table (
  id uuid, ticket_number text, user_id uuid, member_id text, customer_name text, email text, category text, order_id uuid, order_number text,
  subject text, status text, assigned_name text, created_at timestamptz, last_message_at timestamptz, messages bigint,
  details text, rating smallint, rating_comment text, resolved_at timestamptz, closed_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('support.view');
  return query
    select t.id, t.ticket_number, t.user_id, c.member_id, c.full_name, u.email::text, t.category, t.order_id, t.order_number,
           t.subject, t.status, private.actor_name(t.assigned_to), t.created_at, t.last_message_at,
           (select count(*) from public.support_ticket_messages m where m.ticket_id = t.id),
           t.details, t.rating, t.rating_comment, t.resolved_at, t.closed_at
      from public.support_tickets t
      join auth.users u on u.id = t.user_id
      left join public.customer_accounts c on c.id = t.user_id
     where (p_status is null or t.status = p_status)
       and (p_from is null or t.created_at >= p_from) and (p_to is null or t.created_at < p_to)
       and (v_q is null or t.ticket_number ilike '%' || v_q || '%' or t.subject ilike '%' || v_q || '%' or t.details ilike '%' || v_q || '%'
            or c.member_id = v_q or c.full_name ilike '%' || v_q || '%' or u.email ilike '%' || v_q || '%' or t.order_number ilike '%' || v_q || '%')
     order by case t.status when 'open' then 0 when 'in_progress' then 1 when 'waiting_customer' then 2 else 3 end, t.last_message_at desc
     limit greatest(1, least(coalesce(p_limit, 300), 5000));
end;
$$;
revoke all on function public.admin_support_tickets(text, text, timestamptz, timestamptz, integer) from public, anon;
grant execute on function public.admin_support_tickets(text, text, timestamptz, timestamptz, integer) to authenticated;

-- Closed / resolved tickets of a date range (opened in it) are deleted — only after they were exported.
create or replace function public.admin_clear_tickets(p_from date, p_to date)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  perform private.require_permission('support.manage');
  if p_from is null or p_to is null or p_to < p_from or p_to > (now() at time zone 'Europe/Warsaw')::date then perform private.app_error('invalid_request', 'dates'); end if;
  if not private.exported_recently('support', p_from, p_to) then perform private.app_error('invalid_request', 'export_first'); end if;
  with d as (
    delete from public.support_tickets
     where created_at >= (p_from::timestamp at time zone 'Europe/Warsaw') and created_at < ((p_to + 1)::timestamp at time zone 'Europe/Warsaw')
       and status in ('closed', 'resolved')
    returning 1)
  select count(*)::integer into v_count from d;
  perform private.audit('tickets_cleared', 'support_ticket', null, null, null, jsonb_build_object('from', p_from, 'to', p_to, 'deleted', v_count));
  return v_count;
end;
$$;
revoke all on function public.admin_clear_tickets(date, date) from public, anon;
grant execute on function public.admin_clear_tickets(date, date) to authenticated;

create or replace function private.activity_category(p_action text, p_entity_type text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_entity_type in ('security', 'audit', 'data', 'export') or p_action like 'export\_%' or p_action = 'user_signed_out' then 'security'
    when p_entity_type = 'payment_submission' or p_action like 'topup\_%' or p_action like 'payment\_%' or p_action = 'wallet_adjusted' then 'payments'
    when p_entity_type in ('order', 'printing_job') then 'orders'
    when p_entity_type in ('customer_account', 'support_ticket') then 'customers'
    when p_entity_type in ('products', 'categories', 'promotions', 'delivery_zones', 'printing_price_rules', 'homepage_banners',
                           'product_review', 'product_images') then 'catalog'
    when p_entity_type in ('profiles', 'role_permissions', 'website_settings', 'bank_accounts', 'notification') then 'staff'
    else 'other'
  end
$$;

-- ============================================================ Orders: 30-minute payment window, first to pay gets it
update public.website_settings
   set value = value || jsonb_build_object('payment_window_minutes', 30)
 where key = 'delivery' and not (value ? 'payment_window_minutes');

create or replace function private.order_payment_window()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_minutes integer;
begin
  if new.status <> 'awaiting_payment' then return new; end if;
  v_minutes := coalesce((private.setting('delivery') ->> 'payment_window_minutes')::integer, 30);
  new.payment_due_at := now() + make_interval(mins => greatest(5, least(v_minutes, 10080)));
  return new;
end;
$$;
drop trigger if exists orders_payment_window on public.orders;
create trigger orders_payment_window before insert on public.orders
  for each row execute function private.order_payment_window();

-- Release overdue unpaid orders before taking a new one, so their stock is free for this buyer.
create or replace function public.create_order_for_user(p_user_id uuid, p_input jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing public.orders;
  v_result jsonb;
begin
  perform private.assert_confirmed_user(p_user_id);
  -- An idempotent replay must come from the same account.
  select * into v_existing from public.orders where idempotency_key = (p_input ->> 'idempotency_key')::uuid;
  if found and v_existing.user_id is distinct from p_user_id then
    perform private.app_error('idempotency_conflict');
  end if;
  -- Retry of a checkout that was already paid with the balance: same order, fresh access tokens, no second charge.
  if found and v_existing.payment_method = 'wallet' then
    update public.orders
       set access_token_hash = p_input ->> 'access_token_hash', tracking_code_hash = p_input ->> 'tracking_code_hash'
     where id = v_existing.id;
    return jsonb_build_object('order_id', v_existing.id, 'order_number', v_existing.order_number,
                              'total_etb', v_existing.total_etb, 'replayed', true, 'paid_with_wallet', true);
  end if;
  -- Unpaid orders past their 30 minutes give their items back first: the first to pay gets the item.
  perform public.expire_unpaid_orders();
  perform private.set_status_note(null);
  perform set_config('app.ordering_user_id', p_user_id::text, true);
  v_result := public.create_order(p_input);
  -- Clear immediately so nothing later in the same transaction inherits this user.
  perform set_config('app.ordering_user_id', '', true);
  delete from public.customer_carts where user_id = p_user_id;
  -- Pay with the account balance: all or nothing (an insufficient balance cancels the whole checkout).
  if p_input ->> 'payment_method' = 'wallet' then
    perform private.pay_order_from_wallet((v_result ->> 'order_id')::uuid, p_user_id);
    v_result := v_result || jsonb_build_object('paid_with_wallet', true);
  end if;
  return v_result;
end;
$$;

-- ============================================================ Exports are recorded (and gate clearing)
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  elsif p_kind = 'users' then perform private.require_permission('security.manage');
  elsif p_kind = 'support' then perform private.require_permission('support.view');
  elsif p_kind = 'customers' then perform private.require_permission('customers.view');
  elsif p_kind = 'products' then perform private.require_permission('products.view');
  elsif p_kind = 'wallet' then perform private.require_permission('wallet.manage');
  elsif p_kind = 'printing' then perform private.require_permission('printing.view');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261122000055_rating_feedback.sql
-- 0055: a ticket rating (stars + the customer's feedback) is recorded in the activity log and
-- sent to the support Telegram group.

create or replace function public.customer_rate_ticket(p_ticket_id uuid, p_rating integer, p_comment text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_t public.support_tickets;
  v_comment text := nullif(left(btrim(coalesce(p_comment, '')), 500), '');
begin
  if not private.is_active_customer() then perform private.app_error('login_required'); end if;
  if p_rating is null or p_rating not between 1 and 5 then perform private.app_error('invalid_request', 'rating'); end if;
  select * into v_t from public.support_tickets where id = p_ticket_id and user_id = (select auth.uid()) for update;
  if not found or (v_t.status = 'closed' and v_t.closed_at <= now() - interval '24 hours') then perform private.app_error('not_found'); end if;
  if v_t.status not in ('resolved', 'closed') then perform private.app_error('invalid_transition', v_t.status); end if;
  if v_t.rating is not null then perform private.app_error('already_reviewed'); end if;
  update public.support_tickets set rating = p_rating, rating_comment = v_comment, rated_at = now() where id = v_t.id;
  perform private.audit('ticket_rated', 'support_ticket', v_t.id::text, null,
    jsonb_build_object('rating', p_rating, 'feedback', v_comment), jsonb_build_object('ticket_number', v_t.ticket_number));
  perform private.enqueue_notification('support_rating', 'support_rating:' || v_t.id,
    jsonb_build_object('ticket_id', v_t.id, 'number', v_t.ticket_number, 'subject', v_t.subject, 'rating', p_rating, 'feedback', v_comment,
      'user_id', private.member_of(v_t.user_id), 'assigned', private.actor_name(v_t.assigned_to)));
end;
$$;

create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test') then 'receipts'
    when p_event in ('printing_document', 'printing_test') then 'printing'
    when p_event in ('support_ticket', 'support_reply', 'support_rating', 'support_test') then 'support'
    else 'orders'
  end
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000056_paid_only_staff_kpis.sql
-- 0056:
--   * An order (and a printing order) exists for the customer and staff only once its payment is
--     accepted: no customer message for a checkout that was never paid (placed / expired / cancelled);
--     the dashboard counts accepted orders only.
--   * Staff performance (KPIs) per staff member for a date range, with targets set by the Super Admin.

-- ============================================================ customer messages only for real (paid) orders
create or replace function private.email_order_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event text;
  v_note text;
begin
  if new.user_id is null then return new; end if;
  -- A checkout that is still being paid, expired or was cancelled before payment is not an order yet:
  -- no message (the payment details are on the checkout page).
  if tg_op = 'INSERT' then return new; end if;
  if new.status is not distinct from old.status then return new; end if;
  if new.status = 'cancelled' and old.status = 'payment_rejected' then return new; end if;
  if new.status in ('expired', 'cancelled') and new.payment_status not in ('verified', 'refunded') then return new; end if;
  v_event := case new.status
    when 'confirmed' then 'order_confirmed'
    when 'payment_rejected' then 'order_payment_rejected'
    when 'ready_for_pickup' then 'order_ready_for_pickup'
    when 'out_for_delivery' then 'order_out_for_delivery'
    when 'completed' then 'order_completed'
    when 'cancelled' then 'order_cancelled'
  end;
  if v_event is null then return new; end if;
  if v_event = 'order_payment_rejected' then
    select s.review_note into v_note from public.payment_submissions s
     where s.order_id = new.id and s.status = 'rejected' order by s.reviewed_at desc limit 1;
  end if;
  perform private.enqueue_customer_email(
    'customer_' || v_event,
    'email:' || v_event || ':' || new.id || ':' || (select count(*) from public.order_status_history h where h.order_id = new.id),
    new.user_id,
    jsonb_strip_nulls(jsonb_build_object(
      'order_id', new.id, 'order_number', new.order_number, 'total_etb', new.total_etb,
      'fulfillment', new.fulfillment_method, 'locale', new.locale, 'note', v_note)));
  return new;
end;
$$;

-- Dashboard: accepted orders only.
create or replace function public.admin_dashboard_stats(p_days integer default 14)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := (select auth.uid());
  v_all       boolean := private.has_permission('orders.view_all');
  v_assigned  boolean := private.has_permission('orders.view_assigned');
  v_revenue   boolean := private.has_permission('analytics.view');
  v_days      integer := greatest(1, least(coalesce(p_days, 14), 90));
  v_today     date := (now() at time zone 'Europe/Warsaw')::date;
  v_result    jsonb;
begin
  perform private.require_permission('dashboard.view');

  with visible as (
    -- An order exists once its payment is accepted (verified or later refunded).
    select o.*, coalesce(o.payment_verified_at, o.created_at) as accepted_at from public.orders o
    where (v_all or (v_assigned and o.assigned_to = v_uid))
      and o.payment_status in ('verified', 'refunded')
  )
  select jsonb_build_object(
    'orders_total', (select count(*) from visible),
    'orders_today', (select count(*) from visible where (accepted_at at time zone 'Europe/Warsaw')::date = v_today),
    'awaiting_processing', (select count(*) from visible where status in ('confirmed', 'processing')),
    'awaiting_payment', 0,
    'pending_payments', case when private.has_permission('payments.view')
        then (select count(*) from public.payment_submissions where status = 'pending') end,
    'products_active', case when private.has_permission('products.view')
        then (select count(*) from public.products where status = 'active') end,
    'low_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory
              and stock_quantity > 0 and stock_quantity <= low_stock_threshold) end,
    'out_of_stock', case when private.has_permission('products.view') or private.has_permission('inventory.manage')
        then (select count(*) from public.products where status = 'active' and track_inventory and stock_quantity = 0) end,
    'printing_open', case when private.has_permission('printing.view')
        then (select count(*) from public.printing_jobs where status in ('awaiting_quote', 'printing', 'ready')) end,
    'revenue_verified_total', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified') end,
    'revenue_verified_period', case when v_revenue
        then (select coalesce(sum(total_etb), 0) from public.orders where payment_status = 'verified'
              and (payment_verified_at at time zone 'Europe/Warsaw')::date > v_today - v_days) end,
    'daily', (
      select jsonb_agg(jsonb_build_object(
               'day', d.day,
               'orders', (select count(*) from visible v where (v.accepted_at at time zone 'Europe/Warsaw')::date = d.day),
               'revenue', case when v_revenue then (
                   select coalesce(sum(o.total_etb), 0) from public.orders o
                    where o.payment_status = 'verified'
                      and (o.payment_verified_at at time zone 'Europe/Warsaw')::date = d.day) end)
             order by d.day)
      from (select generate_series(v_today - (v_days - 1), v_today, interval '1 day')::date as day) d
    )
  ) into v_result;
  return v_result;
end;
$$;

-- ============================================================ staff performance (KPIs) and targets
insert into public.admin_permissions (key, description) values
  ('kpi.view', 'See staff performance (KPIs)'),
  ('kpi.manage', 'Set the KPI targets')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, p.key from public.admin_roles r cross join (values ('kpi.view'), ('kpi.manage')) p(key)
 where r.key = 'super_admin' or (r.key = 'manager' and p.key = 'kpi.view')
on conflict do nothing;

create table if not exists public.kpi_targets (
  id          uuid primary key default gen_random_uuid(),
  metric      text not null check (metric in ('tickets_resolved', 'ticket_resolution_hours', 'ticket_first_reply_hours', 'orders_completed',
                                              'payments_approved', 'payment_review_minutes', 'topups_approved', 'printing_completed', 'instore_sales')),
  period      text not null check (period in ('day', 'week', 'month')),
  profile_id  uuid references public.profiles(id) on delete cascade,   -- null = every staff member
  target      numeric(12,2) not null check (target >= 0 and target <= 1000000),
  updated_by  uuid references auth.users(id) on delete set null,
  updated_at  timestamptz not null default now()
);
create unique index if not exists kpi_targets_unique on public.kpi_targets (metric, coalesce(profile_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table public.kpi_targets enable row level security;
revoke all on public.kpi_targets from anon, authenticated;
grant select on public.kpi_targets to authenticated;
drop policy if exists kpi_targets_read on public.kpi_targets;
create policy kpi_targets_read on public.kpi_targets for select to authenticated using ((select private.has_permission('kpi.view')));
drop trigger if exists kpi_targets_audit on public.kpi_targets;
create trigger kpi_targets_audit after insert or update or delete on public.kpi_targets
  for each row execute function private.audit_row_change();

create or replace function public.admin_save_kpi_target(p_metric text, p_period text, p_target numeric, p_profile_id uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('kpi.manage');
  if p_profile_id is not null and not exists (select 1 from public.profiles where id = p_profile_id and removed_at is null) then
    perform private.app_error('user_not_found');
  end if;
  if p_target is null or p_target < 0 or p_target > 1000000 then perform private.app_error('invalid_request', 'target'); end if;
  if p_period not in ('day', 'week', 'month') then perform private.app_error('invalid_request', 'period'); end if;
  insert into public.kpi_targets (metric, period, profile_id, target, updated_by)
  values (p_metric, p_period, p_profile_id, p_target, (select auth.uid()))
  on conflict (metric, coalesce(profile_id, '00000000-0000-0000-0000-000000000000'::uuid))
  do update set period = excluded.period, target = excluded.target, updated_by = excluded.updated_by, updated_at = now();
end;
$$;
revoke all on function public.admin_save_kpi_target(text, text, numeric, uuid) from public, anon;
grant execute on function public.admin_save_kpi_target(text, text, numeric, uuid) to authenticated;

create or replace function public.admin_delete_kpi_target(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('kpi.manage');
  delete from public.kpi_targets where id = p_id;
end;
$$;
revoke all on function public.admin_delete_kpi_target(uuid) from public, anon;
grant execute on function public.admin_delete_kpi_target(uuid) to authenticated;

-- One row per staff member for [p_from, p_to).
create or replace function public.admin_staff_kpis(p_from timestamptz, p_to timestamptz)
returns table (
  user_id uuid, member_id text, full_name text, role_name text, is_active boolean,
  tickets_resolved bigint, ticket_resolution_hours numeric, ticket_first_reply_hours numeric, ticket_replies bigint, ticket_rating numeric,
  orders_completed bigint, order_steps bigint,
  payments_approved bigint, payments_rejected bigint, payment_review_minutes numeric,
  topups_approved bigint, topups_rejected bigint,
  printing_completed bigint, instore_sales bigint, instore_sales_etb numeric
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('kpi.view');
  if p_from is null or p_to is null or p_to <= p_from then perform private.app_error('invalid_request', 'dates'); end if;
  return query
  with staff as (
    select p.id, p.full_name, p.is_active, r.name as role_name from public.profiles p
      left join public.admin_roles r on r.id = p.role_id
     where p.removed_at is null
  ),
  resolved as (   -- status changed to resolved / closed by this person
    select a.actor_id, a.entity_id, a.created_at from public.audit_logs a
     where a.action = 'ticket_updated' and a.created_at >= p_from and a.created_at < p_to
       and a.after_data ->> 'status' in ('resolved', 'closed') and coalesce(a.before_data ->> 'status', '') not in ('resolved', 'closed')
  ),
  first_reply as (
    select distinct on (m.ticket_id) m.ticket_id, m.author_id, m.created_at
      from public.support_ticket_messages m
     where m.from_staff and not m.internal and m.author_id is not null
     order by m.ticket_id, m.id
  )
  select s.id, private.member_of(s.id), s.full_name, s.role_name, s.is_active,
    (select count(*) from resolved x where x.actor_id = s.id),
    (select round(avg(extract(epoch from (x.created_at - t.created_at)) / 3600)::numeric, 1)
       from resolved x join public.support_tickets t on t.id::text = x.entity_id where x.actor_id = s.id),
    (select round(avg(extract(epoch from (f.created_at - t.created_at)) / 3600)::numeric, 1)
       from first_reply f join public.support_tickets t on t.id = f.ticket_id
      where f.author_id = s.id and f.created_at >= p_from and f.created_at < p_to),
    (select count(*) from public.support_ticket_messages m where m.author_id = s.id and m.from_staff and not m.internal and m.created_at >= p_from and m.created_at < p_to),
    (select round(avg(t.rating)::numeric, 1) from public.support_tickets t
      where t.assigned_to = s.id and t.rating is not null and t.rated_at >= p_from and t.rated_at < p_to),
    (select count(*) from public.order_status_history h where h.changed_by = s.id and h.to_status = 'completed' and h.created_at >= p_from and h.created_at < p_to),
    (select count(*) from public.order_status_history h where h.changed_by = s.id and h.from_status is not null
        and h.to_status in ('processing', 'ready_for_pickup', 'out_for_delivery', 'completed') and h.created_at >= p_from and h.created_at < p_to),
    (select count(*) from public.payment_submissions ps where ps.reviewed_by = s.id and ps.status = 'verified' and ps.reviewed_at >= p_from and ps.reviewed_at < p_to),
    (select count(*) from public.payment_submissions ps where ps.reviewed_by = s.id and ps.status = 'rejected' and ps.reviewed_at >= p_from and ps.reviewed_at < p_to),
    (select round(avg(extract(epoch from (ps.reviewed_at - ps.submitted_at)) / 60)::numeric, 0) from public.payment_submissions ps
      where ps.reviewed_by = s.id and ps.status in ('verified', 'rejected') and ps.reviewed_at >= p_from and ps.reviewed_at < p_to),
    (select count(*) from public.wallet_topups w where w.reviewed_by = s.id and w.status = 'verified' and w.reviewed_at >= p_from and w.reviewed_at < p_to),
    (select count(*) from public.wallet_topups w where w.reviewed_by = s.id and w.status = 'rejected' and w.reviewed_at >= p_from and w.reviewed_at < p_to),
    (select count(*) from public.printing_job_history h where h.changed_by = s.id and h.to_status = 'completed' and h.created_at >= p_from and h.created_at < p_to),
    (select count(*) from public.order_status_history h join public.orders o on o.id = h.order_id
      where h.changed_by = s.id and h.from_status is null and o.channel = 'in_store' and o.status <> 'cancelled' and h.created_at >= p_from and h.created_at < p_to),
    (select coalesce(sum(o.total_etb), 0) from public.order_status_history h join public.orders o on o.id = h.order_id
      where h.changed_by = s.id and h.from_status is null and o.channel = 'in_store' and o.status <> 'cancelled' and h.created_at >= p_from and h.created_at < p_to)
  from staff s
  order by s.full_name;
end;
$$;
revoke all on function public.admin_staff_kpis(timestamptz, timestamptz) from public, anon;
grant execute on function public.admin_staff_kpis(timestamptz, timestamptz) to authenticated;

-- KPI exports are recorded like the others.
create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  elsif p_kind = 'users' then perform private.require_permission('security.manage');
  elsif p_kind = 'support' then perform private.require_permission('support.view');
  elsif p_kind = 'customers' then perform private.require_permission('customers.view');
  elsif p_kind = 'products' then perform private.require_permission('products.view');
  elsif p_kind = 'wallet' then perform private.require_permission('wallet.manage');
  elsif p_kind = 'printing' then perform private.require_permission('printing.view');
  elsif p_kind = 'kpi' then perform private.require_permission('kpi.view');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000057_telegram_after_approval.sql
-- 0057: Telegram only after a payment is approved.
--   * Printing documents go to the printing group once the payment is approved (job → printing).
--   * "Payment / top-up waiting for approval" alerts (new_order, payment_resubmitted, wallet_topup) are a switch,
--     OFF by default: staff see what is waiting in the admin (red counts); approved payments are still sent.

create or replace function private.feed_on(p_part text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((private.setting('telegram_feed') ->> p_part)::boolean,
                  p_part not in ('order_progress', 'notifications', 'pending_payments'))
$$;

create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_rejected', 'notification_copy', 'printing_request') then
    return null;
  end if;
  if new.event_type in ('new_order', 'payment_resubmitted', 'wallet_topup') and not private.feed_on('pending_payments') then return null; end if;
  return new;
end;
$$;

-- Documents once the payment is approved (or paid from the balance): job moves to "printing".
create or replace function private.printing_documents_on_paid()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_total integer;
  v_i integer := 0;
  f record;
begin
  if new.status <> 'printing' or old.status in ('printing', 'ready', 'completed') then return null; end if;
  select count(*) into v_total from public.printing_files where job_id = new.id and deleted_at is null;
  for f in select * from public.printing_files where job_id = new.id and deleted_at is null order by created_at, id loop
    v_i := v_i + 1;
    perform private.enqueue_notification('printing_document', 'printing_document:' || f.id,
      jsonb_build_object('job_id', new.id, 'job_number', new.job_number, 'file_name', f.original_name, 'mime', f.mime_type,
        'size_bytes', f.size_bytes, 'pages', f.page_count, 'n', v_i, 'of', v_total, 'stage', 'paid',
        'customer', new.customer_name, 'phone', new.customer_phone, 'color_mode', new.color_mode, 'paper_size', new.paper_size,
        'sides', new.sides, 'copies', new.copies, 'page_count', new.page_count, 'total_etb', new.total_etb,
        'fulfillment', new.fulfillment_method, 'notes', left(new.customer_notes, 300)),
      'printing-files', f.storage_path);
  end loop;
  return null;
end;
$$;

-- Saving the feed switches keeps the other parts (merge instead of replace).
create or replace function public.admin_set_telegram_feed(p_security boolean, p_admin boolean, p_notifications boolean,
                                                          p_order_progress boolean default false, p_printing_requests boolean default true)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := jsonb_build_object('security', coalesce(p_security, true), 'admin', coalesce(p_admin, true),
                                'notifications', coalesce(p_notifications, false), 'order_progress', coalesce(p_order_progress, false),
                                'printing_requests', coalesce(p_printing_requests, true));
begin
  perform private.require_permission('settings.manage');
  insert into public.website_settings (key, value, is_public, updated_by) values ('telegram_feed', v, false, auth.uid())
  on conflict (key) do update set value = public.website_settings.value || excluded.value, is_public = false, updated_by = excluded.updated_by;
end;
$$;

create or replace function public.admin_set_pending_payment_alerts(p_on boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  insert into public.website_settings (key, value, is_public, updated_by)
  values ('telegram_feed', jsonb_build_object('pending_payments', coalesce(p_on, false)), false, auth.uid())
  on conflict (key) do update set value = public.website_settings.value || excluded.value, updated_by = excluded.updated_by;
end;
$$;
revoke all on function public.admin_set_pending_payment_alerts(boolean) from public, anon;
grant execute on function public.admin_set_pending_payment_alerts(boolean) to authenticated;

create or replace function public.admin_telegram_feed()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('settings.manage');
  return jsonb_build_object('security', private.feed_on('security'), 'admin', private.feed_on('admin'),
                            'notifications', private.feed_on('notifications'), 'order_progress', private.feed_on('order_progress'),
                            'printing_requests', private.feed_on('printing_requests'), 'pending_payments', private.feed_on('pending_payments'));
end;
$$;

-- Off from now on (the owner's choice; can be switched on under Notifications).
insert into public.website_settings (key, value, is_public)
values ('telegram_feed', jsonb_build_object('pending_payments', false), false)
on conflict (key) do update set value = public.website_settings.value || jsonb_build_object('pending_payments', false);

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000058_topup_approved_alert.sql
-- 0058: an approved wallet top-up is announced in the orders & payments Telegram group
-- ("✅ TOP-UP APPROVED"), like an approved order payment. (Since 0057 top-ups waiting for
-- approval are not alerted by default, so this is the top-up message staff see.)

create or replace function private.telegram_topup_approved()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status::text <> 'verified' or old.status::text = 'verified' then return null; end if;
  perform private.enqueue_notification('topup_verified', 'topup_verified:' || new.id,
    jsonb_build_object('topup_id', new.id, 'number', new.topup_number, 'amount_etb', new.amount_etb,
      'reference', new.transaction_reference, 'user_id', private.member_of(new.user_id),
      'balance_etb', (select wallet_balance_etb from public.customer_accounts where id = new.user_id),
      'decided_by', private.actor_name(new.reviewed_by), 'decided_at', new.reviewed_at));
  return null;
end;
$$;
revoke all on function private.telegram_topup_approved() from public, anon, authenticated;

drop trigger if exists wallet_topups_telegram_approved on public.wallet_topups;
create trigger wallet_topups_telegram_approved after update of status on public.wallet_topups
  for each row execute function private.telegram_topup_approved();

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000059_topup_alerts.sql
-- 0059: wallet top-ups in the orders & payments Telegram group at every step:
--   * "Top-up to verify" as soon as the customer attaches the receipt (always on; the
--     "waiting for approval" switch now covers order payments only),
--   * "Top-up approved" (0058) and "Top-up rejected" (with the reason).

create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_rejected', 'notification_copy', 'printing_request') then
    return null;
  end if;
  if new.event_type in ('new_order', 'payment_resubmitted') and not private.feed_on('pending_payments') then return null; end if;
  return new;
end;
$$;

create or replace function private.telegram_topup_approved()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status::text not in ('verified', 'rejected') or old.status::text = new.status::text then return null; end if;
  perform private.enqueue_notification(case when new.status::text = 'verified' then 'topup_verified' else 'topup_rejected' end,
    'topup_' || new.status::text || ':' || new.id,
    jsonb_build_object('topup_id', new.id, 'number', new.topup_number, 'amount_etb', new.amount_etb,
      'reference', new.transaction_reference, 'user_id', private.member_of(new.user_id),
      'balance_etb', (select wallet_balance_etb from public.customer_accounts where id = new.user_id),
      'decided_by', private.actor_name(new.reviewed_by), 'decided_at', new.reviewed_at, 'reason', new.review_note));
  return null;
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000060_telegram_user_ids.sql
-- 0060: every Telegram alert names the person by User ID only:
--   payload.user_id    = the customer (or account) the alert is about,
--   payload.by_user_id = the staff member who did it (admin actions, decisions).
-- Worked out when the message is queued, from the order / printing job / top-up / ticket / account.

create or replace function private.telegram_enrich()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  p jsonb := coalesce(new.payload, '{}'::jsonb);
  v_uid uuid;
  v_by uuid;
  v_src bigint;
  v_audit public.audit_logs;
  v_uuid_re constant text := '^[0-9a-fA-F-]{36}$';
begin
  if new.channel <> 'telegram' then return new; end if;
  if coalesce(p ->> 'user_id', '') !~ '^[1-9][0-9]{5}$' then
    if coalesce(p ->> 'order_id', '') ~ v_uuid_re then
      select user_id into v_uid from public.orders where id = (p ->> 'order_id')::uuid;
    end if;
    if v_uid is null and coalesce(p ->> 'job_id', '') ~ v_uuid_re then
      select coalesce(j.user_id, o.user_id) into v_uid from public.printing_jobs j left join public.orders o on o.id = j.order_id
       where j.id = (p ->> 'job_id')::uuid;
    end if;
    if v_uid is null and coalesce(p ->> 'topup_id', '') ~ v_uuid_re then
      select user_id into v_uid from public.wallet_topups where id = (p ->> 'topup_id')::uuid;
    end if;
    if v_uid is null and coalesce(p ->> 'number', '') like 'TU-%' then
      select user_id into v_uid from public.wallet_topups where topup_number = p ->> 'number';
    end if;
    if v_uid is null and coalesce(p ->> 'ticket_id', '') ~ v_uuid_re then
      select user_id into v_uid from public.support_tickets where id = (p ->> 'ticket_id')::uuid;
    end if;
    if v_uid is null and new.event_type = 'admin_action' and new.dedupe_key like 'feed:admin:%' then
      select * into v_audit from public.audit_logs where id = nullif(split_part(new.dedupe_key, ':', 3), '')::bigint;
      v_uid := private.subject_user(v_audit.entity_type, v_audit.entity_id);
      v_by := v_audit.actor_id;
    end if;
    if v_uid is null and new.event_type = 'notification_copy' and new.dedupe_key like 'feed:copy:%' then
      v_src := nullif(split_part(new.dedupe_key, ':', 3), '')::bigint;
      select recipient_user_id into v_uid from public.notifications_outbox where id = v_src;
    end if;
    if v_uid is null and new.event_type in ('security_event', 'security_alert') and p ? 'email' then
      select id into v_uid from auth.users where lower(email) = lower(p ->> 'email');
    end if;
    if v_uid is not null then p := p || jsonb_build_object('user_id', private.member_of(v_uid)); end if;
  end if;
  if v_by is null and coalesce(p ->> 'decided_by', p ->> 'by', '') <> '' then
    select id into v_by from public.profiles where full_name = coalesce(p ->> 'decided_by', p ->> 'by') limit 1;
  end if;
  if v_by is not null and not p ? 'by_user_id' then p := p || jsonb_build_object('by_user_id', private.member_of(v_by)); end if;
  new.payload := p;
  return new;
end;
$$;
revoke all on function private.telegram_enrich() from public, anon, authenticated;

drop trigger if exists notifications_outbox_telegram_enrich on public.notifications_outbox;
create trigger notifications_outbox_telegram_enrich before insert on public.notifications_outbox
  for each row execute function private.telegram_enrich();

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000061_super_admin_exports.sql
-- 0061: Excel downloads are for the Super Admin only (every export is recorded through
-- admin_log_export, which now refuses everyone else); wallet balances can be searched by User ID.

create or replace function public.admin_wallet_balances(p_search text default null, p_limit integer default 100)
returns table (user_id uuid, email text, full_name text, balance_etb numeric, last_activity timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_q text := nullif(btrim(coalesce(p_search, '')), '');
begin
  perform private.require_permission('wallet.manage');
  return query
    select c.id, u.email::text, c.full_name, c.wallet_balance_etb,
           (select max(l.created_at) from public.wallet_ledger l where l.user_id = c.id)
      from public.customer_accounts c join auth.users u on u.id = c.id
     where (c.wallet_balance_etb > 0 or exists (select 1 from public.wallet_ledger l where l.user_id = c.id))
       and (v_q is null or c.member_id = v_q or u.email ilike '%' || v_q || '%' or c.full_name ilike '%' || v_q || '%')
     order by 5 desc nulls last
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Excel downloads are for the Super Admin only.
  if coalesce(private.current_role_key(), '') <> 'super_admin' or not private.mfa_verified() then perform private.app_error('forbidden'); end if;
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  elsif p_kind = 'users' then perform private.require_permission('security.manage');
  elsif p_kind = 'support' then perform private.require_permission('support.view');
  elsif p_kind = 'customers' then perform private.require_permission('customers.view');
  elsif p_kind = 'products' then perform private.require_permission('products.view');
  elsif p_kind = 'wallet' then perform private.require_permission('wallet.manage');
  elsif p_kind = 'printing' then perform private.require_permission('printing.view');
  elsif p_kind = 'kpi' then perform private.require_permission('kpi.view');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000062_promotion_rules.sql
-- =============================================================================
-- 0062 PROMOTION RULES
--   * Every promo code can be used once per customer account (everyone or selected customers).
--   * A use counts once the payment is approved: the personal code is marked used (with the
--     order) and disappears from the customer's account. A rejected / cancelled order frees it.
--   * Revoke a promotion with a reason (anyone with promotions.manage). Only the Super Admin
--     can bring a revoked promotion back.
--   * Remove a code from a customer only with a reason, and only while it is not used.
--   * Delete: Super Admin only, only when the promotion was never used and nobody holds it
--     (remove it from the customers first).
--   * Personal codes can be given by User ID as well as by email.
-- =============================================================================

update public.promotions set once_per_customer = true where not once_per_customer;
alter table public.promotions alter column once_per_customer set default true;
alter table public.promotions add constraint promotions_once_per_customer check (once_per_customer);

alter table public.promotions
  add column revoked_at     timestamptz,
  add column revoked_by     uuid references auth.users(id) on delete set null,
  add column revoked_reason text check (revoked_reason is null or char_length(revoked_reason) between 5 and 300);
alter table public.promotions add constraint promotions_revoked_off check (revoked_at is null or not is_active);

alter table public.promotion_customers
  add column used_at       timestamptz,
  add column used_order_id uuid references public.orders(id) on delete set null;

-- Orders waiting for payment already hold the code (see apply_promotion); this records the
-- confirmed use when the payment is approved and frees it again if the order is cancelled.
update public.promotion_customers pc
   set used_at = o.payment_verified_at, used_order_id = o.id
  from public.orders o
 where o.promotion_id = pc.promotion_id and o.user_id = pc.user_id
   and o.payment_status = 'verified' and o.status not in ('expired', 'cancelled');

create or replace function private.promotion_redeemed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.promotion_id is null or new.user_id is null then return new; end if;
  if new.status in ('expired', 'cancelled') then
    update public.promotion_customers set used_at = null, used_order_id = null
     where used_order_id = new.id;
  elsif new.payment_status = 'verified' then
    update public.promotion_customers set used_at = coalesce(used_at, now()), used_order_id = new.id
     where promotion_id = new.promotion_id and user_id = new.user_id and used_order_id is distinct from new.id;
  end if;
  return new;
end;
$$;
create trigger orders_promotion_redeemed after insert or update of payment_status, status on public.orders
  for each row execute function private.promotion_redeemed();

-- Direct changes to promotions (the admin form) follow the rules too.
create or replace function private.promotions_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.once_per_customer := true;
  if tg_op = 'UPDATE' then
    -- Revoking goes through admin_revoke_promotion (with a reason).
    if current_setting('app.promo_revoke', true) is distinct from 'on' then
      if old.revoked_at is not null and new.is_active then
        -- Bringing a revoked promotion back: Super Admin only.
        if coalesce(private.current_role_key(), '') <> 'super_admin' then perform private.app_error('forbidden'); end if;
        new.revoked_at := null; new.revoked_by := null; new.revoked_reason := null;
      else
        new.revoked_at := old.revoked_at; new.revoked_by := old.revoked_by; new.revoked_reason := old.revoked_reason;
      end if;
    end if;
    -- Turning a personal promotion into one for everyone would hand the code to everybody.
    if old.restricted and not new.restricted
       and exists (select 1 from public.promotion_customers pc where pc.promotion_id = old.id) then
      perform private.app_error('promo_has_customers');
    end if;
  else
    new.revoked_at := null; new.revoked_by := null; new.revoked_reason := null;
  end if;
  return new;
end;
$$;
create trigger promotions_guard before insert or update on public.promotions
  for each row execute function private.promotions_guard();

-- Deleting and removing codes from customers only through the functions below.
revoke delete on public.promotions from authenticated;
drop policy if exists promotion_customers_admin_delete on public.promotion_customers;
revoke delete on public.promotion_customers from authenticated;

-- Audit entries for giving / removing a code carry the reason.
create or replace function private.audit_promotion_customer()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.promotion_customers := coalesce(new, old);
  v_code text;
  v_title text;
begin
  select p.code::text, p.title_en into v_code, v_title from public.promotions p where p.id = r.promotion_id;
  perform private.audit(
    case when tg_op = 'INSERT' then 'promo_assigned' else 'promo_unassigned' end,
    'customer_account', r.user_id::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('code', v_code, 'promotion', v_title, 'promotion_id', r.promotion_id,
      'reason', case when tg_op = 'DELETE' then nullif(current_setting('app.promo_reason', true), '') end)));
  return r;
end;
$$;

create or replace function public.admin_revoke_promotion(p_promotion_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.promotions;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform private.require_permission('promotions.manage');
  if char_length(v_reason) not between 5 and 300 then perform private.app_error('invalid_reason'); end if;
  select * into v from public.promotions where id = p_promotion_id for update;
  if not found then perform private.app_error('not_found'); end if;
  if v.revoked_at is not null then perform private.app_error('invalid_transition'); end if;
  perform set_config('app.promo_revoke', 'on', true);
  update public.promotions
     set is_active = false, show_on_homepage = false, revoked_at = now(), revoked_by = auth.uid(), revoked_reason = v_reason
   where id = p_promotion_id;
  perform set_config('app.promo_revoke', '', true);
  perform private.audit('promo_revoked', 'promotions', p_promotion_id::text, null, null,
    jsonb_build_object('code', v.code, 'promotion', v.title_en, 'reason', v_reason));
end;
$$;

create or replace function public.admin_unassign_promotion(p_promotion_id uuid, p_user_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform private.require_permission('promotions.manage');
  if char_length(v_reason) not between 5 and 300 then perform private.app_error('invalid_reason'); end if;
  if not exists (select 1 from public.promotion_customers where promotion_id = p_promotion_id and user_id = p_user_id) then
    perform private.app_error('not_found');
  end if;
  -- Used, or on an order still waiting for payment: it stays (the order keeps its discount).
  if exists (select 1 from public.orders o where o.promotion_id = p_promotion_id and o.user_id = p_user_id
              and o.status not in ('expired', 'cancelled')) then
    perform private.app_error('promo_in_use');
  end if;
  perform set_config('app.promo_reason', v_reason, true);
  delete from public.promotion_customers where promotion_id = p_promotion_id and user_id = p_user_id;
  perform set_config('app.promo_reason', '', true);
end;
$$;

create or replace function public.admin_delete_promotion(p_promotion_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(private.current_role_key(), '') <> 'super_admin' or not private.mfa_verified() then perform private.app_error('forbidden'); end if;
  if not exists (select 1 from public.promotions where id = p_promotion_id) then perform private.app_error('not_found'); end if;
  if exists (select 1 from public.orders o where o.promotion_id = p_promotion_id and o.status not in ('expired', 'cancelled')) then
    perform private.app_error('promo_in_use');
  end if;
  if exists (select 1 from public.promotion_customers where promotion_id = p_promotion_id) then
    perform private.app_error('promo_has_customers');
  end if;
  delete from public.promotions where id = p_promotion_id;  -- expired / cancelled orders keep their amounts (promotion_id → null)
end;
$$;

-- Give a personal promotion by User ID or email.
create or replace function public.admin_assign_promotion(p_promotion_id uuid, p_emails text[], p_notify boolean default true, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_promo public.promotions;
  v_email text;
  v_user uuid;
  v_added text[] := '{}';
  v_already text[] := '{}';
  v_missing text[] := '{}';
begin
  perform private.require_permission('promotions.manage');
  if p_note is not null and char_length(p_note) > 300 then perform private.app_error('invalid_request', 'note'); end if;
  select * into v_promo from public.promotions where id = p_promotion_id;
  if not found then perform private.app_error('not_found'); end if;
  if not v_promo.restricted then perform private.app_error('invalid_request', 'promotion is not personal'); end if;
  if v_promo.revoked_at is not null then perform private.app_error('invalid_transition'); end if;
  if p_emails is null or cardinality(p_emails) = 0 or cardinality(p_emails) > 200 then
    perform private.app_error('invalid_request');
  end if;
  foreach v_email in array p_emails loop
    v_email := lower(btrim(v_email));
    continue when v_email = '';
    v_user := null;
    if v_email ~ '^[1-9][0-9]{5}$' then
      select c.id into v_user from public.customer_accounts c where c.member_id = v_email;
    else
      select u.id into v_user from auth.users u where lower(u.email) = v_email;
    end if;
    if v_user is null then
      v_missing := v_missing || v_email;
      continue;
    end if;
    insert into public.promotion_customers (promotion_id, user_id) values (p_promotion_id, v_user)
    on conflict do nothing;
    if found then
      v_added := v_added || v_email;
      if coalesce(p_notify, true) and v_promo.is_active then perform private.notify_promo_gift(p_promotion_id, v_user, p_note); end if;
    else
      v_already := v_already || v_email;
    end if;
  end loop;
  return jsonb_build_object('added', to_jsonb(v_added), 'already', to_jsonb(v_already), 'not_found', to_jsonb(v_missing));
end;
$$;

-- Holders of personal codes: User ID, used (payment approved, with the order) or reserved (waiting for payment).
drop function if exists public.admin_promotion_customers(uuid, uuid);
create function public.admin_promotion_customers(p_promotion_id uuid default null, p_user_id uuid default null)
returns table (promotion_id uuid, user_id uuid, member_id text, email text, full_name text, code text, title_en text,
               assigned_at timestamptz, used boolean, used_at timestamptz, used_order_number text, reserved boolean,
               revoked boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('promotions.manage');
  return query
    select pc.promotion_id, pc.user_id, c.member_id::text, u.email::text, c.full_name, p.code::text, p.title_en, pc.created_at,
           pc.used_at is not null, pc.used_at, uo.order_number::text,
           pc.used_at is null and exists (select 1 from public.orders o where o.promotion_id = pc.promotion_id and o.user_id = pc.user_id
                    and o.status not in ('expired', 'cancelled')),
           p.revoked_at is not null
      from public.promotion_customers pc
      join public.promotions p on p.id = pc.promotion_id
      join auth.users u on u.id = pc.user_id
      left join public.customer_accounts c on c.id = pc.user_id
      left join public.orders uo on uo.id = pc.used_order_id
     where (p_promotion_id is null or pc.promotion_id = p_promotion_id)
       and (p_user_id is null or pc.user_id = p_user_id)
     order by pc.created_at desc
     limit 1000;
end;
$$;

-- The customer's own codes: used ones disappear.
create or replace function public.my_offers()
returns table (code text, title_en text, title_am text, description_en text, description_am text,
               discount_type text, discount_value numeric, min_order_etb numeric, ends_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select p.code::text, p.title_en, p.title_am, p.description_en, p.description_am,
         p.discount_type, p.discount_value, p.min_order_etb, p.ends_at
    from public.promotion_customers pc
    join public.promotions p on p.id = pc.promotion_id
   where pc.user_id = (select auth.uid())
     and private.is_active_customer()
     and pc.used_at is null
     and p.restricted and p.is_active and p.revoked_at is null and p.code is not null
     and (p.starts_at is null or p.starts_at <= now()) and (p.ends_at is null or p.ends_at > now())
     and not exists (
       select 1 from public.orders o where o.promotion_id = p.id and o.user_id = pc.user_id
          and o.status not in ('expired', 'cancelled'))
     and (p.max_redemptions is null or (
       select count(*) from public.orders o where o.promotion_id = p.id
          and o.status not in ('expired', 'cancelled')) < p.max_redemptions)
   order by p.ends_at nulls last, pc.created_at desc
$$;

revoke all on function public.admin_revoke_promotion(uuid, text) from public, anon;
revoke all on function public.admin_unassign_promotion(uuid, uuid, text) from public, anon;
revoke all on function public.admin_delete_promotion(uuid) from public, anon;
revoke all on function public.admin_promotion_customers(uuid, uuid) from public, anon;
revoke all on function private.promotion_redeemed() from public;
revoke all on function private.promotions_guard() from public;
grant execute on function public.admin_revoke_promotion(uuid, text) to authenticated;
grant execute on function public.admin_unassign_promotion(uuid, uuid, text) to authenticated;
grant execute on function public.admin_delete_promotion(uuid) to authenticated;
grant execute on function public.admin_promotion_customers(uuid, uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000063_promotion_uses_export.sql
-- 0063: Excel of promotion uses (Super Admin only): every order paid with a promo code — who (User ID),
-- which order, the price before the discount, the discount and the price paid. For complaints.

create or replace function public.admin_promotion_uses(p_from timestamptz, p_to timestamptz, p_limit integer default 5000)
returns table (order_number text, member_id text, code text, promotion text, audience text, discount_rule text,
               items text, subtotal_etb numeric, delivery_fee_etb numeric, original_total_etb numeric, discount_etb numeric,
               total_etb numeric, payment_method text, order_status text, ordered_at timestamptz, paid_at timestamptz,
               promotion_status text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('promotions.manage');
  if p_from is null or p_to is null or p_to <= p_from then perform private.app_error('invalid_request'); end if;
  return query
    select o.order_number::text, c.member_id::text, p.code::text, p.title_en,
           case when p.restricted then 'Selected customers' else 'Every customer' end,
           case when p.discount_type = 'percent' then trim(to_char(p.discount_value, 'FM990.##')) || '% off'
                else trim(to_char(p.discount_value, 'FM999999990.##')) || ' ETB off' end,
           (select string_agg(i.quantity || ' × ' || i.name_en || ' (' || i.unit_price_etb || ' ETB)', '; ' order by i.created_at)
              from public.order_items i where i.order_id = o.id),
           o.subtotal_etb, o.delivery_fee_etb, o.subtotal_etb + o.delivery_fee_etb, o.discount_etb, o.total_etb,
           o.payment_method::text, o.status::text, o.created_at, o.payment_verified_at,
           case when p.revoked_at is not null then 'Revoked' when p.is_active then 'Active' else 'Off' end
      from public.orders o
      join public.promotions p on p.id = o.promotion_id
      left join public.customer_accounts c on c.id = o.user_id
     where o.payment_verified_at is not null
       and o.payment_verified_at >= p_from and o.payment_verified_at < p_to
     order by o.payment_verified_at
     limit greatest(1, least(coalesce(p_limit, 5000), 20000));
end;
$$;
revoke all on function public.admin_promotion_uses(timestamptz, timestamptz, integer) from public, anon;
grant execute on function public.admin_promotion_uses(timestamptz, timestamptz, integer) to authenticated;

create or replace function public.admin_log_export(p_kind text, p_metadata jsonb default '{}'::jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Excel downloads are for the Super Admin only.
  if coalesce(private.current_role_key(), '') <> 'super_admin' or not private.mfa_verified() then perform private.app_error('forbidden'); end if;
  if p_kind = 'orders' then perform private.require_permission('orders.view_all');
  elsif p_kind = 'activity' then perform private.require_permission('audit.view');
  elsif p_kind = 'payments' then perform private.require_permission('payments.view');
  elsif p_kind = 'sales' then perform private.require_permission('analytics.view');
  elsif p_kind = 'all' then perform private.require_permission('data.manage');
  elsif p_kind = 'notifications' then perform private.require_permission('settings.manage');
  elsif p_kind = 'users' then perform private.require_permission('security.manage');
  elsif p_kind = 'support' then perform private.require_permission('support.view');
  elsif p_kind = 'customers' then perform private.require_permission('customers.view');
  elsif p_kind = 'products' then perform private.require_permission('products.view');
  elsif p_kind = 'wallet' then perform private.require_permission('wallet.manage');
  elsif p_kind = 'printing' then perform private.require_permission('printing.view');
  elsif p_kind = 'kpi' then perform private.require_permission('kpi.view');
  elsif p_kind = 'promotions' then perform private.require_permission('promotions.manage');
  else perform private.app_error('invalid_request');
  end if;
  if p_metadata is null or jsonb_typeof(p_metadata) <> 'object' or length(p_metadata::text) > 2000 then
    perform private.app_error('invalid_request');
  end if;
  perform private.audit('export_' || p_kind, 'export', null, null, null, p_metadata);
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000064_promotion_alerts_excel_queue.sql
-- =============================================================================
-- 0064 PROMOTION ALERTS + EXCEL COPIES THROUGH THE QUEUE
--   * Every promotion change is a security alert in Telegram: created, changed, switched on / off,
--     revoked (with the reason), brought back, deleted, code given to / removed from a customer —
--     and "code used" when an order with a code is paid (User ID, order, original price, discount, price paid).
--   * Every Excel download is copied, as the file with an alert, to the receipts group through the
--     notification queue (retried like receipts; failures show under Notifications). The file waits in
--     the private excel-exports bucket and is removed once Telegram has it.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('excel-exports', 'excel-exports', false, 52428800, array['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
-- No storage policies: only the server (secret key) reads or writes this bucket.

create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test', 'promotion_alert') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test', 'excel_export') then 'receipts'
    when p_event in ('printing_document', 'printing_test') then 'printing'
    when p_event in ('support_ticket', 'support_reply', 'support_rating', 'support_test') then 'support'
    else 'orders'
  end
$$;

-- ------------------------------------------------------------ Excel copies
create or replace function public.queue_excel_copy(p_path text, p_file_name text, p_title text, p_rows integer default null, p_by uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(p_path, '') !~ '^[0-9a-f-]{36}\.xlsx$' or coalesce(p_file_name, '') !~ '^[A-Za-z0-9._-]{1,120}$'
     or char_length(coalesce(p_title, '')) not between 1 and 120 then
    perform private.app_error('invalid_request');
  end if;
  perform private.enqueue_notification('excel_export', 'excel:' || p_path, jsonb_strip_nulls(jsonb_build_object(
    'title', p_title, 'file_name', p_file_name, 'rows', p_rows, 'by_user_id', private.member_of(p_by), 'at', now())),
    'excel-exports', p_path);
end;
$$;
revoke all on function public.queue_excel_copy(text, text, text, integer, uuid) from public, anon, authenticated;
grant execute on function public.queue_excel_copy(text, text, text, integer, uuid) to service_role;

-- ------------------------------------------------------------ Promotion alerts
create or replace function private.promo_summary(p public.promotions)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'promotion_id', p.id, 'title', p.title_en, 'code', p.code::text,
    'discount', case when p.discount_type = 'percent' then trim(to_char(p.discount_value, 'FM990.##')) || '% off'
                     else trim(to_char(p.discount_value, 'FM999999990.##')) || ' ETB off' end,
    'audience', case when p.restricted then 'Selected customers' else 'Every customer' end,
    'applies_to', coalesce((select 'Product: ' || pr.name_en from public.products pr where pr.id = p.product_id),
                           (select 'Category: ' || c.name_en from public.categories c where c.id = p.category_id), 'All products'),
    'min_order_etb', nullif(p.min_order_etb, 0), 'usage_limit', p.max_redemptions,
    'starts_at', p.starts_at, 'ends_at', p.ends_at, 'active', p.is_active, 'homepage', nullif(p.show_on_homepage, false)))
$$;

create or replace function private.promotion_alert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_change text;
  v_fields text[] := '{}';
  v_p public.promotions := coalesce(new, old);
begin
  if tg_op = 'INSERT' then
    v_change := 'created';
  elsif tg_op = 'DELETE' then
    v_change := 'deleted';
  elsif old.revoked_at is null and new.revoked_at is not null then
    v_change := 'revoked';
  elsif old.revoked_at is not null and new.revoked_at is null then
    v_change := 'restored';
  else
    if old.title_en is distinct from new.title_en then v_fields := array_append(v_fields, 'title'::text); end if;
    if old.code is distinct from new.code then v_fields := array_append(v_fields, 'code'::text); end if;
    if old.discount_type is distinct from new.discount_type or old.discount_value is distinct from new.discount_value then v_fields := array_append(v_fields, 'discount'::text); end if;
    if old.restricted is distinct from new.restricted then v_fields := array_append(v_fields, 'who can use it'::text); end if;
    if old.product_id is distinct from new.product_id or old.category_id is distinct from new.category_id then v_fields := array_append(v_fields, 'applies to'::text); end if;
    if old.min_order_etb is distinct from new.min_order_etb then v_fields := array_append(v_fields, 'minimum order'::text); end if;
    if old.max_redemptions is distinct from new.max_redemptions then v_fields := array_append(v_fields, 'usage limit'::text); end if;
    if old.starts_at is distinct from new.starts_at or old.ends_at is distinct from new.ends_at then v_fields := array_append(v_fields, 'dates'::text); end if;
    if old.show_on_homepage is distinct from new.show_on_homepage then v_fields := array_append(v_fields, 'homepage'::text); end if;
    if old.description_en is distinct from new.description_en then v_fields := array_append(v_fields, 'description'::text); end if;
    if old.is_active is distinct from new.is_active then
      v_change := case when new.is_active then 'switched_on' else 'switched_off' end;
    elsif cardinality(v_fields) > 0 then
      v_change := 'changed';
    else
      return null; -- nothing a person would notice (e.g. only updated_at)
    end if;
  end if;
  perform private.enqueue_notification('promotion_alert', 'promo:' || v_p.id || ':' || v_change || ':' || txid_current() || ':' || clock_timestamp(),
    private.promo_summary(v_p) || jsonb_strip_nulls(jsonb_build_object(
      'change', v_change,
      'changed', case when cardinality(v_fields) > 0 then array_to_string(v_fields, ', ') end,
      'reason', case when v_change = 'revoked' then v_p.revoked_reason end,
      'by_user_id', private.member_of(auth.uid()),
      'at', now())));
  return null;
end;
$$;
drop trigger if exists promotions_telegram_alert on public.promotions;
create trigger promotions_telegram_alert after insert or update or delete on public.promotions
  for each row execute function private.promotion_alert();

create or replace function private.promotion_customer_alert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.promotion_customers := coalesce(new, old);
  v public.promotions;
begin
  select * into v from public.promotions where id = r.promotion_id;
  if not found then return null; end if;  -- the promotion itself is being deleted
  perform private.enqueue_notification('promotion_alert', 'promo:' || r.promotion_id || ':' || r.user_id || ':' || tg_op || ':' || clock_timestamp(),
    private.promo_summary(v) || jsonb_strip_nulls(jsonb_build_object(
      'change', case when tg_op = 'INSERT' then 'given' else 'removed' end,
      'user_id', private.member_of(r.user_id),
      'reason', case when tg_op = 'DELETE' then nullif(current_setting('app.promo_reason', true), '') end,
      'by_user_id', private.member_of(auth.uid()),
      'at', now())));
  return null;
end;
$$;
drop trigger if exists promotion_customers_telegram_alert on public.promotion_customers;
create trigger promotion_customers_telegram_alert after insert or delete on public.promotion_customers
  for each row execute function private.promotion_customer_alert();

-- Code used: the order's payment was approved (or paid with the balance).
create or replace function private.promotion_redeemed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.promotions;
begin
  if new.promotion_id is null or new.user_id is null then return new; end if;
  if new.status in ('expired', 'cancelled') then
    update public.promotion_customers set used_at = null, used_order_id = null
     where used_order_id = new.id;
  elsif new.payment_status = 'verified' then
    update public.promotion_customers set used_at = coalesce(used_at, now()), used_order_id = new.id
     where promotion_id = new.promotion_id and user_id = new.user_id and used_order_id is distinct from new.id;
    select * into v from public.promotions where id = new.promotion_id;
    if found then
      perform private.enqueue_notification('promotion_alert', 'promo_used:' || new.id,
        private.promo_summary(v) || jsonb_strip_nulls(jsonb_build_object(
          'change', 'used', 'user_id', private.member_of(new.user_id), 'order_id', new.id, 'order_number', new.order_number,
          'original_etb', new.subtotal_etb + new.delivery_fee_etb, 'discount_etb', new.discount_etb, 'total_etb', new.total_etb,
          'payment_method', new.payment_method, 'at', now())));
    end if;
  end if;
  return new;
end;
$$;

revoke all on function private.promo_summary(public.promotions) from public;
revoke all on function private.promotion_alert() from public;
revoke all on function private.promotion_customer_alert() from public;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000065_upload_virus_scan.sql
-- 0065: customer uploads are virus-scanned (Cloudmersive) before they are accepted.
--   * New security events: upload_blocked (the scan found something — file deleted, upload refused) and
--     scan_unavailable (the scanner could not be reached — upload refused, nothing unscanned is kept).
--   * A blocked upload makes the account high-risk at once (active alert on the Security page).

alter table public.security_events drop constraint if exists security_events_kind_check;
alter table public.security_events add constraint security_events_kind_check check (kind in (
  'admin_login_failed', 'admin_login_not_staff', 'admin_mfa_failed', 'admin_login_success',
  'customer_login_failed', 'staff_customer_login', 'login_blocked', 'signup_blocked', 'rate_limited',
  'upload_blocked', 'scan_unavailable'));

create or replace function private.email_risk_24h(p_email text)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
           count(*) filter (where s.kind in ('admin_login_failed', 'admin_login_not_staff')) * 3
         + count(*) filter (where s.kind = 'admin_mfa_failed') * 4
         + count(*) filter (where s.kind = 'customer_login_failed')
         + count(*) filter (where s.kind in ('login_blocked', 'signup_blocked')) * 2
         + count(*) filter (where s.kind = 'rate_limited') * 2
         + count(*) filter (where s.kind = 'upload_blocked') * 6
         + greatest(count(distinct s.ip_hash) - 1, 0) * 2, 0)::int
    from public.security_events s
    left join public.security_reviews r on r.subject_type = 'email' and r.subject = lower(s.email)
   where lower(s.email) = lower(p_email) and s.kind not in ('admin_login_success', 'scan_unavailable')
     and s.created_at > now() - interval '24 hours'
     and (r.reviewed_at is null or s.created_at > r.reviewed_at)
$$;
revoke all on function private.email_risk_24h(text) from public;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000066_upload_scan_history.sql
-- 0066: history of every virus scan of a customer upload (Cloudmersive), kept in our own database:
-- who (User ID), what kind of upload, file type / size / fingerprint (sha256), the result (clean / blocked /
-- scanner unavailable), what was found and how long it took. Admin → Security → File scans; the payment,
-- top-up and printing pages show the scan of their exact file (matched by fingerprint). Kept 1 year.

create table public.upload_scans (
  id          bigint generated always as identity primary key,
  created_at  timestamptz not null default now(),
  user_id     uuid references auth.users(id) on delete set null,
  member_id   text check (member_id ~ '^[1-9][0-9]{5}$'),
  source      text not null check (source in ('payment_receipt', 'topup_receipt', 'printing_file')),
  ref         text check (char_length(ref) <= 64),
  file_type   text not null check (file_type ~ '^[a-z0-9.+/-]{1,80}$'),
  size_bytes  integer not null check (size_bytes >= 0),
  sha256      text not null check (sha256 ~ '^[0-9a-f]{64}$'),
  result      text not null check (result in ('clean', 'blocked', 'unavailable')),
  findings    text check (char_length(findings) <= 500),
  duration_ms integer check (duration_ms >= 0),
  scanner     text not null default 'cloudmersive' check (scanner in ('cloudmersive'))
);
create index upload_scans_created_idx on public.upload_scans (created_at desc);
create index upload_scans_sha_idx on public.upload_scans (sha256);
create index upload_scans_user_idx on public.upload_scans (user_id);

alter table public.upload_scans enable row level security;
revoke all on public.upload_scans from anon, authenticated;
grant select on public.upload_scans to authenticated;
create policy upload_scans_staff_read on public.upload_scans for select to authenticated
  using ((select private.has_permission('audit.view')) or (select private.has_permission('payments.view'))
         or (select private.has_permission('wallet.manage')) or (select private.has_permission('printing.view')));
-- Rows are written only by the server (record_upload_scan); nobody edits or deletes them (kept 1 year).

create or replace function public.record_upload_scan(
  p_user_id uuid, p_source text, p_ref text, p_file_type text, p_size integer, p_sha256 text,
  p_result text, p_findings text default null, p_duration_ms integer default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.upload_scans (user_id, member_id, source, ref, file_type, size_bytes, sha256, result, findings, duration_ms)
  values (p_user_id, private.member_of(p_user_id), p_source, left(p_ref, 64), p_file_type, p_size, p_sha256, p_result,
          left(p_findings, 500), p_duration_ms);
  delete from public.upload_scans where id in (
    select id from public.upload_scans where created_at < now() - interval '365 days' order by id limit 200);
end;
$$;
revoke all on function public.record_upload_scan(uuid, text, text, text, integer, text, text, text, integer) from public, anon, authenticated;
grant execute on function public.record_upload_scan(uuid, text, text, text, integer, text, text, text, integer) to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000067_printing_payment_alert_about.sql
-- 0067:
--   * A printing order whose payment receipt was attached is always announced in the orders & payments
--     Telegram group ("waiting for verification"), whatever the "pending payment alerts" switch says —
--     like wallet top-ups. Product orders still follow the switch. The documents go to the printing
--     group only after the payment is approved (unchanged).
--   * "About us" page text, edited in Admin → Settings → About us.

create or replace function private.telegram_filter()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.channel <> 'telegram' then return new; end if;
  if new.event_type in ('order_placed', 'order_status', 'printing_status', 'order_cancelled', 'payment_rejected', 'notification_copy', 'printing_request') then
    return null;
  end if;
  if new.event_type in ('new_order', 'payment_resubmitted') then
    -- Printing orders are marked (own title in Telegram) and always announced.
    if exists (select 1 from public.order_items i
                where i.order_id = case when coalesce(new.payload ->> 'order_id', '') ~ '^[0-9a-fA-F-]{36}$' then (new.payload ->> 'order_id')::uuid end
                  and i.item_type = 'printing') then
      new.payload := new.payload || jsonb_build_object('printing', true);
    elsif not private.feed_on('pending_payments') then
      return null;
    end if;
  end if;
  return new;
end;
$$;

insert into public.website_settings (key, value, is_public)
values ('about', jsonb_build_object(
  'title', jsonb_build_object('en', '', 'am', ''),
  'body', jsonb_build_object('en', '', 'am', ''),
  'show_services', true, 'show_why_us', true), true)
on conflict (key) do nothing;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261123000068_courier.sql
-- =============================================================================
-- 0068 COURIERS (and the role used by the separate sign-in addresses)
--   * New permission set "Courier" with one permission: deliveries.own — only the deliveries assigned
--     to them, through the functions below (couriers cannot read the orders table).
--   * Admin assigns a delivery order to a courier (orders.manage). A 4-digit delivery code is made for
--     the customer (shown on their order page); the courier enters it at the door.
--   * Courier steps: Picked up (→ out for delivery), Delivered (with the customer's code → completed),
--     Couldn't deliver (with a reason → back to preparing, admin decides). 5 wrong codes lock the code.
--   * The customer's name, phone and address are shown to the courier only while the delivery is
--     assigned to them and not finished.
--   * Every step: Activity log + orders & payments Telegram group (User ID of the courier).
--   * my_staff_status also returns the permission set (each one signs in at its own address).
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('deliveries.own', 'Courier app: deliver the orders assigned to me')
on conflict (key) do nothing;

insert into public.admin_roles (key, name, description, is_builtin)
values ('courier', 'Courier', 'Delivers the orders assigned to them (courier app only).', true)
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, 'deliveries.own' from public.admin_roles r where r.key = 'courier'
on conflict do nothing;
-- The Super Admin has every permission.
insert into public.role_permissions (role_id, permission_key)
select r.id, 'deliveries.own' from public.admin_roles r where r.key = 'super_admin'
on conflict do nothing;

alter table public.orders
  add column courier_id            uuid references public.profiles(id) on delete set null,
  add column courier_assigned_at   timestamptz,
  add column picked_up_at          timestamptz,
  add column delivered_at          timestamptz,
  add column delivery_code         text check (delivery_code ~ '^[0-9]{4}$'),
  add column delivery_code_tries   integer not null default 0 check (delivery_code_tries >= 0),
  add column delivery_failed_at    timestamptz,
  add column delivery_fail_reason  text check (char_length(delivery_fail_reason) <= 300),
  add column delivery_attempts     integer not null default 0 check (delivery_attempts >= 0);
create index orders_courier_idx on public.orders (courier_id) where courier_id is not null;

create or replace function public.my_staff_status()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'staff', exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.is_active),
    'mfa_verified', private.mfa_verified(),
    'role', (select r.key from public.profiles p join public.admin_roles r on r.id = p.role_id
              where p.id = (select auth.uid()) and p.is_active))
$$;

create or replace function private.delivery_event(p_order public.orders, p_step text, p_extra jsonb default '{}'::jsonb)
returns void
language sql
security definer
set search_path = ''
as $$
  select private.enqueue_notification('delivery_update', 'delivery:' || p_order.id || ':' || p_step || ':' || clock_timestamp(),
    jsonb_build_object('order_id', p_order.id, 'order_number', p_order.order_number, 'step', p_step,
      'courier_user_id', private.member_of(p_order.courier_id), 'by_user_id', private.member_of((select auth.uid())),
      'city', p_order.city, 'at', now()) || coalesce(p_extra, '{}'::jsonb))
$$;

-- Admin: give a delivery order to a courier (or take it back with null).
create or replace function public.admin_assign_courier(p_order_id uuid, p_courier uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders;
begin
  perform private.require_permission('orders.manage');
  select * into v from public.orders where id = p_order_id for update;
  if not found then perform private.app_error('not_found'); end if;
  if v.fulfillment_method <> 'delivery' then perform private.app_error('invalid_request', 'pickup order'); end if;
  if v.status not in ('confirmed', 'processing', 'out_for_delivery') then perform private.app_error('invalid_transition'); end if;
  if p_courier is not null and not exists (
       select 1 from public.profiles p join public.admin_roles r on r.id = p.role_id
        where p.id = p_courier and p.is_active and r.key = 'courier') then
    perform private.app_error('invalid_assignee');
  end if;
  if p_courier is null and v.status = 'out_for_delivery' then perform private.app_error('invalid_transition', 'on the way'); end if;
  update public.orders
     set courier_id = p_courier,
         courier_assigned_at = case when p_courier is null then null else now() end,
         delivery_code = case when p_courier is null then delivery_code else coalesce(delivery_code, lpad((floor(random() * 10000))::int::text, 4, '0')) end,
         delivery_code_tries = 0
   where id = v.id
  returning * into v;
  perform private.audit(case when p_courier is null then 'courier_unassigned' else 'courier_assigned' end, 'order', v.id::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('order_number', v.order_number, 'courier_user_id', private.member_of(p_courier))));
  if p_courier is not null then perform private.delivery_event(v, 'assigned'); end if;
end;
$$;

-- Couriers' active deliveries (contact details only while assigned and not finished) + today's finished ones.
create or replace function public.courier_deliveries()
returns table (order_id uuid, order_number text, status text, customer_name text, customer_phone text, city text,
               address_line text, delivery_instructions text, items jsonb, total_etb numeric, assigned_at timestamptz,
               picked_up_at timestamptz, delivered_at timestamptz, fail_reason text, active boolean)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('deliveries.own');
  return query
    select o.id, o.order_number::text, o.status::text,
           case when a then o.customer_name end, case when a then o.customer_phone end, o.city,
           case when a then o.address_line end, case when a then o.delivery_instructions end,
           (select coalesce(jsonb_agg(jsonb_build_object('name', i.name_en, 'quantity', i.quantity) order by i.created_at), '[]'::jsonb)
              from public.order_items i where i.order_id = o.id),
           o.total_etb, o.courier_assigned_at, o.picked_up_at, o.delivered_at, o.delivery_fail_reason, a
      from public.orders o
      cross join lateral (select o.status in ('confirmed', 'processing', 'out_for_delivery') as a) x
     where o.courier_id = (select auth.uid())
       and (a or (o.status = 'completed' and o.delivered_at > now() - interval '24 hours'))
     order by a desc, o.courier_assigned_at;
end;
$$;

create or replace function private.courier_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders;
begin
  perform private.require_permission('deliveries.own');
  select * into v from public.orders where id = p_order_id for update;
  if not found or v.courier_id is distinct from (select auth.uid()) then perform private.app_error('not_found'); end if;
  return v;
end;
$$;

create or replace function public.courier_pick_up(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders := private.courier_order(p_order_id);
begin
  if v.status not in ('confirmed', 'processing') then perform private.app_error('invalid_transition'); end if;
  perform private.set_status_note('Picked up by the courier');
  update public.orders set status = 'out_for_delivery', picked_up_at = now(), delivery_failed_at = null, delivery_fail_reason = null
   where id = v.id returning * into v;
  perform private.audit('delivery_picked_up', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number));
  perform private.delivery_event(v, 'picked_up');
end;
$$;

-- true = delivered; false = wrong code (the try is counted; 5 wrong tries lock the code).
create or replace function public.courier_deliver(p_order_id uuid, p_code text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders := private.courier_order(p_order_id);
begin
  if v.status <> 'out_for_delivery' then perform private.app_error('invalid_transition'); end if;
  if v.delivery_code_tries >= 5 then perform private.app_error('delivery_locked'); end if;
  if v.delivery_code is null or coalesce(btrim(p_code), '') <> v.delivery_code then
    update public.orders set delivery_code_tries = delivery_code_tries + 1 where id = v.id returning * into v;
    if v.delivery_code_tries >= 5 then
      perform private.audit('delivery_code_locked', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number));
      perform private.delivery_event(v, 'code_locked');
    end if;
    -- The failed try is kept: a raised error would roll it back, so answer with a result instead.
    return false;
  end if;
  perform private.set_status_note('Delivered — customer''s code checked by the courier');
  update public.orders set status = 'completed', delivered_at = now() where id = v.id returning * into v;
  perform private.audit('delivery_completed', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number));
  perform private.delivery_event(v, 'delivered');
  return true;
end;
$$;

create or replace function public.courier_fail(p_order_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders := private.courier_order(p_order_id);
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if char_length(v_reason) not between 3 and 300 then perform private.app_error('invalid_reason'); end if;
  if v.status <> 'out_for_delivery' then perform private.app_error('invalid_transition'); end if;
  perform private.set_status_note('Courier could not deliver: ' || v_reason);
  update public.orders
     set status = 'processing', delivery_failed_at = now(), delivery_fail_reason = v_reason, delivery_attempts = delivery_attempts + 1
   where id = v.id returning * into v;
  perform private.audit('delivery_failed', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number, 'reason', v_reason));
  perform private.delivery_event(v, 'failed', jsonb_build_object('reason', v_reason));
end;
$$;

revoke all on function public.admin_assign_courier(uuid, uuid) from public, anon;
revoke all on function public.courier_deliveries() from public, anon;
revoke all on function public.courier_pick_up(uuid) from public, anon;
revoke all on function public.courier_deliver(uuid, text) from public, anon;
revoke all on function public.courier_fail(uuid, text) from public, anon;
revoke all on function private.courier_order(uuid) from public;
revoke all on function private.delivery_event(public.orders, text, jsonb) from public;
grant execute on function public.admin_assign_courier(uuid, uuid) to authenticated;
grant execute on function public.courier_deliveries() to authenticated;
grant execute on function public.courier_pick_up(uuid) to authenticated;
grant execute on function public.courier_deliver(uuid, text) to authenticated;
grant execute on function public.courier_fail(uuid, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261124000069_customer_approval.sql
-- =============================================================================
-- 0069 CUSTOMER ACCOUNT APPROVAL
--   * Every NEW customer account starts "Under verification" (pending). Existing accounts are approved.
--   * Pending customers can sign in, browse, see their account and use Support & feedback — but cannot
--     order, top up, use printing, write reviews or ask for stock alerts (refused in the database).
--   * Someone with the new permission customers.approve approves it, or rejects it with a reason:
--     the email is put on the block list (with the reason) and the app emails the customer and deletes
--     the account. Both are in the Activity log; new accounts are announced in the security group.
--   * Accounts invited by the shop (Admin → Customers → Invite) are approved at once.
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('customers.approve', 'Approve or reject new customer accounts')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, 'customers.approve' from public.admin_roles r where r.key = 'super_admin'
on conflict do nothing;

-- Existing accounts: approved. New ones: pending (the column default changes after the backfill).
alter table public.customer_accounts
  add column approval_status text not null default 'approved' check (approval_status in ('pending', 'approved')),
  add column approved_at     timestamptz,
  add column approved_by     uuid references auth.users(id) on delete set null;
alter table public.customer_accounts alter column approval_status set default 'pending';
create index customer_accounts_pending_idx on public.customer_accounts (created_at) where approval_status = 'pending';
-- (Customers cannot change these columns: only full_name, phone, address, date of birth and sex are updatable.)

-- Buying / creating things needs an approved account (orders, printing, top-ups, reviews, stock alerts, personal codes).
create or replace function private.assert_confirmed_user(p_user_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_email text;
begin
  select email into v_email from auth.users where id = p_user_id and email_confirmed_at is not null;
  if p_user_id is null or v_email is null then
    perform private.app_error('login_required');
  end if;
  if not private.is_active_user(p_user_id) then
    perform private.app_error('account_deactivated');
  end if;
  if exists (select 1 from public.profiles where id = p_user_id) then
    perform private.app_error('staff_account');
  end if;
  if private.email_is_blocked(v_email) then
    perform private.app_error('email_blocked');
  end if;
  if exists (select 1 from public.customer_accounts where id = p_user_id and approval_status = 'pending') then
    perform private.app_error('account_pending');
  end if;
end;
$$;

-- New account → security group alert (User ID; the email is not shown).
create or replace function private.customer_pending_alert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.approval_status = 'pending' and not exists (select 1 from public.profiles where id = new.id) then
    perform private.enqueue_notification('account_pending', 'account_pending:' || new.id,
      jsonb_build_object('user_id', new.member_id, 'at', now()));
  end if;
  return null;
end;
$$;
create trigger customer_accounts_pending_alert after insert on public.customer_accounts
  for each row execute function private.customer_pending_alert();

-- Accounts waiting for a decision (approvers only).
create or replace function public.admin_pending_customers()
returns table (id uuid, member_id text, email text, full_name text, phone text, date_of_birth date, sex text,
               default_address text, email_confirmed boolean, created_at timestamptz, last_sign_in_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('customers.approve');
  return query
    select c.id, c.member_id::text, u.email::text, c.full_name, c.phone, c.date_of_birth, c.sex::text, c.default_address,
           u.email_confirmed_at is not null, c.created_at, u.last_sign_in_at
      from public.customer_accounts c
      join auth.users u on u.id = c.id
     where c.approval_status = 'pending'
       and not exists (select 1 from public.profiles p where p.id = c.id)
     order by c.created_at
     limit 500;
end;
$$;

create or replace function public.admin_approve_customer(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.customer_accounts;
begin
  perform private.require_permission('customers.approve');
  select * into v from public.customer_accounts where id = p_user_id for update;
  if not found or exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('not_found'); end if;
  if v.approval_status <> 'pending' then perform private.app_error('invalid_transition'); end if;
  update public.customer_accounts set approval_status = 'approved', approved_at = now(), approved_by = auth.uid() where id = p_user_id;
  perform private.audit('account_approved', 'customer_account', p_user_id::text, null, null, jsonb_build_object('user_id', v.member_id));
  perform private.enqueue_customer_email('customer_account_approved', 'account_approved:' || p_user_id, p_user_id,
    jsonb_build_object('name', v.full_name));
end;
$$;

-- Reject: block the email with the reason and return what the app needs to email the customer and delete
-- the account (the app does both right after, with the secret key, only after this succeeded).
create or replace function public.admin_reject_customer(p_user_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.customer_accounts;
  v_email text;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform private.require_permission('customers.approve');
  if char_length(v_reason) not between 5 and 500 then perform private.app_error('invalid_reason'); end if;
  select * into v from public.customer_accounts where id = p_user_id for update;
  if not found or exists (select 1 from public.profiles where id = p_user_id) then perform private.app_error('not_found'); end if;
  if v.approval_status <> 'pending' then perform private.app_error('invalid_transition'); end if;
  if exists (select 1 from public.orders where user_id = p_user_id) or exists (select 1 from public.wallet_topups where user_id = p_user_id) then
    perform private.app_error('has_orders');
  end if;
  select lower(email) into v_email from auth.users where id = p_user_id;
  insert into public.blocked_emails (email, reason) values (v_email, 'Account rejected: ' || left(v_reason, 480))
  on conflict (email) do update set reason = excluded.reason;
  perform private.audit('account_rejected', 'customer_account', p_user_id::text, null, null,
    jsonb_build_object('user_id', v.member_id, 'reason', v_reason));
  return jsonb_build_object('email', v_email, 'name', v.full_name, 'member_id', v.member_id);
end;
$$;

-- Accounts invited by the shop are approved at once (server only, after the inviting admin was checked).
create or replace function public.approve_invited_customer(p_user_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.customer_accounts set approval_status = 'approved', approved_at = now()
   where id = p_user_id and approval_status = 'pending'
$$;

revoke all on function public.admin_pending_customers() from public, anon;
revoke all on function public.admin_approve_customer(uuid) from public, anon;
revoke all on function public.admin_reject_customer(uuid, text) from public, anon;
revoke all on function public.approve_invited_customer(uuid) from public, anon, authenticated;
revoke all on function private.customer_pending_alert() from public;
grant execute on function public.admin_pending_customers() to authenticated;
grant execute on function public.admin_approve_customer(uuid) to authenticated;
grant execute on function public.admin_reject_customer(uuid, text) to authenticated;
grant execute on function public.approve_invited_customer(uuid) to service_role;

-- "New account waiting for approval" goes to the security group.
create or replace function private.telegram_group(p_event text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_event in ('security_event', 'security_alert', 'admin_action', 'security_test', 'promotion_alert', 'account_pending') then 'security'
    when p_event in ('low_stock', 'out_of_stock', 'stock_test') then 'stock'
    when p_event in ('receipt_record', 'receipts_test', 'excel_export') then 'receipts'
    when p_event in ('printing_document', 'printing_test') then 'printing'
    when p_event in ('support_ticket', 'support_reply', 'support_rating', 'support_test') then 'support'
    else 'orders'
  end
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261124000070_courier_earnings.sql
-- =============================================================================
-- 0070 COURIER APP: DETAILS, ON DUTY, EARNINGS (FIXED FEE), PAYOUTS, NOTIFICATIONS + ADMIN COURIERS
--   * courier_profiles: phone, vehicle, plate number, on duty; fee per delivery for this courier (optional).
--   * Fixed fee per delivered order (Admin → Couriers → Settings; default 100 ETB). Earned when the courier
--     delivers with the customer's code; paid out by the Super Admin ("Mark as paid") → payout record.
--   * Courier notifications (in the app): new delivery, delivery taken back, payment recorded.
--   * Admin (couriers.manage — Super Admin): couriers list, details, earnings, payouts, fee; dispatch list
--     of paid delivery orders without a courier (assigning still needs orders.manage).
-- =============================================================================

insert into public.admin_permissions (key, description)
values ('couriers.manage', 'Manage couriers: details, fee per delivery, earnings and payouts')
on conflict (key) do nothing;
insert into public.role_permissions (role_id, permission_key)
select r.id, 'couriers.manage' from public.admin_roles r where r.key = 'super_admin'
on conflict do nothing;

insert into public.website_settings (key, value, is_public)
values ('courier', '{"fee_per_delivery_etb": 100}', false)
on conflict (key) do nothing;

create table public.courier_profiles (
  profile_id       uuid primary key references public.profiles(id) on delete cascade,
  phone            text check (phone ~ '^\+251[79][0-9]{8}$'),
  vehicle          text not null default 'motorbike' check (vehicle in ('motorbike', 'bicycle', 'car', 'on_foot', 'other')),
  plate_number     text check (char_length(plate_number) <= 20),
  fee_override_etb numeric(10,2) check (fee_override_etb >= 0 and fee_override_etb <= 100000),
  on_duty          boolean not null default false,
  on_duty_since    timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create trigger courier_profiles_updated_at before update on public.courier_profiles
  for each row execute function private.set_updated_at();

create table public.courier_payouts (
  id             uuid primary key default gen_random_uuid(),
  courier_id     uuid not null references public.profiles(id) on delete restrict,
  amount_etb     numeric(12,2) not null check (amount_etb > 0),
  deliveries     integer not null check (deliveries > 0),
  reference      text check (char_length(reference) <= 80),
  note           text check (char_length(note) <= 300),
  paid_by        uuid references auth.users(id) on delete set null default auth.uid(),
  paid_at        timestamptz not null default now()
);
create index courier_payouts_courier_idx on public.courier_payouts (courier_id, paid_at desc);

create table public.courier_earnings (
  id          bigint generated always as identity primary key,
  courier_id  uuid not null references public.profiles(id) on delete restrict,
  order_id    uuid not null unique references public.orders(id) on delete restrict,
  order_number text not null,   -- shown to the courier (couriers cannot read the orders table)
  amount_etb  numeric(10,2) not null check (amount_etb >= 0),
  earned_at   timestamptz not null default now(),
  payout_id   uuid references public.courier_payouts(id) on delete restrict
);
create index courier_earnings_courier_idx on public.courier_earnings (courier_id, earned_at desc);
create index courier_earnings_unpaid_idx on public.courier_earnings (courier_id) where payout_id is null;

create table public.courier_notifications (
  id          bigint generated always as identity primary key,
  courier_id  uuid not null references public.profiles(id) on delete cascade,
  kind        text not null check (kind in ('assigned', 'unassigned', 'payout', 'message')),
  title       text not null check (char_length(title) <= 120),
  body        text check (char_length(body) <= 500),
  order_id    uuid references public.orders(id) on delete set null,
  created_at  timestamptz not null default now(),
  read_at     timestamptz
);
create index courier_notifications_courier_idx on public.courier_notifications (courier_id, id desc);

-- RLS: only through the functions below (couriers see their own rows; couriers.manage sees all).
alter table public.courier_profiles enable row level security;
alter table public.courier_payouts enable row level security;
alter table public.courier_earnings enable row level security;
alter table public.courier_notifications enable row level security;
revoke all on public.courier_profiles, public.courier_payouts, public.courier_earnings, public.courier_notifications from anon, authenticated;
grant select on public.courier_profiles, public.courier_payouts, public.courier_earnings, public.courier_notifications to authenticated;
create policy courier_profiles_read on public.courier_profiles for select to authenticated
  using (profile_id = (select auth.uid()) or (select private.has_permission('couriers.manage')));
create policy courier_payouts_read on public.courier_payouts for select to authenticated
  using (courier_id = (select auth.uid()) or (select private.has_permission('couriers.manage')));
create policy courier_earnings_read on public.courier_earnings for select to authenticated
  using (courier_id = (select auth.uid()) or (select private.has_permission('couriers.manage')));
create policy courier_notifications_read on public.courier_notifications for select to authenticated
  using (courier_id = (select auth.uid()));

create or replace function private.courier_fee(p_courier uuid)
returns numeric
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select fee_override_etb from public.courier_profiles where profile_id = p_courier),
                  (private.setting('courier') ->> 'fee_per_delivery_etb')::numeric, 0)
$$;

create or replace function private.notify_courier(p_courier uuid, p_kind text, p_title text, p_body text, p_order uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.courier_notifications (courier_id, kind, title, body, order_id)
  select p_courier, p_kind, left(p_title, 120), left(p_body, 500), p_order where p_courier is not null
$$;

-- Assign / take back: also tells the courier(s) in the app.
create or replace function public.admin_assign_courier(p_order_id uuid, p_courier uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders;
  v_old uuid;
begin
  perform private.require_permission('orders.manage');
  select * into v from public.orders where id = p_order_id for update;
  if not found then perform private.app_error('not_found'); end if;
  if v.fulfillment_method <> 'delivery' then perform private.app_error('invalid_request', 'pickup order'); end if;
  if v.status not in ('confirmed', 'processing', 'out_for_delivery') then perform private.app_error('invalid_transition'); end if;
  if p_courier is not null and not exists (
       select 1 from public.profiles p join public.admin_roles r on r.id = p.role_id
        where p.id = p_courier and p.is_active and r.key = 'courier') then
    perform private.app_error('invalid_assignee');
  end if;
  if p_courier is null and v.status = 'out_for_delivery' then perform private.app_error('invalid_transition', 'on the way'); end if;
  v_old := v.courier_id;
  update public.orders
     set courier_id = p_courier,
         courier_assigned_at = case when p_courier is null then null else now() end,
         delivery_code = case when p_courier is null then delivery_code else coalesce(delivery_code, lpad((floor(random() * 10000))::int::text, 4, '0')) end,
         delivery_code_tries = 0
   where id = v.id
  returning * into v;
  perform private.audit(case when p_courier is null then 'courier_unassigned' else 'courier_assigned' end, 'order', v.id::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('order_number', v.order_number, 'courier_user_id', private.member_of(p_courier))));
  if v_old is not null and v_old is distinct from p_courier then
    perform private.notify_courier(v_old, 'unassigned', 'Delivery ' || v.order_number || ' was taken back', 'The office gave it to someone else or will deliver it another way.', v.id);
  end if;
  if p_courier is not null and v_old is distinct from p_courier then
    perform private.notify_courier(p_courier, 'assigned', 'New delivery: ' || v.order_number,
      coalesce(v.city, '') || coalesce(' — ' || v.address_line, ''), v.id);
  end if;
  if p_courier is not null then perform private.delivery_event(v, 'assigned'); end if;
end;
$$;

-- Delivered with the right code → earning recorded (fee at that moment).
create or replace function public.courier_deliver(p_order_id uuid, p_code text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v public.orders := private.courier_order(p_order_id);
begin
  if v.status <> 'out_for_delivery' then perform private.app_error('invalid_transition'); end if;
  if v.delivery_code_tries >= 5 then perform private.app_error('delivery_locked'); end if;
  if v.delivery_code is null or coalesce(btrim(p_code), '') <> v.delivery_code then
    update public.orders set delivery_code_tries = delivery_code_tries + 1 where id = v.id returning * into v;
    if v.delivery_code_tries >= 5 then
      perform private.audit('delivery_code_locked', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number));
      perform private.delivery_event(v, 'code_locked');
    end if;
    return false;
  end if;
  perform private.set_status_note('Delivered — customer''s code checked by the courier');
  update public.orders set status = 'completed', delivered_at = now() where id = v.id returning * into v;
  insert into public.courier_earnings (courier_id, order_id, order_number, amount_etb) values (v.courier_id, v.id, v.order_number, private.courier_fee(v.courier_id))
  on conflict (order_id) do nothing;
  perform private.audit('delivery_completed', 'order', v.id::text, null, null, jsonb_build_object('order_number', v.order_number));
  perform private.delivery_event(v, 'delivered');
  return true;
end;
$$;

-- ------------------------------------------------------------ courier app
create or replace function public.courier_me()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  perform private.require_permission('deliveries.own');
  return (
    select jsonb_build_object(
      'full_name', p.full_name, 'member_id', private.member_of(v_uid), 'email', (select email from auth.users where id = v_uid),
      'phone', cp.phone, 'vehicle', coalesce(cp.vehicle, 'motorbike'), 'plate_number', cp.plate_number,
      'on_duty', coalesce(cp.on_duty, false), 'on_duty_since', cp.on_duty_since, 'fee_etb', private.courier_fee(v_uid),
      'today_delivered', (select count(*) from public.courier_earnings e where e.courier_id = v_uid and e.earned_at >= date_trunc('day', now() at time zone 'Europe/Warsaw') at time zone 'Europe/Warsaw'),
      'today_etb', (select coalesce(sum(amount_etb), 0) from public.courier_earnings e where e.courier_id = v_uid and e.earned_at >= date_trunc('day', now() at time zone 'Europe/Warsaw') at time zone 'Europe/Warsaw'),
      'month_etb', (select coalesce(sum(amount_etb), 0) from public.courier_earnings e where e.courier_id = v_uid and e.earned_at >= date_trunc('month', now() at time zone 'Europe/Warsaw') at time zone 'Europe/Warsaw'),
      'unpaid_etb', (select coalesce(sum(amount_etb), 0) from public.courier_earnings e where e.courier_id = v_uid and e.payout_id is null),
      'total_delivered', (select count(*) from public.courier_earnings e where e.courier_id = v_uid),
      'unread', (select count(*) from public.courier_notifications n where n.courier_id = v_uid and n.read_at is null),
      'active', (select count(*) from public.orders o where o.courier_id = v_uid and o.status in ('confirmed', 'processing', 'out_for_delivery')))
    from public.profiles p left join public.courier_profiles cp on cp.profile_id = p.id
    where p.id = v_uid);
end;
$$;

create or replace function public.courier_set_duty(p_on boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('deliveries.own');
  insert into public.courier_profiles (profile_id, on_duty, on_duty_since)
  values ((select auth.uid()), p_on, case when p_on then now() end)
  on conflict (profile_id) do update set on_duty = excluded.on_duty, on_duty_since = excluded.on_duty_since;
  perform private.audit(case when p_on then 'courier_on_duty' else 'courier_off_duty' end, 'profiles', (select auth.uid())::text);
end;
$$;

create or replace function public.courier_update_details(p_phone text, p_vehicle text, p_plate text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('deliveries.own');
  insert into public.courier_profiles (profile_id, phone, vehicle, plate_number)
  values ((select auth.uid()), nullif(btrim(p_phone), ''), coalesce(nullif(p_vehicle, ''), 'motorbike'), nullif(upper(btrim(p_plate)), ''))
  on conflict (profile_id) do update set phone = excluded.phone, vehicle = excluded.vehicle, plate_number = excluded.plate_number;
  perform private.audit('courier_details_updated', 'profiles', (select auth.uid())::text);
end;
$$;

create or replace function public.courier_mark_notifications_read()
returns void
language sql
security definer
set search_path = ''
as $$
  update public.courier_notifications set read_at = now() where courier_id = (select auth.uid()) and read_at is null
$$;

-- ------------------------------------------------------------ admin
create or replace function public.admin_couriers()
returns table (id uuid, member_id text, full_name text, email text, is_active boolean, phone text, vehicle text, plate_number text,
               on_duty boolean, on_duty_since timestamptz, fee_etb numeric, fee_override_etb numeric, active_deliveries bigint,
               delivered_month bigint, delivered_total bigint, failed_month bigint, unpaid_etb numeric, last_delivered_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not (private.has_permission('couriers.manage') or private.has_permission('orders.manage')) then perform private.app_error('forbidden'); end if;
  return query
    select p.id, private.member_of(p.id), p.full_name, u.email::text, p.is_active, cp.phone, coalesce(cp.vehicle, 'motorbike'), cp.plate_number,
           coalesce(cp.on_duty, false), cp.on_duty_since, private.courier_fee(p.id), cp.fee_override_etb,
           (select count(*) from public.orders o where o.courier_id = p.id and o.status in ('confirmed', 'processing', 'out_for_delivery')),
           (select count(*) from public.courier_earnings e where e.courier_id = p.id and e.earned_at >= date_trunc('month', now() at time zone 'Europe/Warsaw') at time zone 'Europe/Warsaw'),
           (select count(*) from public.courier_earnings e where e.courier_id = p.id),
           (select count(*) from public.audit_logs a where a.actor_id = p.id and a.action = 'delivery_failed'
              and a.created_at >= date_trunc('month', now() at time zone 'Europe/Warsaw') at time zone 'Europe/Warsaw'),
           case when private.has_permission('couriers.manage') then (select coalesce(sum(e.amount_etb), 0) from public.courier_earnings e where e.courier_id = p.id and e.payout_id is null) end,
           (select max(e.earned_at) from public.courier_earnings e where e.courier_id = p.id)
      from public.profiles p
      join public.admin_roles r on r.id = p.role_id and r.key = 'courier'
      join auth.users u on u.id = p.id
      left join public.courier_profiles cp on cp.profile_id = p.id
     where p.removed_at is null
     order by coalesce(cp.on_duty, false) desc, p.full_name;
end;
$$;

create or replace function public.admin_update_courier(p_courier uuid, p_phone text, p_vehicle text, p_plate text, p_fee_override numeric)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('couriers.manage');
  if not exists (select 1 from public.profiles p join public.admin_roles r on r.id = p.role_id where p.id = p_courier and r.key = 'courier') then
    perform private.app_error('not_found');
  end if;
  insert into public.courier_profiles (profile_id, phone, vehicle, plate_number, fee_override_etb)
  values (p_courier, nullif(btrim(p_phone), ''), coalesce(nullif(p_vehicle, ''), 'motorbike'), nullif(upper(btrim(p_plate)), ''), p_fee_override)
  on conflict (profile_id) do update set phone = excluded.phone, vehicle = excluded.vehicle, plate_number = excluded.plate_number,
                                         fee_override_etb = excluded.fee_override_etb;
  perform private.audit('courier_details_updated', 'profiles', p_courier::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('fee_override_etb', p_fee_override)));
end;
$$;

create or replace function public.admin_set_courier_fee(p_fee numeric)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('couriers.manage');
  if p_fee is null or p_fee < 0 or p_fee > 100000 then perform private.app_error('invalid_amount'); end if;
  insert into public.website_settings (key, value, is_public) values ('courier', jsonb_build_object('fee_per_delivery_etb', p_fee), false)
  on conflict (key) do update set value = public.website_settings.value || jsonb_build_object('fee_per_delivery_etb', p_fee);
  perform private.audit('courier_fee_set', 'website_settings', 'courier', null, null, jsonb_build_object('fee_per_delivery_etb', p_fee));
end;
$$;

-- Pay all unpaid earnings of a courier (cash / transfer done outside the website) → one payout record.
create or replace function public.admin_pay_courier(p_courier uuid, p_reference text default null, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sum numeric(12,2);
  v_n integer;
  v_id uuid;
begin
  perform private.require_permission('couriers.manage');
  if not private.mfa_verified() then perform private.app_error('forbidden'); end if;
  perform 1 from public.courier_earnings where courier_id = p_courier and payout_id is null for update;
  select coalesce(sum(amount_etb), 0), count(*) into v_sum, v_n from public.courier_earnings where courier_id = p_courier and payout_id is null;
  if v_n = 0 or v_sum <= 0 then perform private.app_error('invalid_amount'); end if;
  insert into public.courier_payouts (courier_id, amount_etb, deliveries, reference, note)
  values (p_courier, v_sum, v_n, nullif(btrim(coalesce(p_reference, '')), ''), nullif(btrim(coalesce(p_note, '')), ''))
  returning id into v_id;
  update public.courier_earnings set payout_id = v_id where courier_id = p_courier and payout_id is null;
  perform private.notify_courier(p_courier, 'payout', 'Payment recorded: ' || v_sum || ' ETB',
    v_n || ' deliveries' || coalesce(' · ref ' || nullif(btrim(coalesce(p_reference, '')), ''), ''), null);
  perform private.audit('courier_paid', 'profiles', p_courier::text, null, null,
    jsonb_build_object('amount_etb', v_sum, 'deliveries', v_n, 'reference', p_reference, 'courier_user_id', private.member_of(p_courier)));
  return jsonb_build_object('payout_id', v_id, 'amount_etb', v_sum, 'deliveries', v_n);
end;
$$;

-- Paid delivery orders still needing a courier (new, or back after "couldn't deliver").
create or replace function public.admin_dispatch_orders()
returns table (order_id uuid, order_number text, status text, city text, address_line text, total_etb numeric, paid_at timestamptz,
               courier_id uuid, delivery_attempts integer, fail_reason text, items integer)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_permission('orders.manage');
  return query
    select o.id, o.order_number::text, o.status::text, o.city, o.address_line, o.total_etb, o.payment_verified_at, o.courier_id,
           o.delivery_attempts, o.delivery_fail_reason, (select coalesce(sum(i.quantity), 0)::int from public.order_items i where i.order_id = o.id)
      from public.orders o
     where o.fulfillment_method = 'delivery' and o.status in ('confirmed', 'processing')
       and o.payment_status = 'verified'
       and (o.courier_id is null or o.delivery_failed_at is not null)
     order by o.payment_verified_at nulls last
     limit 200;
end;
$$;

-- Reset test data (Admin → Export everything / reset) also clears courier earnings, payouts and notifications.
create or replace function public.admin_reset_test_data(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_counts jsonb;
  n_orders int; n_jobs int; n_customers int; n_accounts int; n_topups int; n_reviews int; n_audit int;
begin
  perform private.require_permission('data.manage');
  if p_confirm is distinct from public.admin_reset_phrase() then
    perform private.app_error('invalid_request', 'confirmation');
  end if;
  if not exists (select 1 from public.audit_logs where action = 'export_all' and actor_id = v_uid and created_at > now() - interval '30 minutes') then
    perform private.app_error('invalid_request', 'export_first');
  end if;
  -- One reset at a time.
  perform pg_advisory_xact_lock(hashtext('admin_reset_test_data'));

  select count(*) into n_orders from public.orders;
  select count(*) into n_jobs from public.printing_jobs;
  select count(*) into n_customers from public.customers;
  select count(*) into n_accounts from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id);
  select count(*) into n_topups from public.wallet_topups;
  select count(*) into n_reviews from public.product_reviews;

  perform set_config('app.data_reset', 'on', true);
  perform set_config('app.audit_purge', 'on', true);

  -- ("where true": Supabase refuses DELETE without WHERE on API calls)
  delete from public.inventory_movements where order_id is not null;   -- stock levels stay as they are now
  delete from public.wallet_ledger where true;
  delete from public.wallet_topups where true;
  delete from public.product_reviews where true;
  delete from public.stock_alerts where true;
  delete from public.customer_carts where true;
  delete from public.push_subscriptions where true;
  delete from public.courier_notifications where true;  -- courier app (0070): before the orders they point to
  delete from public.courier_earnings where true;
  delete from public.courier_payouts where true;
  delete from public.orders where true;                -- items, payments, history, notes
  delete from public.printing_jobs where true;         -- files, history
  delete from public.customers where true;             -- addresses
  delete from public.notifications_outbox where true;
  delete from public.rate_limits where true;
  delete from public.security_events where true;
  -- Before the accounts: their activity entries would otherwise need an (forbidden) update.
  delete from public.audit_logs where action not in ('audit_cleared', 'data_reset');
  get diagnostics n_audit = row_count;
  -- Customer sign-in accounts (staff are kept).
  delete from auth.users u where not exists (select 1 from public.profiles p where p.id = u.id);

  -- New numbering for the real shop.
  alter sequence public.order_number_seq restart with 10001;
  alter sequence public.print_job_number_seq restart with 10001;
  alter sequence public.wallet_topup_number_seq restart with 1001;

  perform set_config('app.data_reset', 'off', true);
  perform set_config('app.audit_purge', 'off', true);

  v_counts := jsonb_build_object('orders', n_orders, 'printing_jobs', n_jobs, 'customers', n_customers, 'customer_accounts', n_accounts,
                                 'wallet_topups', n_topups, 'reviews', n_reviews, 'activity_entries', n_audit, 'reset_at', now());
  perform private.audit('data_reset', 'data', null, null, null, v_counts);
  return v_counts;
end;
$$;

